"""도메인 DB 레이어 — 엔진 state.py 에서 이동한 도메인 테이블 + 함수 (v3.82 U3c · P2 W2 갱신).

소유: smb_*/mail_*/asset_owner/scan/screenshot(=skill_smb) · web_target_domain/dev_web_*(=skill_dev_web) ·
github_*(=skill_github) · confluence_*(=skill_confluence) — DDL bootstrap 포함.
★ platform 5종(control_flag/pipeline_heartbeat/pipeline_run/service_reply_message/devops_target)은 **코어 소유**
(67b8bd5 provision) — 이 모듈은 CREATE 하지 않고 baseline search_path(…, platform, …)로 **접근만** 한다(P2 W2 락스텝).

연결은 엔진 코어 `secu_agent.state.connect()` 풀을 재사용하고, 이 모듈의
`connect()` 가 도메인 schema 를 lazy 1회 보장한다. id-less 테이블(asset_owner)
은 코어 connection 레이어에 register_idless_table 로 등록 (INSERT RETURNING
자동부착 제외 유지).

claimed_by 등 코어 chat_session id 참조는 opaque id (cross-모듈 FK 없음).
python_exec 의 `state` 자동 바인딩으로는 더 이상 도메인 함수에 접근할 수 없다 —
skills 스니펫은 이 모듈을 사용한다 (재부착 가이드 참조).
"""
from __future__ import annotations

import ipaddress
import json
