# 이하: 엔진 state.py 원형 이동분 (S1 cred/asset_owner/scan/smb 파이프라인,
# S2 finding_index SMB reindex, S3 memory_recall_for_share, S4 sweep targets,
# S5 도메인 entity_timeline)
# ============================================================

def cred_add(name: str, username: str, password_ref: str) -> int:
    """password_ref는 'env:VAR_NAME' 형식만 허용. 평문 비번 절대 X."""
    if not password_ref.startswith("env:"):
        raise ValueError("password_ref must be 'env:VAR_NAME' (no plaintext stored)")
    with connect() as c:
        cur = c.execute(
            "INSERT INTO smb_credential(name, username, password_ref, created_at) "
            "VALUES (?, ?, ?, ?)",
            (name, username, password_ref, time.time()),
        )
        return int(cur.lastrowid)


def cred_list(enabled_only: bool = False) -> list[dict[str, Any]]:
    with connect() as c:
        q = "SELECT * FROM smb_credential"
        if enabled_only:
            q += " WHERE enabled=1"
        q += " ORDER BY id"
        rows = c.execute(q).fetchall()
        return [{k: r[k] for k in r.keys()} for r in rows]


def cred_set_enabled(cred_id: int, enabled: bool) -> None:
    with connect() as c:
        c.execute("UPDATE smb_credential SET enabled=? WHERE id=?",
                  (1 if enabled else 0, cred_id))


def cred_get(cred_id: int) -> dict[str, Any] | None:
    with connect() as c:
        r = c.execute("SELECT * FROM smb_credential WHERE id=?", (cred_id,)).fetchone()
        return {k: r[k] for k in r.keys()} if r else None


def cred_pick_for_scan() -> dict[str, Any] | None:
    """enabled=True 중 last_used 가장 오래된 것 (없으면 NULL이 먼저)."""
    with connect() as c:
        r = c.execute(
            "SELECT * FROM smb_credential WHERE enabled=1 "
            "ORDER BY (last_used IS NOT NULL), last_used ASC LIMIT 1"
        ).fetchone()
        return {k: r[k] for k in r.keys()} if r else None


def cred_resolve_password(cred: dict[str, Any]) -> str | None:
    """password_ref → 실제 비번 (env에서). DB나 로그에 평문 절대 안 나타남."""
    ref = cred.get("password_ref", "")
    if ref.startswith("env:"):
        return os.environ.get(ref[4:])
    return None


def cred_touch(cred_id: int) -> None:
    with connect() as c:
        c.execute("UPDATE smb_credential SET last_used=? WHERE id=?", (time.time(), cred_id))


# ============================================================
# asset_owner — IP → 담당자 enrichment cache
# ============================================================

def _owner_email_from_user_id(user_id: str | None) -> str | None:
    uid = str(user_id or "").strip()
    if not uid:
        return None
    if "@" in uid:
        return uid.lower()
    return f"{uid}@samsung.com"


def _asset_owner_row(row: Any) -> dict[str, Any] | None:
    if row is None:
        return None
    return {
        "ip": row["ip"],
        "user_id": row["user_id"],
        "user_name": row["user_name"],
        "user_dept": row["user_dept"],
        "email": row["email"],
        "source": row["source"],
        "updated_at": row["updated_at"],
    }


def asset_owner_upsert(
    ip: str,
    *,
    user_id: str | None = None,
    user_name: str | None = None,
    user_dept: str | None = None,
    email: str | None = None,
    source: str = "splunk",
) -> dict[str, Any]:
    norm_ip = str(ip or "").strip()
    if not norm_ip:
        raise ValueError("ip is required")
    uid = str(user_id or "").strip() or None
    name = str(user_name or "").strip() or None
    dept = str(user_dept or "").strip() or None
    mail = str(email or "").strip().lower() or _owner_email_from_user_id(uid)
    src = str(source or "splunk").strip() or "splunk"
    now = time.time()
    with connect() as c:
        c.execute(
            "INSERT INTO asset_owner("
            "ip, user_id, user_name, user_dept, email, source, updated_at"
            ") VALUES (?, ?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(ip) DO UPDATE SET "
            "user_id=excluded.user_id, user_name=excluded.user_name, "
            "user_dept=excluded.user_dept, email=excluded.email, "
            "source=excluded.source, updated_at=excluded.updated_at",
            (norm_ip, uid, name, dept, mail, src, now),
        )
    owner = asset_owner_get(norm_ip)
    if owner is None:
        raise RuntimeError(f"asset owner upsert failed for {norm_ip}")
    return owner


def asset_owner_get(ip: str) -> dict[str, Any] | None:
    norm_ip = str(ip or "").strip()
    if not norm_ip:
        return None
    with connect() as c:
        row = c.execute(
            "SELECT * FROM asset_owner WHERE ip=?", (norm_ip,),
        ).fetchone()
    return _asset_owner_row(row)


def asset_owner_list(limit: int = 100) -> list[dict[str, Any]]:
    lim = max(1, min(int(limit), 1000))
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM asset_owner ORDER BY updated_at DESC, ip LIMIT ?",
            (lim,),
        ).fetchall()
    return [d for row in rows if (d := _asset_owner_row(row)) is not None]


# ── employee_directory — Knox ID → 이름·부서·직급 (횡단 캐시) ──────────────────

def _employee_row(row: Any) -> dict[str, Any] | None:
    if row is None:
        return None
    d = dict(row)
    return d or None


def employee_directory_upsert(
    knox_id: str,
    *,
    full_name: str | None = None,
    department: str | None = None,
    en_department: str | None = None,
    title: str | None = None,
    employee_number: str | None = None,
    source: str = "knox",
) -> dict[str, Any]:
    """Knox ID 기준 upsert. knox_id 는 **메일 local part**다(주소를 그대로 넣지 마라)."""
    uid = str(knox_id or "").strip().lower()
    if not uid:
        raise ValueError("knox_id is required")
    if "@" in uid:
        raise ValueError(f"knox_id 에 메일 주소가 들어왔다: {uid!r} — local part 만 넣어라")
    now = time.time()
    with connect() as c:
        c.execute(
            "INSERT INTO employee_directory("
            "knox_id, full_name, department, en_department, title, employee_number,"
            " source, updated_at"
            ") VALUES (?, ?, ?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(knox_id) DO UPDATE SET "
            "full_name=excluded.full_name, department=excluded.department, "
            "en_department=excluded.en_department, title=excluded.title, "
            "employee_number=excluded.employee_number, source=excluded.source, "
            "updated_at=excluded.updated_at",
            (uid, str(full_name or "").strip() or None,
             str(department or "").strip() or None,
             str(en_department or "").strip() or None,
             str(title or "").strip() or None,
             str(employee_number or "").strip() or None,
             str(source or "knox").strip() or "knox", now),
        )
    emp = employee_directory_get(uid)
    if emp is None:
        raise RuntimeError(f"employee upsert failed for {uid}")
    return emp


def employee_directory_get(knox_id: str) -> dict[str, Any] | None:
    uid = str(knox_id or "").strip().lower()
    if not uid:
        return None
    with connect() as c:
        row = c.execute(
            "SELECT * FROM employee_directory WHERE knox_id=?", (uid,),
        ).fetchone()
    return _employee_row(row)


# ── github_repo_owner — 저장소 → 담당자 ───────────────────────────────────────
#: 판정 근거. 화면·메일이 "확정" 과 "추정" 을 구분해 보여줘야 한다.
#:
#:   repo_login      저장소 이름이 곧 그 사람이다 — **확정**
#:   commit_author   커밋 작성자의 **사내 메일**이 Knox 에서 확인됐다 — 거의 확정
#:                   (2026-09-01 추가. 그 저장소에 실제로 코드를 넣은 사람이고,
#:                    주소를 우리가 조립한 게 아니라 git 이 기록한 값이다.)
#:   top_contributor 커밋 화면의 상위 기여자 — **추정**
GITHUB_REPO_OWNER_SOURCES = ("repo_login", "commit_author", "top_contributor")


def github_repo_owner_upsert(
    repo: str, *, knox_id: str | None, login: str | None, source: str,
) -> dict[str, Any]:
    name = str(repo or "").strip()
    if not name:
        raise ValueError("repo is required")
    src = str(source or "").strip()
    if src not in GITHUB_REPO_OWNER_SOURCES:
        raise ValueError(f"unknown source: {src!r} (허용: {GITHUB_REPO_OWNER_SOURCES})")
    now = time.time()
    with connect() as c:
        c.execute(
            "INSERT INTO github_repo_owner(repo, knox_id, login, source, updated_at) "
            "VALUES (?, ?, ?, ?, ?) "
            "ON CONFLICT(repo) DO UPDATE SET knox_id=excluded.knox_id, "
            "login=excluded.login, source=excluded.source, updated_at=excluded.updated_at",
            (name, str(knox_id or "").strip().lower() or None,
             str(login or "").strip() or None, src, now),
        )
    got = github_repo_owner_get(name)
    if got is None:
        raise RuntimeError(f"repo owner upsert failed for {name}")
    return got


def github_repo_owner_get(repo: str) -> dict[str, Any] | None:
    name = str(repo or "").strip()
    if not name:
        return None
    with connect() as c:
        row = c.execute(
            "SELECT * FROM github_repo_owner WHERE repo=?", (name,),
        ).fetchone()
    return _employee_row(row)


# ============================================================
# scan lifecycle
# ============================================================

def scan_start(kind: str, subnets: list[str]) -> int:
    with connect() as c:
        cur = c.execute(
            "INSERT INTO scan(kind, started_at, subnets) VALUES (?, ?, ?)",
            (kind, time.time(), json.dumps(subnets)),
        )
        return int(cur.lastrowid)


def scan_finish(
    scan_id: int, *, alive_total: int, accessible_total: int,
    new_count: int, closed_count: int,
) -> None:
    with connect() as c:
        c.execute(
            "UPDATE scan SET finished_at=?, alive_total=?, accessible_total=?, "
            "new_count=?, closed_count=? WHERE id=?",
            (time.time(), alive_total, accessible_total, new_count, closed_count, scan_id),
        )


# ============================================================
# smb_share
# ============================================================

def upsert_smb_share(
    scan_id: int, subnet: str, host: str, share: str,
    *,
    null_login_ok: bool | None = None,
    guest_login_ok: bool | None = None,
    auth_login_ok: bool | None = None,
    auth_credential_id: int | None = None,
    share_read: bool = False,
    share_write: bool = False,
    access_modes: dict[str, Any] | None = None,
) -> tuple[str, int]:
    """결과: (new|updated, share_id).

    새 주간 cycle 에 다시 보인 share 는 같은 row/finding history 를 보존하되 이번
    cycle 운영 상태만 pending 부터 다시 시작한다.
    """
    fp = f"{host}:{share}"
    now = time.time()
    cycle_key = smb_current_cycle_key()
    access_modes_json = (
        json.dumps(access_modes, ensure_ascii=False, sort_keys=True)
        if access_modes is not None else None
    )
    with connect() as c:
        row = c.execute(
            "SELECT id, status, cycle_key, null_login_ok, guest_login_ok, auth_login_ok, "
            "auth_credential_id, share_read, share_write, access_modes "
            "FROM smb_share WHERE fingerprint=?",
            (fp,),
        ).fetchone()
        if row is None:
            cur = c.execute(
                "INSERT INTO smb_share(fingerprint, subnet, host, share, first_seen, last_seen, "
                "last_scan_id, status, null_login_ok, guest_login_ok, auth_login_ok, "
                "auth_credential_id, share_read, share_write, access_modes, "
                "cycle_key, cycle_seen_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (fp, subnet, host, share, now, now, scan_id,
                 _b(null_login_ok), _b(guest_login_ok), _b(auth_login_ok),
                 auth_credential_id, int(share_read), int(share_write), access_modes_json,
                 cycle_key, now),
            )
            return "new", int(cur.lastrowid)
        new_access = (
            _b(null_login_ok),
            _b(guest_login_ok),
            _b(auth_login_ok),
            auth_credential_id,
            int(share_read),
            int(share_write),
            access_modes_json,
        )
        old_access = (
            row["null_login_ok"],
            row["guest_login_ok"],
            row["auth_login_ok"],
            row["auth_credential_id"],
            row["share_read"],
            row["share_write"],
            row["access_modes"],
        )
        is_new_cycle = row["cycle_key"] != cycle_key
        access_changed = not is_new_cycle and old_access != new_access
        reset_for_work = is_new_cycle or (
            access_changed and row["status"] not in ("pending", "in_progress")
        )
        new_status = "pending" if reset_for_work or row["status"] == "closed" else row["status"]
        c.execute(
            "UPDATE smb_share SET last_seen=?, last_scan_id=?, subnet=?, status=?, "
            "null_login_ok=?, guest_login_ok=?, auth_login_ok=?, "
            "auth_credential_id=?, share_read=?, share_write=?, access_modes=?, "
            # ★ 2026-08-29: 무조건 NULL 이었다. 스윕은 같은 cycle 안에서도 share 를
            #   여러 번 다시 본다(서브넷별 점진 스윕) — 그때마다 `retry_after` 가
            #   지워져 "덜 훑었으니 8시간 뒤 다시 봐라" 예약이 남을 수가 없었다.
            #   실측: 미스캔 파일을 안은 채 닫힌 공유 68개 / 115,388건, 그중
            #   27~48개가 `retry_after` NULL. 이제 **새 cycle/접근권 변화** 때만
            #   지운다 — 그때는 어차피 status 도 pending 으로 되돌아간다.
            "retry_after=CASE WHEN ? THEN NULL ELSE retry_after END, "
            "last_error_kind=CASE WHEN ? THEN NULL ELSE last_error_kind END, "
            "last_error=CASE WHEN ? THEN NULL ELSE last_error END, "
            "cycle_key=?, cycle_seen_at=?, "
            "cycle_walk_done_at=CASE WHEN ? THEN NULL ELSE cycle_walk_done_at END, "
            "claimed_by=CASE WHEN ? THEN NULL ELSE claimed_by END, "
            "claimed_at=CASE WHEN ? THEN NULL ELSE claimed_at END, "
            "walk_done_at=CASE WHEN ? THEN NULL ELSE walk_done_at END, "
            "processed_at=CASE WHEN ? THEN NULL ELSE processed_at END "
            "WHERE id=?",
            (now, scan_id, subnet, new_status,
             _b(null_login_ok), _b(guest_login_ok), _b(auth_login_ok),
             auth_credential_id, int(share_read), int(share_write), access_modes_json,
             reset_for_work, reset_for_work, reset_for_work,   # retry_after/error 2종
             cycle_key, now, reset_for_work,
             reset_for_work, reset_for_work, reset_for_work, reset_for_work, row["id"]),
        )
        return "updated", int(row["id"])


def _b(v: bool | None) -> int | None:
    if v is None:
        return None
    return 1 if v else 0


def close_unseen_since(scan_id: int, *, subnets: list[str] | None = None) -> int:
    """이번 scan 에서 안 보인 share 를 closed 로.

    subnets 지정 시 **그 서브넷 범위 안에서만** close (v3.72: per-subnet 점진
    스윕에서 다른 서브넷 share 를 닫아버리지 않도록 — 스윕 안 한 subnet 은 그대로).
    None 이면 전역 (full discovery 의 기존 동작).
    """
    sql = (
        "UPDATE smb_share SET status='closed' "
        "WHERE last_scan_id IS NOT NULL AND last_scan_id<>? "
        "  AND status IN ('pending','walked','triaged_completed','triaged_errored','ignored')"
    )
    args: list[Any] = [scan_id]
    if subnets is not None:
        norm = [_normalize_cidr(s) for s in subnets]
        if not norm:
            return 0
        sql += " AND subnet IN (" + ",".join("?" for _ in norm) + ")"
        args.extend(norm)
    with connect() as c:
        cur = c.execute(sql, args)
        return cur.rowcount


def share_set_status(share_id: int, status: str, **fields: Any) -> None:
    _validate_column_names(fields.keys())
    sets = ["status=?"]
    args: list[Any] = [status]
    # v3.60: terminal(=in_progress 가 아닌) 전이 시 host-level claim 자동 해제.
    # caller 가 명시적으로 넘긴 값은 존중.
    if status != "in_progress":
        if "claimed_by" not in fields:
            sets.append("claimed_by=?")
            args.append(None)
        if "claimed_at" not in fields:
            sets.append("claimed_at=?")
            args.append(None)
    if status in {"walked", "listing_reviewed", "triaged_completed", "triaged_errored", "ignored"}:
        if "cycle_key" not in fields:
            sets.append("cycle_key=?")
            args.append(smb_current_cycle_key())
        if "cycle_walk_done_at" not in fields:
            sets.append("cycle_walk_done_at=?")
            args.append(fields.get("walk_done_at") or time.time())
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(share_id)
    with connect() as c:
        c.execute(f"UPDATE smb_share SET {', '.join(sets)} WHERE id=?", args)


def share_mark_excluded(share_id: int, reason: str, *, summary: str | None = None) -> None:
    fields: dict[str, Any] = {
        "excluded_reason": str(reason or "excluded"),
        "excluded_at": time.time(),
    }
    if summary is not None:
        fields["summary"] = summary
    share_set_status(share_id, "ignored", **fields)


def share_mark_exception(
    share_id: int,
    *,
    reason: str,
    thread_id: int | None = None,
    approved_by: str | None = None,
) -> dict[str, Any] | None:
    """HITL 승인된 share 단위 조치 예외를 기록하고 큐에서 제외한다."""
    clean_reason = str(reason or "").strip()[:1000] or "HITL approved exception"
    now = time.time()
    share_set_status(
        share_id,
        "ignored",
        excluded_reason="exception",
        excluded_at=now,
        exception_reason=clean_reason,
        exception_thread_id=thread_id,
        exception_approved_by=str(approved_by or "operator")[:120],
        exception_at=now,
        summary=f"조치 예외 승인: {clean_reason}",
    )
    with connect() as c:
        row = c.execute("SELECT * FROM smb_share WHERE id=?", (share_id,)).fetchone()
    return {k: row[k] for k in row.keys()} if row else None


# v3.60: SMB host-level atomic claim (web_target_claim_next 대응).
SMB_CLAIM_STALE_SECONDS = 1800  # 30분 — hang 한 세션의 host 점유 회수
SMB_COMMUNICATION_RETRY_SECONDS = 8 * 3600


def smb_communication_retry_seconds() -> float:
    raw = os.environ.get("SMB_COMMUNICATION_RETRY_SECONDS", "")
    try:
        value = float(raw)
    except ValueError:
        return float(SMB_COMMUNICATION_RETRY_SECONDS)
    return value if value > 0 else float(SMB_COMMUNICATION_RETRY_SECONDS)


def smb_shares_of_host(host: str) -> list[dict[str, Any]]:
    """host 의 모든 smb_share row (claim 상태 확인/테스트용)."""
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM smb_share WHERE host=? ORDER BY id", (host,),
        ).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]


def smb_share_resolve(host: str | None, share: str | None) -> dict[str, Any] | None:
    """`host`+`share` 이름으로 smb_share row 를 찾는다. 없으면 None.

    ★ 왜 (2026-08-27 실측): 워커는 `{"host": "12.54.62.109", "share": "Users"}` 를
      쥐고 있는데 `smb_scan_share` 는 DB 의 int `share_id` 만 받았다. 그 어포던스
      불일치로 스캔 호출 241건 중 **71건이 share_id 누락으로 거부**됐다 —
      실행조차 안 된 것이다. 같은 공유를 이름으로도 가리킬 수 있게 한다.

    ⚠️ host 를 안 주면 share 이름만으로는 못 고른다. 같은 이름의 공유(`SMSSIG$`,
       `SCCMContentLib$`)가 host 마다 있어서 아무거나 고르면 **다른 host 를 훑는다.**
       그건 조용한 오작동이라 None 을 돌려주고 도구가 사유를 말하게 둔다.
    """
    h = str(host or "").strip()
    sh = str(share or "").strip()
    if not h or not sh:
        return None
    with connect() as c:
        row = c.execute(
            "SELECT * FROM smb_share WHERE host=? AND share=? ORDER BY id LIMIT 1",
            (h, sh),
        ).fetchone()
    return {k: row[k] for k in row.keys()} if row else None


def smb_auth_verified_hosts(*, limit: int = 12) -> list[str]:
    """과거에 **auth 로그인이 실제로 통했던** host, 최근 성공 순.

    패스 시작 센티넬용(`smb.verify_auth_credential`). 여기서 LOGON_FAILURE 가 나면
    자격증명이 깨진 것이지 host 성질이 아니다 — 미지 host 로는 그 구분이 안 된다
    (2026-08-17: 회로를 끊은 `10.97.140.31` 은 DB 에 기록조차 없는 host 였다).

    `print$` 는 제외한다 — 프린터 드라이버 공유는 어디에나 있어 신호가 약하다.
    """
    n = max(1, int(limit))
    with connect() as c:
        rows = c.execute(
            "SELECT host, MAX(last_seen) AS seen FROM smb_share "
            "WHERE auth_login_ok=1 AND share <> 'print$' "
            "GROUP BY host ORDER BY seen DESC LIMIT ?",
            (n,),
        ).fetchall()
    return [str(r["host"]) for r in rows if r["host"]]


def smb_host_schedule_communication_retry(
    host: str,
    *,
    reason: str,
    retry_seconds: float | None = None,
    status: str = "pending",
) -> int:
    """Host-level SMB 통신 불가를 terminal 로 닫지 않고 재시도 예약한다."""
    now = time.time()
    retry_after = now + (retry_seconds if retry_seconds is not None else smb_communication_retry_seconds())
    clean_reason = str(reason or "communication unavailable")[:1000]
    with connect() as c:
        r = c.execute(
            "UPDATE smb_share SET status=?, claimed_by=NULL, claimed_at=NULL, "
            "retry_after=?, retry_count=COALESCE(retry_count,0)+1, "
            "last_error_kind='communication_unavailable', last_error=?, "
            "processed_at=? "
            "WHERE host=? AND status NOT IN ('closed','ignored')",
            (status, retry_after, clean_reason, now, host),
        )
        return r.rowcount


def smb_share_schedule_communication_retry(
    share_id: int,
    *,
    reason: str,
    retry_seconds: float | None = None,
    status: str = "walked",
) -> None:
    now = time.time()
    retry_after = now + (retry_seconds if retry_seconds is not None else smb_communication_retry_seconds())
    share_set_status(
        share_id,
        status,
        retry_after=retry_after,
        last_error_kind="communication_unavailable",
        last_error=str(reason or "communication unavailable")[:1000],
        processed_at=now,
    )
    with connect() as c:
        c.execute(
            "UPDATE smb_share SET retry_count=COALESCE(retry_count,0)+1 WHERE id=?",
            (share_id,),
        )


def smb_unseen_since_scan_apply(
    scan_id: int,
    *,
    subnets: list[str] | None = None,
    alive_hosts: list[str] | set[str] | None = None,
    retry_seconds: float | None = None,
) -> dict[str, int]:
    """Apply post-discovery cleanup.

    If alive_hosts is provided, unseen shares on alive hosts are closed, while
    unseen shares on non-alive hosts are scheduled for communication retry.
    Without alive_hosts this preserves the legacy close-all-unseen behavior.
    """
    if alive_hosts is None:
        return {
            "closed": close_unseen_since(scan_id, subnets=subnets),
            "retry_scheduled": 0,
        }
    now = time.time()
    retry_after = now + (retry_seconds if retry_seconds is not None else smb_communication_retry_seconds())
    alive = sorted({str(h).strip() for h in alive_hosts if str(h).strip()})
    args: list[Any] = [scan_id]
    subnet_clause = ""
    if subnets is not None:
        norm = [_normalize_cidr(s) for s in subnets]
        if not norm:
            return {"closed": 0, "retry_scheduled": 0}
        subnet_clause = " AND subnet IN (" + ",".join("?" for _ in norm) + ")"
        args.extend(norm)
    host_in = ",".join("?" for _ in alive)
    with connect() as c:
        if alive:
            close_sql = (
                "UPDATE smb_share SET status='closed', claimed_by=NULL, claimed_at=NULL "
                "WHERE last_scan_id IS NOT NULL AND last_scan_id<>? "
                "AND status IN ('pending','walked','listing_reviewed','triaged_completed','triaged_errored') "
                + subnet_clause
                + f" AND host IN ({host_in})"
            )
            close_args = [*args, *alive]
            closed = c.execute(close_sql, close_args).rowcount
            retry_host_filter = f" AND host NOT IN ({host_in})"
            retry_host_args = alive
        else:
            closed = 0
            retry_host_filter = ""
            retry_host_args = []
        retry_sql = (
            "UPDATE smb_share SET claimed_by=NULL, claimed_at=NULL, retry_after=?, "
            "retry_count=COALESCE(retry_count,0)+1, "
            "last_error_kind='communication_unavailable', "
            "last_error='host not reachable during SMB discovery', "
            "status='pending' "
            "WHERE last_scan_id IS NOT NULL AND last_scan_id<>? "
            "AND status IN ('pending','walked','listing_reviewed','triaged_completed','triaged_errored') "
            + subnet_clause
            + retry_host_filter
        )
        retry_scheduled = c.execute(
            retry_sql,
            [retry_after, *args, *retry_host_args],
        ).rowcount
    return {"closed": int(closed), "retry_scheduled": int(retry_scheduled)}


def smb_host_claim_next(
    *,
    session_id: int,
    subnet: str | None = None,
    stale_seconds: float = SMB_CLAIM_STALE_SECONDS,
) -> dict[str, Any] | None:
    """pending(또는 stale in_progress) host 1개의 pending share 전부를 atomic 하게
    in_progress 로 claim → host digest 반환. 없으면 None(=완료).

    동시 smb-batch 세션이 서로 다른 host 를 집도록 보장한다. claim 단위 = HOST
    (share 는 host 안에서 sweep). 우선순위: share 수 desc, MIN(id) asc.
    pg=FOR UPDATE SKIP LOCKED, sqlite=single-writer 직렬화로 atomic.
    """
    now = time.time()
    cycle_key = smb_current_cycle_key()
    cutoff = now - stale_seconds
    # claimable = pending 또는 stale in_progress.
    claimable = (
        "((status='pending' "
        "OR (status='in_progress' AND claimed_at IS NOT NULL AND claimed_at < ?)) "
        "AND (retry_after IS NULL OR retry_after <= ?))"
    )
    subnet_clause = "AND subnet=? " if subnet is not None else ""
    pick_sql = (
        "SELECT host FROM smb_share "
        f"WHERE cycle_key=? AND {claimable} {subnet_clause}"
        "GROUP BY host ORDER BY COUNT(*) DESC, MIN(id) ASC LIMIT 1"
    )
    pick_args: list[Any] = [cycle_key, cutoff, now]
    if subnet is not None:
        pick_args.append(subnet)
    # pg 는 FOR UPDATE+GROUP BY 금지 → pick(락없음) 후 claimable UPDATE RETURNING.
    # 다른 세션이 그 host 를 먼저 채가면 UPDATE 0행 → 다음 host 재시도(동시성 안전,
    # 두 백엔드 공통: autocommit + 단일 UPDATE 문 atomic).
    with connect() as c:
        for _ in range(12):
            prow = c.execute(pick_sql, pick_args).fetchone()
            if prow is None:
                return None
            host = prow["host"]
            rows = c.execute(
                "UPDATE smb_share SET status='in_progress', claimed_by=?, claimed_at=? "
                f"WHERE host=? AND cycle_key=? AND {claimable} RETURNING *",
                [session_id, now, host, cycle_key, cutoff, now],
            ).fetchall()
            if rows:
                shares = [{k: r[k] for k in r.keys()} for r in rows]
                return {
                    "host": shares[0]["host"],
                    "subnet": shares[0]["subnet"],
                    "claimed_by": session_id,
                    "claimed_at": now,
                    "share_ids": [s["id"] for s in shares],
                    "shares": shares,
                }
            # 0행 = race 로 그 host 가 사라짐 → 다음 host 재시도
    return None


# SMB E2E #1 점검 큐 — 7일 롤링 재점검.
SMB_TASK_RESCAN_SECONDS = 7 * 86400  # triaged_completed 가 이만큼 지나면 재점검 대상


def smb_task_claim_next(
    *,
    session_id: int,
    subnet: str | None = None,
    stale_seconds: float = SMB_CLAIM_STALE_SECONDS,
    rescan_seconds: float = SMB_TASK_RESCAN_SECONDS,
) -> dict[str, Any] | None:
    """#1 점검 에이전트 전용 share claim. claim 대상(요구):

    - 수집기가 채운 **walked / listing_reviewed** share (판정 대기), 또는
    - 멈춘 stale in_progress (claimed_at < now-stale), 또는
    - **7일 지난 triaged_completed** (processed_at < now-7d) = 롤링 재점검.

    즉 "pending/미완료 중 7일 지난 것" + "아직 판정 안 한 walked". 일주일 내 중복
    점검 방지(triaged 가 7일 안이면 제외). claim 단위 = SHARE.

    ⚠️ **2026-08-28 현재 생산 호출부가 없다.** 이 쿼리를 부르던 평면 태스크 레인이
       은퇴했고, 그 자리를 대신한 `smb.lead` 는 `lead_targets_overview` 로 큐를 본다 —
       그쪽은 **status 만** 거른다. 즉 아래 세 조건이 리드 경로에는 아직 없다:

         · 7일 지난 `triaged_completed` 롤링 재점검
         · 8h 통신/agent 재시도 도래분 재개 (`retry_after`)
         · stale `in_progress` 회수 (`claimed_at < now-stale`)

       설계 의도(주 1회 사이클 · 8시간 간격 3회 재시도)는 여기에만 적혀 있다.
       지우지 말고 리드 어댑터가 같은 조건을 갖출 때 옮겨라.
    """
    now = time.time()
    cycle_key = smb_current_cycle_key()
    stale_cutoff = now - stale_seconds
    rescan_cutoff = now - rescan_seconds
    # claimable = 판정대기(walked/listing_reviewed) | stale in_progress |
    # 7일경과 triaged | 8h 통신/agent 재시도 도래 triaged.
    claimable = (
        "((status IN ('walked','listing_reviewed') "
        " OR (status='in_progress' AND claimed_at IS NOT NULL AND claimed_at < ?) "
        " OR (status='triaged_completed' AND (processed_at IS NULL OR processed_at < ?)) "
        " OR (status='triaged_completed' AND retry_after IS NOT NULL AND retry_after <= ?)) "
        "AND (retry_after IS NULL OR retry_after <= ?))"
    )
    subnet_clause = "AND subnet=? " if subnet is not None else ""
    pick_sql = (
        "SELECT id FROM smb_share "
        f"WHERE cycle_key=? AND {claimable} {subnet_clause}"
        "ORDER BY COALESCE(walk_done_at, last_seen, first_seen) ASC, host ASC, id ASC LIMIT 1"
    )
    pick_args: list[Any] = [cycle_key, stale_cutoff, rescan_cutoff, now, now]
    if subnet is not None:
        pick_args.append(subnet)
    with connect() as c:
        for _ in range(12):
            prow = c.execute(pick_sql, pick_args).fetchone()
            if prow is None:
                return None
            share_id = int(prow["id"])
            rows = c.execute(
                "UPDATE smb_share SET status='in_progress', claimed_by=?, claimed_at=? "
                f"WHERE id=? AND cycle_key=? AND {claimable} RETURNING *",
                [session_id, now, share_id, cycle_key, stale_cutoff, rescan_cutoff, now, now],
            ).fetchall()
            if rows:
                shares = [{k: r[k] for k in r.keys()} for r in rows]
                return {
                    "host": shares[0]["host"],
                    "subnet": shares[0]["subnet"],
                    "claimed_by": session_id,
                    "claimed_at": now,
                    "share_ids": [s["id"] for s in shares],
                    "shares": shares,
                }
    return None


def smb_task_host_open_count(host: str, *, session_id: int) -> int:
    """host 에 남은 점검 대상 share 수.

    0이면 해당 IP의 현재 task-ready share가 모두 terminal 상태라는 뜻이고,
    IP report draft를 #2 큐로 승격할 수 있다.
    """
    with connect() as c:
        row = c.execute(
            "SELECT COUNT(*) FROM smb_share WHERE host=? AND cycle_key=? AND ("
            "(status IN ('walked','listing_reviewed') "
            "OR (status='in_progress' AND claimed_by=?)) "
            "AND (retry_after IS NULL OR retry_after <= ?))",
            (host, smb_current_cycle_key(), session_id, time.time()),
        ).fetchone()
    return int(row[0] or 0) if row else 0


def smb_host_claim(
    *,
    host: str,
    session_id: int,
    subnet: str | None = None,
    stale_seconds: float = SMB_CLAIM_STALE_SECONDS,
) -> dict[str, Any] | None:
    """명시 host 의 claimable share 를 in_progress 로 점유.

    direct `smb_host_sweep(host=...)` 경로가 batch driver 를 우회해 같은 host 를
    중복 sweep 하지 않도록 하는 보강. pending, stale in_progress, 같은 session 의
    in_progress 만 갱신한다.
    """
    now = time.time()
    cycle_key = smb_current_cycle_key()
    cutoff = now - stale_seconds
    subnet_clause = "AND subnet=? " if subnet is not None else ""
    args: list[Any] = [session_id, now, host, cycle_key]
    if subnet is not None:
        args.append(_normalize_cidr(subnet))
    args.extend([session_id, cutoff, now])
    with connect() as c:
        rows = c.execute(
            "UPDATE smb_share SET status='in_progress', claimed_by=?, claimed_at=? "
            f"WHERE host=? AND cycle_key=? {subnet_clause}"
            "AND ((status='pending' OR "
            "(status='in_progress' AND (claimed_by=? OR claimed_at IS NULL OR claimed_at < ?))) "
            "AND (retry_after IS NULL OR retry_after <= ?)) "
            "RETURNING *",
            args,
        ).fetchall()
    if not rows:
        return None
    shares = [{k: r[k] for k in r.keys()} for r in rows]
    return {
        "host": shares[0]["host"],
        "subnet": shares[0]["subnet"],
        "claimed_by": session_id,
        "claimed_at": now,
        "share_ids": [s["id"] for s in shares],
        "shares": shares,
    }


def smb_reclaim_stale_host_claims(
    *,
    stale_seconds: float = SMB_CLAIM_STALE_SECONDS,
) -> int:
    """Release SMB host claims that cannot make progress.

    Reclaims only non-terminal `in_progress` rows when the claim is stale or
    belongs to a paused/archived session. Terminal review rows are untouched.
    """
    cutoff = time.time() - stale_seconds
    with connect() as c:
        r = c.execute(
            "UPDATE smb_share SET status='pending', claimed_by=NULL, claimed_at=NULL "
            "WHERE status='in_progress' AND ("
            "claimed_at IS NULL OR claimed_at < ? OR "
            "claimed_by IN (SELECT session_id FROM chat_goal WHERE status='paused') OR "
            "claimed_by IN (SELECT id FROM chat_session WHERE status='archived')"
            ")",
            (cutoff,),
        )
        return r.rowcount


def smb_host_set_status(host: str, status: str, **fields: Any) -> None:
    """host 의 in_progress share 전부를 terminal status 로 + claim 해제.

    status 는 기존 smb_share 어휘(walked/triaged_completed/triaged_errored/closed/ignored).
    """
    _validate_column_names(fields.keys())
    sets = ["status=?", "claimed_by=?", "claimed_at=?"]
    args: list[Any] = [status, None, None]
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(host)
    with connect() as c:
        c.execute(
            f"UPDATE smb_share SET {', '.join(sets)} "
            "WHERE host=? AND status='in_progress'",
            args,
        )


def smb_hosts_summary(*, subnet: str | None = None) -> dict[str, int]:
    """host 단위 진행률 — pending/in_progress/done host 수 (smb-batch 완료 narration)."""
    where = []
    args: list[Any] = []
    if subnet is not None:
        where.append("subnet=?")
        args.append(subnet)
    where_sql = ("WHERE " + " AND ".join(where)) if where else ""
    # host 별 상태 집계: pending share 있으면 pending, 아니면 in_progress 있으면 in_progress,
    # 둘 다 없으면 done.
    q = (
        "SELECT host, "
        "SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS n_pending, "
        "SUM(CASE WHEN status='in_progress' THEN 1 ELSE 0 END) AS n_inprog "
        f"FROM smb_share {where_sql} GROUP BY host"
    )
    with connect() as c:
        rows = c.execute(q, args).fetchall()
    out = {"pending_hosts": 0, "in_progress_hosts": 0, "done_hosts": 0, "total_hosts": 0}
    for r in rows:
        out["total_hosts"] += 1
        if int(r["n_pending"]) > 0:
            out["pending_hosts"] += 1
        elif int(r["n_inprog"]) > 0:
            out["in_progress_hosts"] += 1
        else:
            out["done_hosts"] += 1
    return out


