# smb_directory
# ============================================================

def upsert_smb_directory(
    share_id: int,
    path: str,
    *,
    depth: int = 0,
    listable: bool | None = None,
    readable: bool | None = None,
    writable: bool | None = None,
    error: str | None = None,
) -> int:
    """SMB directory access observation. path is share-root relative; root is ''."""
    clean_path = str(path or "").strip("/")
    now = time.time()
    with connect() as c:
        row = c.execute(
            "SELECT id FROM smb_directory WHERE share_id=? AND path=?",
            (share_id, clean_path),
        ).fetchone()
        if row is None:
            cur = c.execute(
                "INSERT INTO smb_directory(share_id, path, depth, listable, readable, "
                "writable, error, last_seen) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    share_id,
                    clean_path,
                    int(depth),
                    _b(listable),
                    _b(readable),
                    _b(writable),
                    error,
                    now,
                ),
            )
            return int(cur.lastrowid)
        c.execute(
            "UPDATE smb_directory SET depth=?, listable=?, readable=?, writable=?, "
            "error=?, last_seen=? WHERE id=?",
            (
                int(depth),
                _b(listable),
                _b(readable),
                _b(writable),
                error,
                now,
                row["id"],
            ),
        )
        return int(row["id"])


def directories_for_share(share_id: int, *, limit: int = 5000) -> list[dict[str, Any]]:
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM smb_directory WHERE share_id=? "
            "ORDER BY depth ASC, path ASC LIMIT ?",
            (share_id, limit),
        ).fetchall()
        return [{k: r[k] for k in r.keys()} for r in rows]


