def upsert_smb_file(
    share_id: int, path: str, *,
    size: int, is_text_candidate: bool, suspicious_name: bool,
) -> int:
    """반환: file_id."""
    now = time.time()
    with connect() as c:
        row = c.execute(
            "SELECT id FROM smb_file WHERE share_id=? AND path=?", (share_id, path),
        ).fetchone()
        if row is None:
            cur = c.execute(
                "INSERT INTO smb_file(share_id, path, size, is_text_candidate, "
                "suspicious_name, last_walked_at) VALUES (?, ?, ?, ?, ?, ?)",
                (share_id, path, size, int(is_text_candidate), int(suspicious_name), now),
            )
            return int(cur.lastrowid)
        c.execute(
            "UPDATE smb_file SET size=?, is_text_candidate=?, suspicious_name=?, "
            "last_walked_at=? WHERE id=?",
            (size, int(is_text_candidate), int(suspicious_name), now, row["id"]),
        )
