def status_counts(kind: str = "smb") -> dict[str, int]:
    assert kind == "smb"
    with connect() as c:
        rows = c.execute(
            "SELECT status, COUNT(*) AS n FROM smb_share GROUP BY status"
        ).fetchall()
        return {r["status"]: r["n"] for r in rows}


def shares_overview(*, status: str | None = None, limit: int = 50) -> list[dict[str, Any]]:
    with connect() as c:
        q = (
            "SELECT s.*, c.name AS cred_name, "
            "  (SELECT COUNT(*) FROM smb_file f WHERE f.share_id=s.id) AS file_total, "
            "  (SELECT COUNT(*) FROM smb_file f WHERE f.share_id=s.id AND f.hits_count>0) AS file_with_hits, "
            "  (SELECT COUNT(*) FROM smb_file_hit h JOIN smb_file f ON f.id=h.file_id "
            "   WHERE f.share_id=s.id AND h.agent_verdict='confirmed') AS confirmed_hits "
            "FROM smb_share s LEFT JOIN smb_credential c ON c.id=s.auth_credential_id "
        )
        if status:
            q += "WHERE s.status=? ORDER BY s.last_seen DESC LIMIT ?"
            args = (status, limit)
        else:
            q += "ORDER BY s.last_seen DESC LIMIT ?"
            args = (limit,)
        rows = c.execute(q, args).fetchall()
        return [{k: r[k] for k in r.keys()} for r in rows]


def recent_scans(kind: str = "smb", limit: int = 10) -> list[dict[str, Any]]:
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM scan WHERE kind=? ORDER BY started_at DESC LIMIT ?",
            (kind, limit),
        ).fetchall()
        return [{k: r[k] for k in r.keys()} for r in rows]


