def _reindex_file_review(c, file_id: int) -> None:
    row = c.execute(
        "SELECT f.path, f.review_summary, f.agent_tags, f.agent_note, "
        "  f.share_id, s.host, s.share "
        "FROM smb_file f JOIN smb_share s ON s.id=f.share_id "
        "WHERE f.id=?", (file_id,),
    ).fetchone()
    if not row or not row["review_summary"]:
        return
    tags = ""
    if row["agent_tags"]:
        try:
            tags = " ".join(json.loads(row["agent_tags"]))
        except Exception:
            pass
    note = row["agent_note"] or ""
    content = f"{row['review_summary']} {tags} {note}".strip()
    _fts_delete(c, "file_review", file_id)
    c.execute(
        "INSERT INTO finding_index(kind, ref_id, share_id, host, share_name, "
        "path, content) VALUES (?, ?, ?, ?, ?, ?, ?)",
        ("file_review", file_id, row["share_id"], row["host"], row["share"],
         row["path"], content),
    )


def _reindex_share_review(c, share_id: int,
                          review: dict[str, Any]) -> None:
    row = c.execute(
        "SELECT host, share FROM smb_share WHERE id=?", (share_id,),
    ).fetchone()
    if not row:
        return
    parts = [review.get("summary", "")]
    fua = review.get("follow_up_actions") or []
    if isinstance(fua, list):
        parts.extend(str(x) for x in fua)
    content = " ".join(p for p in parts if p).strip()
    _fts_delete(c, "share_review", share_id)
    c.execute(
        "INSERT INTO finding_index(kind, ref_id, share_id, host, share_name, "
        "path, content) VALUES (?, ?, ?, ?, ?, ?, ?)",
        ("share_review", share_id, share_id, row["host"], row["share"],
         "", content),
    )


def memory_recall_for_share(
    *, host: str, share: str,
    path_samples: list[str] | None = None,
) -> list[dict[str, Any]]:
    """master 가 share 시작 시 호출. 매칭되는 모든 룰 반환.

    - host scope: key == host
    - share scope: key == f"{host}:{share}"
    - global scope: 항상
    - path_pattern scope: path_samples 중 key 가 부분 매칭되는 path 가 있으면
    - operator scope: 항상 (사용자 규칙)
    """
    now = time.time()
    share_key = f"{host}:{share}"
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM memory_rule "
            "WHERE (expires_at IS NULL OR expires_at > ?) "
            "ORDER BY scope, updated_at DESC",
            (now,),
        ).fetchall()

    matched = []
    for r in rows:
        d = _memory_row(r)
        scope, key = d["scope"], d["key"]
        if scope == "host" and key == host:
            matched.append(d)
        elif scope == "share" and key == share_key:
            matched.append(d)
        elif scope == "global":
            matched.append(d)
        elif scope == "operator":
            matched.append(d)
        elif scope == "path_pattern" and path_samples:
            if any(key in p for p in path_samples):
                matched.append(d)
    return matched


