def _normalize_cidr(subnet: str) -> str:
    import ipaddress
    try:
        net = ipaddress.ip_network(subnet.strip(), strict=False)
    except (ValueError, TypeError) as e:
        raise ValueError(f"invalid CIDR: {subnet!r} ({e})") from e
    return str(net)


def smb_current_cycle_key(ts: float | None = None) -> str:
    """Return the local ISO week key used for SMB weekly board cycles."""
    dt = datetime.fromtimestamp(time.time() if ts is None else ts)
    year, week, _weekday = dt.isocalendar()
    return f"{year:04d}-W{week:02d}"


def smb_cycle_ensure_current(cycle_key: str | None = None) -> dict[str, Any]:
    """Make enabled subnet targets belong to the current weekly cycle.

    This does not delete findings, evidence, mail history, or shares. It only
    resets per-cycle subnet progress so the weekly board starts from a fresh
    queue.
    """
    key = cycle_key or smb_current_cycle_key()
    now = time.time()
    with connect() as c:
        r = c.execute(
            "UPDATE smb_target_subnet SET cycle_key=?, cycle_swept_at=NULL, "
            "cycle_hosts_found=0, cycle_shares_found=0, claimed_by=NULL, claimed_at=NULL "
            "WHERE enabled=1 AND (cycle_key IS NULL OR cycle_key<>?)",
            (key, key),
        )
        return {"cycle_key": key, "subnets_reset": int(r.rowcount or 0), "at": now}


def smb_target_add(
    subnet: str, *, note: str | None = None,
    charter_ref: str | None = None, added_by: str | None = None,
    allow_duplicate: bool = False,
) -> int:
    norm = _normalize_cidr(subnet)
    now = time.time()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        if not allow_duplicate and (
            note is not None or charter_ref is not None or added_by is not None
        ):
            r = c.execute(
                "SELECT id FROM smb_target_subnet WHERE subnet=? ORDER BY id LIMIT 1",
                (norm,),
            ).fetchone()
            if r:
                fields = []
                args: list[Any] = []
                if note is not None:
                    fields.append("note=?")
                    args.append(note)
                if charter_ref is not None:
                    fields.append("charter_ref=?")
                    args.append(charter_ref)
                if added_by is not None:
                    fields.append("added_by=?")
                    args.append(added_by)
                args.append(r["id"])
                c.execute(
                    f"UPDATE smb_target_subnet SET {', '.join(fields)} WHERE id=?",
                    args,
                )
                return int(r["id"])
        cur = c.execute(
            "INSERT INTO smb_target_subnet(subnet, note, charter_ref, "
            "added_by, cycle_key, created_at) VALUES (?, ?, ?, ?, ?, ?)",
            (norm, note, charter_ref, added_by, cycle_key, now),
        )
        return int(cur.lastrowid)


def smb_target_list(*, enabled_only: bool = False) -> list[dict[str, Any]]:
    q = "SELECT * FROM smb_target_subnet"
    if enabled_only:
        q += " WHERE enabled=1"
    q += " ORDER BY id"
    with connect() as c:
        return [{k: r[k] for k in r.keys()} for r in c.execute(q).fetchall()]


def smb_target_remove(target_id: int) -> None:
    with connect() as c:
        c.execute("DELETE FROM smb_target_subnet WHERE id=?", (target_id,))


def smb_target_remove_by_subnet(subnet: str) -> None:
    norm = _normalize_cidr(subnet)
    with connect() as c:
        c.execute("DELETE FROM smb_target_subnet WHERE subnet=?", (norm,))


def smb_target_set_enabled(target_id: int, enabled: bool) -> None:
    with connect() as c:
        c.execute(
            "UPDATE smb_target_subnet SET enabled=? WHERE id=?",
            (1 if enabled else 0, target_id),
        )


# ---- v3.72 (a): 서브넷 스윕 진행상태 — 40만 IP 한방 금지, 하나씩 점진/재개 ----

# v3.76: rolling 통일 — never-first → oldest-first.
# v3.83: weekly board cycle 은 cycle_swept_at 으로 새판을 만들고, gap rescan 은 8h.
SMB_SUBNET_RESCAN_SECONDS = 7 * 86400
SMB_SUBNET_GAP_RESCAN_SECONDS = 8 * 3600
SMB_SUBNET_CLAIM_STALE_SECONDS = 1800


def _subnet_retry_due_sql() -> str:
    return (
        "EXISTS ("
        " SELECT 1 FROM smb_share s"
        " WHERE s.subnet=smb_target_subnet.subnet"
        " AND s.status NOT IN ('closed','ignored')"
        " AND s.last_error_kind='communication_unavailable'"
        " AND s.retry_after IS NOT NULL"
        " AND s.retry_after <= ?"
        ")"
    )


def subnets_pending_sweep(
    *, limit: int = 1, cooldown_seconds: float | None = None,
) -> list[dict[str, Any]]:
    """스윕 대상 subnet rows — 현재 주차 미완료 먼저 → 8h gap 재조사.

    **기본 limit=1** — 한 번에 한 서브넷씩 꺼내 점진 스윕하라는 의도.
    중간에 죽어도 현재 cycle_swept_at 이 NULL 인 것은 다시 잡혀 재개 가능.
    주간 cycle 이 끝나면 cooldown(기본 8h) 지난 swept subnet 이 gap-rescan 대상.
    """
    smb_cycle_ensure_current()
    cycle_key = smb_current_cycle_key()
    cooldown = SMB_SUBNET_GAP_RESCAN_SECONDS if cooldown_seconds is None else cooldown_seconds
    now = time.time()
    fresh_cutoff = now - cooldown
    claim_cutoff = now - SMB_SUBNET_CLAIM_STALE_SECONDS
    retry_due = _subnet_retry_due_sql()
    weekly_due = "(cycle_key=? AND cycle_swept_at IS NULL)"
    rolling_due = f"((swept_at IS NULL OR swept_at < ?) OR {retry_due})"
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM smb_target_subnet "
            f"WHERE enabled=1 AND ({weekly_due} OR {rolling_due}) "
            "AND (claimed_at IS NULL OR claimed_at < ?) "
            f"ORDER BY {weekly_due} DESC, ({retry_due}) DESC, swept_at ASC, id ASC LIMIT ?",
            (cycle_key, fresh_cutoff, now, claim_cutoff, cycle_key, now, limit),
        ).fetchall()
        return [{k: r[k] for k in r.keys()} for r in rows]


def smb_subnet_claim_next(
    *,
    session_id: int,
    subnet: str | None = None,
    stale_seconds: float = SMB_SUBNET_CLAIM_STALE_SECONDS,
    cooldown_seconds: float | None = None,
) -> dict[str, Any] | None:
    """스윕할 subnet 1개를 atomic 하게 claim.

    subnet 이 없으면 pending/rolling 대상 중 1개를 고르고, 있으면 그 subnet 만
    claim한다. fresh in_progress 는 다른 세션이 가져가지 못하고, stale claim 은 회수된다.
    """
    smb_cycle_ensure_current()
    cycle_key = smb_current_cycle_key()
    cooldown = SMB_SUBNET_GAP_RESCAN_SECONDS if cooldown_seconds is None else cooldown_seconds
    now = time.time()
    fresh_cutoff = now - cooldown
    claim_cutoff = now - stale_seconds
    retry_due = _subnet_retry_due_sql()
    due = f"((cycle_key=? AND cycle_swept_at IS NULL) OR ((swept_at IS NULL OR swept_at < ?) OR {retry_due}))"
    claimable = "(claimed_at IS NULL OR claimed_at < ? OR claimed_by=?)"
    if subnet is not None:
        norm = _normalize_cidr(subnet)
        sql = (
            "UPDATE smb_target_subnet SET claimed_by=?, claimed_at=? "
            "WHERE id = ("
            " SELECT id FROM smb_target_subnet "
            f" WHERE subnet=? AND enabled=1 AND {due} AND {claimable} "
            " ORDER BY id ASC LIMIT 1"
            ") "
            "RETURNING *"
        )
        args: list[Any] = [
            session_id, now, norm, cycle_key, fresh_cutoff, now, claim_cutoff, session_id,
        ]
    else:
        sql = (
            "UPDATE smb_target_subnet SET claimed_by=?, claimed_at=? "
            "WHERE id = ("
            " SELECT id FROM smb_target_subnet "
            f" WHERE enabled=1 AND {due} AND {claimable} "
            " ORDER BY (cycle_key=? AND cycle_swept_at IS NULL) DESC, swept_at ASC, id ASC LIMIT 1"
            ") RETURNING *"
        )
        args = [session_id, now, cycle_key, fresh_cutoff, now, claim_cutoff, session_id, cycle_key]
    with connect() as c:
        row = c.execute(sql, args).fetchone()
        return {k: row[k] for k in row.keys()} if row else None


def smb_subnet_release_claim(subnet: str, *, session_id: int | None = None) -> bool:
    norm = _normalize_cidr(subnet)
    sql = "UPDATE smb_target_subnet SET claimed_by=NULL, claimed_at=NULL WHERE subnet=?"
    args: list[Any] = [norm]
    if session_id is not None:
        sql += " AND claimed_by=?"
        args.append(session_id)
    with connect() as c:
        r = c.execute(sql, args)
        return r.rowcount > 0


def subnet_mark_swept(
    subnet: str, *, scan_id: int | None = None,
    hosts_found: int = 0, shares_found: int = 0,
) -> None:
    """한 subnet 스윕 완료 기록 — per-subnet commit (재개 기준점)."""
    norm = _normalize_cidr(subnet)
    now = time.time()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        c.execute(
            "UPDATE smb_target_subnet SET swept_at=?, sweep_scan_id=?, "
            "hosts_found=?, shares_found=?, cycle_key=?, cycle_swept_at=?, "
            "cycle_hosts_found=?, cycle_shares_found=?, claimed_by=NULL, claimed_at=NULL "
            "WHERE subnet=?",
            (now, scan_id, hosts_found, shares_found, cycle_key, now,
             hosts_found, shares_found, norm),
        )


def subnets_sweep_overview() -> dict[str, int]:
    """enabled subnet 현재 주차 스윕 집계 — {total, swept, pending}."""
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        row = c.execute(
            "SELECT COUNT(*) AS total, "
            "SUM(CASE WHEN cycle_key=? AND cycle_swept_at IS NOT NULL THEN 1 ELSE 0 END) AS swept "
            "FROM smb_target_subnet WHERE enabled=1",
            (cycle_key,),
        ).fetchone()
    total = int(row["total"])
    swept = int(row["swept"] or 0)
    return {"total": total, "swept": swept, "pending": total - swept}


