_WEB_TARGET_STATUSES = {"pending", "in_progress", "tasked", "skipped", "error"}


def web_target_upsert(
    domain: str,
    *,
    source: str,
    day_bucket: str,
    event_count: int = 0,
) -> int:
    """domain × day_bucket 1 row 보장. 같은 키 재호출 시 event_count + last_seen 갱신.

    매일 fresh task 정책 — 같은 domain 도 day_bucket 다르면 별 row (다음 날
    자동으로 pending 으로 다시 적재). status 는 신규 row 만 'pending', 기존
    row 의 status 는 안 건드림 (한번 tasked 면 그날엔 tasked 유지).
    """
    domain = domain.strip()
    if not domain:
        raise ValueError("domain empty")
    now = time.time()
    with connect() as c:
        r = c.execute(
            "SELECT id FROM web_target_domain WHERE domain=? AND day_bucket=?",
            (domain, day_bucket),
        ).fetchone()
        if r is not None:
            c.execute(
                "UPDATE web_target_domain SET event_count=?, last_seen_at=? "
                "WHERE id=?",
                (event_count, now, r["id"]),
            )
            return int(r["id"])
        cur = c.execute(
            "INSERT INTO web_target_domain"
            "(domain, source, day_bucket, status, event_count, "
            " discovered_at, last_seen_at) "
            "VALUES (?, ?, ?, 'pending', ?, ?, ?)",
            (domain, source, day_bucket, event_count, now, now),
        )
        return int(cur.lastrowid)


def web_target_set_status(target_id: int, status: str, **fields: Any) -> None:
    """status 전이 + 추가 column 갱신. S2 column guard 적용.

    terminal status(tasked/skipped/error)로 가면 claim(claimed_by/at)을 자동 해제 —
    in_progress 회계가 깔끔히 닫힘. (caller 가 명시적으로 넘긴 값은 존중.)"""
    if status not in _WEB_TARGET_STATUSES:
        raise ValueError(f"invalid web_target status: {status!r}")
    _validate_column_names(fields.keys())
    sets = ["status=?", "last_task_at=?"]
    args: list[Any] = [status, time.time()]
    if status != "in_progress":
        if "claimed_by" not in fields:
            sets.append("claimed_by=?")
            args.append(None)
        if "claimed_at" not in fields:
            sets.append("claimed_at=?")
            args.append(None)
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(target_id)
    with connect() as c:
        c.execute(
            f"UPDATE web_target_domain SET {', '.join(sets)} WHERE id=?",
            args,
        )


# v3.59: web-batch 동시 세션이 같은 대상을 중복 점검하지 않도록 atomic claim.
# hang(crash) 한 세션이 in_progress 를 물고 있으면 이 시간 지나면 회수 대상.
WEB_CLAIM_STALE_SECONDS = 1800  # 30분
# v3.76: rolling 재헌트 — 본 지(last_task_at) 이만큼 지난 대상은 cooldown 풀려 재claim.
WEB_RESCAN_SECONDS = 86400


def web_target_claim_next(
    *,
    session_id: int,
    day_bucket: str | None = None,
    stale_seconds: float = WEB_CLAIM_STALE_SECONDS,
    cooldown_seconds: float = WEB_RESCAN_SECONDS,
) -> dict[str, Any] | None:
    """pending(또는 stale in_progress, 또는 cooldown 지난 tasked) 1개를 atomic claim.

    동시에 도는 web-batch 세션들이 서로 다른 대상을 집도록 보장한다.
    pg 는 `FOR UPDATE SKIP LOCKED` 로 row 락 경합을 건너뛴다. claim 할 게 없으면 None.

    v3.76 rolling 통일: 우선순위 = 안 본 것(last_task_at NULL) 먼저 → event_count desc
    (splunk 인기 secondary) → 본 지 오래된 순(last_task_at asc) → id asc. terminal
    (tasked/skipped/error) row 도 last_task_at < now-cooldown 이면 재헌트 대상(cross-bucket
    oldest 우선). stale in_progress 는 claimed_at < now-stale_seconds 인 것만 회수.
    """
    now = time.time()
    cutoff = now - stale_seconds
    fresh_cutoff = now - cooldown_seconds
    pick_where = (
        "status='pending' "
        "OR (status='in_progress' AND claimed_at IS NOT NULL AND claimed_at < ?) "
        "OR (status IN ('tasked','skipped','error') "
        "AND (last_task_at IS NULL OR last_task_at < ?))"
    )
    pick_args: list[Any] = [cutoff, fresh_cutoff]
    day_clause = ""
    if day_bucket is not None:
        day_clause = "day_bucket=? AND "
        pick_args.insert(0, day_bucket)
    inner_lock = "FOR UPDATE SKIP LOCKED"  # v3.76: 단일 postgres
    sql = (
        "UPDATE web_target_domain SET status='in_progress', "
        "claimed_by=?, claimed_at=? WHERE id = ("
        "SELECT id FROM web_target_domain "
        f"WHERE {day_clause}({pick_where}) "
        "ORDER BY (last_task_at IS NULL) DESC, event_count DESC, "
        f"last_task_at ASC, id ASC LIMIT 1 {inner_lock}"
        ") RETURNING *"
    )
    args = [session_id, now, *pick_args]
    with connect() as c:
        r = c.execute(sql, args).fetchone()
    return {k: r[k] for k in r.keys()} if r is not None else None


def _reclaim_stale_claims(table: str, *, stale_seconds: float) -> int:
    """v3.80 Slice0b: 진행 불능 claim 해제 — smb_reclaim_stale_host_claims 의 공용 미러.

    시간 기반 stale 은 각 claim_next 의 pick_where 가 이미 회수하지만, **paused goal /
    archived session** 이 물고 있는 claim 은 stale_seconds(30분)를 기다려야 했다.
    phase 진입 시 즉시 해제 + claimed_at IS NULL 엣지 정리. terminal row 는 불변.
    (goal_set 이 비-terminal goal 을 cleared 로 만들므로 status='paused' goal 이 남은
    세션 = 현재 paused — active goal 과 동시 존재 불가, 과잉 회수 없음.)
    """
    cutoff = time.time() - stale_seconds
    with connect() as c:
        r = c.execute(
            f"UPDATE {table} SET status='pending', claimed_by=NULL, claimed_at=NULL "
            "WHERE status='in_progress' AND ("
            "claimed_at IS NULL OR claimed_at < ? OR "
            "claimed_by IN (SELECT session_id FROM chat_goal WHERE status='paused') OR "
            "claimed_by IN (SELECT id FROM chat_session WHERE status='archived')"
            ")",
            (cutoff,),
        )
        return r.rowcount


# ── 리드(lead) read-only 큐 조회 ────────────────────────────────────────
#
# Phase 2a: 리드는 "다음에 무엇을 볼지" 판단한다 — 그러려면 큐를 **읽어야** 한다.
# 기존 함수는 claim_next(상태를 in_progress 로 바꿈)와 summary(카운트만)뿐이라,
# "지금 pending 인 타깃 20개가 무엇인가"를 부작용 없이 볼 방법이 없었다.
#
# ⚠️ claim 하지 않는다. 동시성 claim 은 러너(fanout)의 소관이고, 리드가 목록을 본다는
# 이유로 큐 상태가 바뀌면 러너와 리드가 같은 큐를 두고 싸운다.
_LEAD_QUEUE_TABLES: frozenset[str] = frozenset({
    "smb_share",
    "dev_web_target",
    "devops_target",
    "confluence_space_target",
    "confluence_search_target",
})


_LEAD_QUEUE_ORDERS: frozenset[str] = frozenset({
    "id DESC", "id ASC", "last_seen DESC", "priority_score DESC, id ASC",
    #: ★ smb 전용 — **시작한 host 를 먼저 끝낸다**(사용자 결정 2026-08-31).
    #   `last_seen DESC` 는 host 를 섞는다. 실측: 리드 창 200행에 서로 다른 host 122개
    #   (host 당 1.6행). 141개 host 를 하나씩 찔러 놓고 아무것도 완성하지 못했고,
    #   그래서 draft 스레드 25건이 **공유 1~3개만 남긴 채** 멈춰 있었다.
    #   smb 는 host 의 공유를 다 봐야 메일 한 통으로 묶어 보낸다 — 완성이 곧 발송이다.
    "started_host_first",
    #: ★ dev_web 판 — **메일이 걸린 target 을 먼저 끝낸다.** dev_web 은 target 하나가
    #   스레드 하나라 "묶기" 는 없지만, 제출 시점에 스레드가 draft 로 열리고 target 이
    #   종료돼야 큐로 올라간다. 그 사이가 반쯤 하다 만 구간이고, 거기 멈춘 것이 곧
    #   안 나가는 메일이다(실측 2026-08-31: draft 8건이 target in_progress 로 대기).
    "started_target_first",
})

#: 심볼릭 정렬 → 실제 SQL. 상관 서브쿼리라 **테이블을 탄다** — 아무 데나 쓰면 SQL 에러다.
#: 그래서 아래에서 테이블을 검사하고, 안 맞으면 **소리 내서 죽는다**(조용히 다른 정렬로
#: 떨어지면 "왜 안 바뀌지" 를 며칠 뒤에 묻게 된다).
_LEAD_ORDER_SQL: dict[str, tuple[str, str]] = {
    # (허용 테이블, SQL)
    "started_host_first": {
        "smb_share": (
        # ① 이미 스레드가 열린(=조치요청 대기 중인) host 를 최우선으로
        # ② 그중에서도 **남은 공유가 적은** host 부터 — 가장 빨리 메일이 나가는 순서
        # ③ 같은 host 의 공유는 붙여서 (한 번 잡으면 그 host 를 끝낸다)
        # ★ 높음 이상을 먼저 본다(사용자 결정 2026-08-31).
        #   ⚠️ 점검 **전** 공유는 severity 가 대부분 비어 있다(실측: walked 240건 중
        #      211건이 NULL). 그래서 이 키는 아는 것만 위로 띄우고, 모르는 것들 사이의
        #      순서는 아래 규칙이 정한다 — "모르면 낮음" 으로 취급하지 않는다.
        "(COALESCE(smb_share.severity,'') IN ('critical','high')) DESC, "
        "(EXISTS (SELECT 1 FROM mail_thread mt "
        "         WHERE mt.host = smb_share.host AND mt.status = 'draft')) DESC, "
        # ⚠️ `=` 로 쓰면 cycle_key 가 NULL 인 행에서 비교가 NULL 이 되어 개수가 **전부 0**
        #    이 되고, 정렬이 조용히 host 이름순으로 떨어진다(테스트가 잡았다).
        "(SELECT count(*) FROM smb_share s2 "
        "   WHERE s2.host = smb_share.host "
        "     AND s2.cycle_key IS NOT DISTINCT FROM smb_share.cycle_key "
        "     AND s2.status IN ('walked','listing_reviewed')) ASC, "
        "smb_share.host ASC, smb_share.id ASC"
        ),
    },
    # ★ 같은 이름이 도메인마다 다른 SQL 을 쓴다 — 규칙은 하나, 조인 키만 다르다
    #   (사용자 결정 2026-08-31 "다른 도메인 모두 동일하게 반영").
    #     ① 높음 이상이 걸린 대상 먼저
    #     ② 조치요청 스레드가 살아 있는 대상 먼저 — **묶는 단위를 끝낸다**
    #     ③ 나머지는 기존 우선순위
    #   ⚠️ NULL 함정: `severity IN (...)` 는 NULL 이면 NULL 이고 DESC 는 NULL 을 먼저
    #      놓는다. 여기선 EXISTS 라 그 함정이 없지만, 조건을 옮길 때 주의할 것.
    "started_target_first": {
        "dev_web_target": (
            "(EXISTS (SELECT 1 FROM dev_web_report_thread th "
            "         WHERE th.target_id = dev_web_target.id "
            "           AND th.severity IN ('critical','high') "
            "           AND th.status NOT IN ('closed','remediated','resolved','false_positive'))) DESC, "
            "(EXISTS (SELECT 1 FROM dev_web_report_thread th "
            "         WHERE th.target_id = dev_web_target.id AND th.status = 'draft')) DESC, "
            "(dev_web_target.status = 'in_progress') DESC, "
            "dev_web_target.priority_score DESC NULLS LAST, dev_web_target.id ASC"
        ),
        # github: 대상은 URL, 스레드는 `owner/name`. 호스트 부분을 떼면 같은 키가 된다.
        # ⚠️ 정규식에 `?` 를 쓰지 마라 — 상태 계층이 `?` 를 **바인딩 자리표시자**로 바꾼다.
        #    `https?` 라고 썼다가 "3 placeholders but 1 parameters" 로 죽었다.
        "devops_target": (
            "(EXISTS (SELECT 1 FROM github_report_thread th "
            "         WHERE th.repo = regexp_replace(devops_target.url, '^https{0,1}://[^/]+/', '') "
            "           AND th.severity IN ('critical','high') "
            "           AND th.status NOT IN ('closed','remediated','resolved','false_positive'))) DESC, "
            "(EXISTS (SELECT 1 FROM github_report_thread th "
            "         WHERE th.repo = regexp_replace(devops_target.url, '^https{0,1}://[^/]+/', '') "
            "           AND th.status NOT IN ('closed','remediated','resolved','false_positive'))) DESC, "
            "(devops_target.status = 'in_progress') DESC, devops_target.id DESC"
        ),
        "confluence_space_target": (
            "(EXISTS (SELECT 1 FROM confluence_report_thread th "
            "         WHERE th.space_key = confluence_space_target.space_key "
            "           AND th.severity IN ('critical','high') "
            "           AND th.status NOT IN ('closed','remediated','resolved','false_positive'))) DESC, "
            "(EXISTS (SELECT 1 FROM confluence_report_thread th "
            "         WHERE th.space_key = confluence_space_target.space_key "
            "           AND th.status NOT IN ('closed','remediated','resolved','false_positive'))) DESC, "
            "(confluence_space_target.status = 'in_progress') DESC, confluence_space_target.id DESC"
        ),
    },
}


# ── 리드 큐 필터: 행정적 제외 컬럼 ────────────────────────────────────────
# ★ **status 축이 아니라 제외 축이다.** print$ 는 설계상 점검 대상이 아니고
#   (`service/collector/print_filter.py`), 그 사실이 `excluded_reason` 에 적힌다.
#   status 로 거르면(=claimable 만 남기면) `triaged_completed` 168건이 영구히 숨어
#   **7일 롤링 재점검이 죽는다** — 두 축을 섞으면 안 된다.
#
# ⚠️ 이 컬럼은 `smb_share` 에만 있다(실측: dev_web_target·devops_target·
#    confluence_*_target 전부 없음). 다른 테이블에 걸면 SQL 에러가 난다.
_LEAD_EXCLUDE_COLS: dict[str, str] = {
    "smb_share": "excluded_reason",
}

# ── 리드 큐 필터: 테이블별 시각 컬럼 ──────────────────────────────────────
# ⚠️ 이름이 테이블마다 다르다. 하나로 가정하면 조용히 필터가 안 걸린다.
_LEAD_TIME_COLS: dict[str, dict[str, str]] = {
    "smb_share":                {"claimed": "claimed_at", "done": "processed_at",  "retry": "retry_after"},
    "dev_web_target":           {"claimed": "claimed_at", "done": "last_task_at",  "retry": "retry_after"},
    "devops_target":            {"claimed": "claimed_at", "done": "last_task_at",  "retry": "retry_after"},
    "confluence_space_target":  {"claimed": "claimed_at", "done": "last_scanned_at", "retry": "retry_after"},
    "confluence_search_target": {"claimed": "claimed_at", "done": "last_scanned_at", "retry": "retry_after"},
}

# 검토원이 아직 도는 타깃을 다시 위임하지 않도록 하는 임계.
# 계약 기본 wall-clock 이 1200~1800s 라 그보다 넉넉히 잡는다.
LEAD_INFLIGHT_STALE_SECONDS = 2700.0

def lead_targets_overview(
    table: str,
    *,
    status: str | None = None,
    limit: int = 50,
    order_by: str = "id DESC",
    skip_fresh_claims: bool = False,
    recheck_after_seconds: float | None = None,
    respect_retry_after: bool = False,
    exclude_marked: bool = False,
    **equals: Any,
) -> list[dict[str, Any]]:
    """리드용 read-only 큐 조회. **claim 하지 않는다.**

    table 은 화이트리스트 강제(fail-closed) — 호출자는 어댑터(고정 문자열)이지 LLM 이
    아니지만, 테이블명은 placeholder 로 바인딩할 수 없으므로 집합으로 닫는다.
    `order_by` 도 같은 이유로 어휘를 닫는다.
    `equals`: 추가 동등조건(예: service='github'). 값이 None 이면 무시한다.
    """
    if table not in _LEAD_QUEUE_TABLES:
        raise ValueError(
            f"lead_targets_overview: 허용되지 않은 테이블 {table!r} "
            f"(허용: {sorted(_LEAD_QUEUE_TABLES)})"
        )
    if order_by not in _LEAD_QUEUE_ORDERS:
        raise ValueError(
            f"lead_targets_overview: 허용되지 않은 정렬 {order_by!r} "
            f"(허용: {sorted(_LEAD_QUEUE_ORDERS)})"
        )
    where: list[str] = []
    args: list[Any] = []
    if status is not None:
        where.append("status=?")
        args.append(status)
    for col, val in equals.items():
        if val is None:
            continue
        if not col.isidentifier():
            raise ValueError(f"lead_targets_overview: 잘못된 컬럼 {col!r}")
        where.append(f"{col}=?")
        args.append(val)
    cols = _LEAD_TIME_COLS.get(table, {})
    now = time.time()

    # ── 행정적으로 점검 제외된 행은 큐 목록에서 뺀다 (2026-08-29) ────────────
    # smb 큐 2,707행 중 2,463(91%)이 `print$`(excluded_reason='print') 이고,
    # `last_seen DESC` 상위를 전부 차지해 **리드의 무필터 목록 200행이 전부 그것**이었다.
    # 결과(실기동 실측): `report_no_targets` 5건 전부 `accepted=false` — 근거가 매번
    # print$ 였다. 리드에게 **합법적 출구가 원리적으로 도달 불가**였고, 궁지에 몰린
    # 리드가 프린터 공유에 `open_inspection` 3회 · `set_target_status` 28회
    # (`ignored` 재스탬프 24 + `closed` 4)를 썼다. 그 4행이 DB 에 남아 있다.
    #
    # ⚠️ **파이썬 후처리로 하면 안 된다.** LIMIT 이 SQL 에서 먼저 걸려 200행이 전부
    #    제외 대상이면 후처리 결과가 0행이 되고, `report_no_targets` 가 "큐가 비었다"로
    #    **면제를 내준다** — walked 52행이 살아 있는데도. 그래서 SQL 층이다.
    #
    # ⚠️ 가드는 **raise** 다. `_LEAD_TIME_COLS` 는 컬럼이 없으면 조용히 필터를 안 걸지만,
    #    여기서 조용히 넘기면 제외 대상이 그대로 돌아온다 — fail-open 이다.
    #    등록 안 된 테이블에 이 플래그를 넘기는 건 배선 실수이므로 소리 내서 죽는다.
    if exclude_marked:
        ex_col = _LEAD_EXCLUDE_COLS.get(table)
        if ex_col is None:
            raise ValueError(
                f"lead_targets_overview: {table!r} 에는 제외 컬럼이 없다 — "
                f"exclude_marked 를 넘길 수 없다 (등록: {sorted(_LEAD_EXCLUDE_COLS)})"
            )
        where.append(f"{ex_col} IS NULL")

    # ── 아직 도는 검토원의 타깃을 다시 주지 않는다 (2026-08-28) ──────────────
    # 4도메인 리드가 전부 `claimable_statuses` 에 `in_progress` 를 넣는다. 덕분에 죽은
    # 워커의 행이 영구히 잠기진 않지만, 옛 백스톱이 하던 **stale 임계 검사가 없어서**
    # 살아 있는 검토원의 타깃까지 다시 위임될 수 있다 — LLM 예산을 두 배로 태운다.
    if skip_fresh_claims and cols.get("claimed"):
        cc = cols["claimed"]
        where.append(f"(status <> 'in_progress' OR {cc} IS NULL OR {cc} < ?)")
        args.append(now - LEAD_INFLIGHT_STALE_SECONDS)

    # ── 백오프가 도래하지 않은 행은 감춘다 ──────────────────────────────────
    if respect_retry_after and cols.get("retry"):
        rc = cols["retry"]
        where.append(f"({rc} IS NULL OR {rc} <= ?)")
        args.append(now)

    # ── 롤링 재점검: 끝난 지 오래된 것을 다시 큐에 올린다 ──────────────────
    # ⚠️ status 필터와 **함께 쓰면 안 된다** — 호출자가 status=None 으로 목록을 받고
    #    어댑터의 claimable_statuses 로 거르는 구조라, 여기선 "끝난 지 오래된 것"을
    #    빼지 않고 남기는 것만 한다(감추는 게 아니라 통과시킨다).
    if recheck_after_seconds is not None and cols.get("done"):
        dc = cols["done"]
        where.append(f"({dc} IS NULL OR {dc} < ?)")
        args.append(now - float(recheck_after_seconds))

    where_sql = ("WHERE " + " AND ".join(where)) if where else ""
    args.append(max(1, min(int(limit), 200)))
    order_sql = order_by
    spec = _LEAD_ORDER_SQL.get(order_by)
    if spec is not None:
        if table not in spec:
            raise ValueError(
                f"lead_targets_overview: 정렬 {order_by!r} 는 {sorted(spec)} 전용인데 "
                f"{table!r} 에 걸렸다 (상관 서브쿼리가 그 테이블을 탄다)"
            )
        order_sql = spec[table]
    with connect() as c:
        rows = c.execute(
            f"SELECT * FROM {table} {where_sql} ORDER BY {order_sql} LIMIT ?", args,
        ).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]


# ── 리드 hit view (v3.98) ─────────────────────────────────────────────
#
# 여기는 **쿼리만** 한다. 값 규칙(masked→shape)·캡·표시 순서는 전부
# `_shared/hit_view.py` 소관이다 — 두 곳에 두면 갈린다.
#
# ⚠️ 절대 `line_preview` 를 SELECT 하지 마라. 그건 파일 본문이고, 사용자 결정상
#    리드에게 가지 않는다(2026-08-21). 컬럼을 안 읽는 것이 그 약속의 이행이다.

_HIT_FILTER_COLS: dict[str, str] = {
    "category": "h.category",
    "kind": "h.kind",
    "verdict": "h.agent_verdict",
}

_HIT_FROM = "FROM smb_file_hit h JOIN smb_file f ON f.id=h.file_id"


def _hit_where(share_id: int, filters: dict[str, Any]) -> tuple[str, list[Any]]:
    """공유 스코프 + 닫힌 필터 컬럼만. 알 수 없는 키는 **조용히 무시하지 않고** 막는다."""
    unknown = sorted(set(filters) - set(_HIT_FILTER_COLS))
    if unknown:
        raise ValueError(
            f"share hit 필터에 없는 키: {unknown} (허용: {sorted(_HIT_FILTER_COLS)})")
    where = ["f.share_id=?"]
    args: list[Any] = [int(share_id)]
    for name, col in _HIT_FILTER_COLS.items():
        val = filters.get(name)
        if val is None:
            continue
        where.append(f"{col}=?")
        args.append(str(val))
    return " AND ".join(where), args


def share_hit_rollup(share_id: int, **filters: Any) -> list[dict[str, Any]]:
    """공유 하나의 `(category, kind, verdict)` 별 건수. 30k행이 파이썬으로 오지 않는다."""
    where_sql, args = _hit_where(share_id, filters)
    q = (
        "SELECT h.category AS category, h.kind AS kind, "
        "h.agent_verdict AS verdict, COUNT(*) AS count, "
        f"COUNT(DISTINCT f.id) AS files {_HIT_FROM} "
        f"WHERE {where_sql} "
        "GROUP BY h.category, h.kind, h.agent_verdict "
        "ORDER BY COUNT(*) DESC LIMIT 200"
    )
    with connect() as c:
        return [{k: r[k] for k in r.keys()} for r in c.execute(q, args).fetchall()]


def share_hit_shapes(
    share_id: int, *, limit: int = 20, priority: tuple[str, ...] = (),
    **filters: Any,
) -> list[dict[str, Any]]:
    """`masked` 값별 집계 — "같은 값이 몇 번" 이 이 도구의 핵심 신호다.

    `priority` 는 호출자(`_shared.hit_view.CATEGORY_PRIORITY`)가 준다. 여기에
    목록을 복사하지 마라 — 정렬 어휘가 두 곳에 생기면 갈린다. 이게 필요한 이유는
    순수 count desc 로 자르면 email 30,065건이 aws_access_key_id 2건을 덮기 때문이다.
    """
    where_sql, where_args = _hit_where(share_id, filters)
    prio_args: list[Any] = []
    if priority:
        cases = " ".join("WHEN h.category=? THEN ?" for _ in priority)
        prio_sql = f"CASE {cases} ELSE ? END"
        for i, cat in enumerate(priority):
            prio_args += [str(cat), i]
        prio_args.append(len(priority))
    else:
        prio_sql = "0"
    q = (
        f"SELECT {prio_sql} AS prio, h.category AS category, h.kind AS kind, "
        "h.agent_verdict AS verdict, h.masked AS masked, COUNT(*) AS count, "
        "COUNT(DISTINCT f.id) AS files, MIN(f.path) AS sample_ref, "
        f"MIN(h.line_no) AS sample_line {_HIT_FROM} "
        f"WHERE {where_sql} "
        "GROUP BY h.category, h.kind, h.agent_verdict, h.masked "
        "ORDER BY prio ASC, COUNT(*) DESC LIMIT ?"
    )
    args = [*prio_args, *where_args, max(1, min(int(limit), 100))]
    with connect() as c:
        return [{k: r[k] for k in r.keys()} for r in c.execute(q, args).fetchall()]


def findings_for_asset(
    task_type: str, *, asset_like: str, limit: int = 200,
) -> list[dict[str, Any]]:
    """코어 `finding_lifecycle` 을 asset 부분일치로 — smb 외 3도메인 hit view 소스.

    그 셋은 finding 이전 hit 을 영속하지 않는다. `extra_json.hits[]` 가 유일한
    소스이고 모양은 4도메인 동일하다(집계는 `_shared.hit_view.aggregate_finding_hits`).

    대소문자는 양쪽을 낮춰 비교한다 — postgres `LIKE` 는 대소문자를 가리고
    sqlite 는 안 가려서, 안 그러면 백엔드마다 결과가 달라진다.
    """
    like = str(asset_like or "").strip().lower()
    if not like:
        return []
    with _core_connect() as c:
        rows = c.execute(
            "SELECT asset, status, severity, task_type, extra_json "
            "FROM finding_lifecycle WHERE task_type=? AND LOWER(asset) LIKE ? "
            "ORDER BY last_seen DESC LIMIT ?",
            (str(task_type), like, max(1, min(int(limit), 500))),
        ).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]



def web_reclaim_stale_claims(*, stale_seconds: float = WEB_CLAIM_STALE_SECONDS) -> int:
    """⚠️ **런타임 소비자가 없다 — 일부러 배선하지 않았다** (2026-08-22 확인).

    `web` 도메인은 은퇴했다: `web_target_claim_next` 도 호출부가 테스트뿐이고,
    `domains/web/` 에 fanout 어댑터가 없으며, 게이트웨이 `DOMAIN_TABLES` 에도
    `web` 이 없다(UI 도 이 큐를 안 본다). 그래서 `web_target_domain` 은 643행 중
    **537행(84%)이 2026-06-01 부터 `in_progress`** 로 잠겨 있는데, 아무도 안 읽으므로
    영향이 없다. 도메인을 되살린다면 그때 이 함수를 claim 경로에 배선하고 잠긴 행부터
    회수해야 한다.

    ⚠️ 2026-08-28 갱신: 형제 중 `dev_web_reclaim_stale_claims` 도 호출부를 잃었다
    (평면 task 팬아웃 은퇴). 남은 배선은 `devops_reclaim_stale_claims`
    (github/confluence sso fanout) 하나다. 죽은 함수를 설명 없이 두면 다음 사람이
    "배선돼 있겠지" 하고 믿는다 — 코어 `FanoutAdapter.release` 주석이 정확히 그랬다.
    """
    return _reclaim_stale_claims("web_target_domain", stale_seconds=stale_seconds)


