def web_targets_pending(
    *, day_bucket: str | None = None, limit: int = 200,
) -> list[dict[str, Any]]:
    """pending 도메인 — event_count desc (인기 많은 사이트 먼저 점검)."""
    where = ["status='pending'"]
    args: list[Any] = []
    if day_bucket is not None:
        where.append("day_bucket=?")
        args.append(day_bucket)
    args.append(limit)
    q = (
        "SELECT * FROM web_target_domain "
        f"WHERE {' AND '.join(where)} "
        "ORDER BY event_count DESC, id ASC LIMIT ?"
    )
    with connect() as c:
        return [{k: r[k] for k in r.keys()} for r in c.execute(q, args).fetchall()]


def web_targets_summary(
    *, day_bucket: str | None = None,
) -> dict[str, int]:
    """status 별 카운트 + total. agent 가 진행률 narration 에 사용."""
    where = []
    args: list[Any] = []
    if day_bucket is not None:
        where.append("day_bucket=?")
        args.append(day_bucket)
    where_sql = ("WHERE " + " AND ".join(where)) if where else ""
    q = (
        f"SELECT status, COUNT(*) AS n FROM web_target_domain "
        f"{where_sql} GROUP BY status"
    )
    with connect() as c:
        rows = c.execute(q, args).fetchall()
    out: dict[str, int] = {
        s: 0 for s in _WEB_TARGET_STATUSES
    }
    out["total"] = 0
    for r in rows:
        out[r["status"]] = int(r["n"])
        out["total"] += int(r["n"])
    return out


# ============================================================
# dev_web_target / dev_web_report_thread — SMB E2E 미러, web 검사 최적화
# ============================================================

_DEV_WEB_TARGET_STATUSES = {"pending", "in_progress", "tasked", "skipped", "error"}
DEV_WEB_CLAIM_STALE_SECONDS = 1800
DEV_WEB_RESCAN_SECONDS = 86400

_DEV_WEB_REPORT_STATUSES = {
    # ★ report_ready = "초안까지 다 만들었고 발송만 남았다" 파킹 자리.
    #   confluence·github 이 이미 쓰는 어휘를 그대로 가져왔다(새 개념을 만들지 않는다).
    #   dev_web 엔 이 자리가 없어서 dry-run 종결이 reported 로 되돌아갔고, claim_next 가
    #   1800초마다 같은 스레드를 다시 집어 attempt_count 가 67까지 올랐다(실측 2026-08-28).
    "draft", "reported", "report_ready", "awaiting_reply", "reply_received", "reverifying",
    "remediated", "re_requested", "escalated", "closed",
    "exception_review", "owner_update_needed", "owner_reassignment_review",
    "reassigned", "partially_remediated",
}
# ⚠️ terminal 은 건드리지 않는다. report_ready 는 **종결이 아니라 파킹**이다 —
#    자율발송이 켜지면 다시 흘러야 하고, 그동안 병합 후보(open_statuses)에도 남아야 한다.
_DEV_WEB_REPORT_TERMINAL = {"remediated", "closed"}
# 심각도 랭크 — 도메인마다 같은 맵을 하나씩 갖고 있었다(4벌, 내용 동일).
# 병합 한 줄짜리도 4벌이었다. service.services.severity 가 정본이다.
_DEV_WEB_SEV_RANK = _sev.RANK


def _dev_web_normalize_url(url: str) -> tuple[str, str]:
    from urllib.parse import urlparse, urlunparse

    raw = str(url or "").strip()
    if not raw:
        raise ValueError("url empty")
    parsed = urlparse(raw if "://" in raw else f"https://{raw}")
    host = (parsed.hostname or "").lower().strip()
    if not host:
        raise ValueError(f"dev_web url host empty: {url!r}")
    scheme = (parsed.scheme or "https").lower()
    path = parsed.path.rstrip("/") or ""
    normalized = urlunparse((scheme, parsed.netloc.lower(), path, "", parsed.query, ""))
    return normalized, host


def dev_web_target_upsert(
    url: str,
    *,
    source: str,
    day_bucket: str,
    event_count: int = 0,
    priority_score: int = 0,
    domain: str | None = None,
    cycle_key: str | None = None,
) -> int:
    """url × day_bucket 1 row 보장. dev_web E2E 점검 큐의 단위."""
    normalized, host = _dev_web_normalize_url(url)
    domain = (domain or host).strip().lower()
    cycle = str(cycle_key or smb_current_cycle_key()).strip()
    now = time.time()
    with connect() as c:
        r = c.execute(
            "SELECT id FROM dev_web_target WHERE url=? AND day_bucket=?",
            (normalized, day_bucket),
        ).fetchone()
        if r is not None:
            c.execute(
                "UPDATE dev_web_target SET domain=?, event_count=?, priority_score=?, "
                "cycle_key=?, last_seen_at=? "
                "WHERE id=?",
                (domain, event_count, int(priority_score), cycle, now, r["id"]),
            )
            return int(r["id"])
        cur = c.execute(
            "INSERT INTO dev_web_target"
            "(url, domain, source, day_bucket, status, event_count, priority_score, "
            " discovered_at, last_seen_at, cycle_key) "
            "VALUES (?, ?, ?, ?, 'pending', ?, ?, ?, ?, ?)",
            (
                normalized, domain, source, day_bucket, event_count, int(priority_score),
                now, now, cycle,
            ),
        )
        return int(cur.lastrowid)


def dev_web_target_set_status(target_id: int, status: str, **fields: Any) -> None:
    if status not in _DEV_WEB_TARGET_STATUSES:
        raise ValueError(f"invalid dev_web_target status: {status!r}")
    _validate_column_names(fields.keys())
    sets = ["status=?", "last_task_at=?"]
    args: list[Any] = [status, time.time()]
    if status != "in_progress":
        if "retry_after" not in fields:
            sets.append("retry_after=?")
            args.append(None)
        if "claimed_by" not in fields:
            sets.append("claimed_by=?")
            args.append(None)
        if "claimed_at" not in fields:
            sets.append("claimed_at=?")
            args.append(None)
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(target_id)
    with connect() as c:
        c.execute(f"UPDATE dev_web_target SET {', '.join(sets)} WHERE id=?", args)


def dev_web_target_get(target_id: int) -> dict[str, Any] | None:
    with connect() as c:
        r = c.execute("SELECT * FROM dev_web_target WHERE id=?", (target_id,)).fetchone()
    return {k: r[k] for k in r.keys()} if r else None


def dev_web_target_claim_next(
    *,
    session_id: int,
    day_bucket: str | None = None,
    cycle_key: str | None = None,
    stale_seconds: float = DEV_WEB_CLAIM_STALE_SECONDS,
    cooldown_seconds: float = DEV_WEB_RESCAN_SECONDS,
) -> dict[str, Any] | None:
    """pending/stale/cooldown target 1개를 atomic claim."""
    now = time.time()
    cutoff = now - stale_seconds
    fresh_cutoff = now - cooldown_seconds
    cycle = str(cycle_key or smb_current_cycle_key()).strip()
    pick_where = (
        "(status='pending' "
        "OR (status='in_progress' AND claimed_at IS NOT NULL AND claimed_at < ?) "
        "OR (status IN ('tasked','skipped','error') "
        "AND (last_task_at IS NULL OR last_task_at < ?))) "
        "AND (retry_after IS NULL OR retry_after <= ?)"
    )
    pick_args: list[Any] = [cutoff, fresh_cutoff, now]
    filters = ["cycle_key=?"]
    filter_args: list[Any] = [cycle]
    if day_bucket is not None:
        filters.append("day_bucket=?")
        filter_args.append(day_bucket)
    filter_sql = " AND ".join(filters)
    sql = (
        "UPDATE dev_web_target SET status='in_progress', claimed_by=?, claimed_at=? "
        "WHERE id = ("
        "SELECT id FROM dev_web_target "
        f"WHERE {filter_sql} AND ({pick_where}) "
        "ORDER BY (last_task_at IS NULL) DESC, priority_score DESC, event_count DESC, "
        "last_task_at ASC, id ASC LIMIT 1 FOR UPDATE SKIP LOCKED"
        ") RETURNING *"
    )
    with connect() as c:
        r = c.execute(sql, (session_id, now, *filter_args, *pick_args)).fetchone()
    return {k: r[k] for k in r.keys()} if r else None


def dev_web_reclaim_stale_claims(
    *, stale_seconds: float = DEV_WEB_CLAIM_STALE_SECONDS,
) -> int:
    """⚠️ **2026-08-28 현재 런타임 호출부가 없다.**

    유일한 호출부였던 평면 task 팬아웃 어댑터가 은퇴하면서 함께 지워졌다.

    ✅ **정정(2026-08-28)**: "물린 `in_progress` 를 푸는 주체가 없다" 고 처음 적었는데
       그건 과했다. 리드 어댑터의 `claimable_statuses` 가 `in_progress` 를 **포함**한다
       (4도메인 전부 — `DEV_WEB_STATUSES` 등). 그래서 죽은 워커가 물고 있던 행도
       다음 리드 패스가 다시 집는다. 영구히 잠기지 않는다.

    ⚠️ 다만 성질이 **바뀌었다**. 옛 백스톱은 stale 임계(claimed_at < now-N)를 보고 나서야
       claim 을 풀었다. 지금 리드는 그런 검사 없이 `in_progress` 를 그냥 다시 목록에 올린다
       — 즉 위험이 "영원히 잠김" 에서 "아직 도는 검토원의 타깃을 다시 위임" 쪽으로 옮겼다.
       (`lead_tools` 의 `_CLOSED` 장부는 같은 패스 안에서만 유효하다.)
       리드에 stale 인지 백스톱을 세울 때 이 함수를 그 경로에 물려라.
    """
    return _reclaim_stale_claims("dev_web_target", stale_seconds=stale_seconds)


def dev_web_targets_pending(
    *, day_bucket: str | None = None, cycle_key: str | None = None, limit: int = 200,
) -> list[dict[str, Any]]:
    where = ["status='pending'"]
