def _dev_web_merge_sev(a: str | None, b: str | None) -> str | None:
    if a is None:
        return b
    if b is None:
        return a
    return _sev.merge(a, b)


def normalize_dev_web_subject_tag(domain: str) -> str:
    return f"[Dev Web 보안취약점 조치요청]({str(domain or '').strip().lower()})"


def dev_web_report_thread_upsert(
    *,
    target_id: int | None,
    finding_id: int | None,
    domain: str,
    url: str,
    subject_tag: str | None = None,
    severity: str | None = None,
    recipient: str | None = None,
    status: str = "draft",
    report_json: dict[str, Any] | None = None,
    cycle_key: str | None = None,
) -> tuple[str, int]:
    """dev_web 사이트 단위 report thread 생성/병합."""
    if status not in _DEV_WEB_REPORT_STATUSES:
        raise ValueError(f"invalid dev_web_report_thread status: {status!r}")
    normalized, host = _dev_web_normalize_url(url)
    domain = (domain or host).strip().lower()
    tag = subject_tag or normalize_dev_web_subject_tag(domain)
    sev = (severity or "").strip().lower() or None
    now = time.time()
    cur_cycle = str(cycle_key or smb_current_cycle_key()).strip()
    payload = json.dumps(report_json or {}, ensure_ascii=False)
    open_statuses = tuple(s for s in _DEV_WEB_REPORT_STATUSES if s not in _DEV_WEB_REPORT_TERMINAL)
    placeholders = ",".join("?" for _ in open_statuses)
    with connect() as c:
        row = None
        if target_id is not None:
            row = c.execute(
                f"SELECT * FROM dev_web_report_thread WHERE target_id=? "
                f"AND status IN ({placeholders}) AND last_cycle_key=? "
                "ORDER BY updated_at DESC LIMIT 1",
                (target_id, *open_statuses, cur_cycle),
            ).fetchone()
        if row is None and finding_id is not None:
            row = c.execute(
                f"SELECT * FROM dev_web_report_thread WHERE finding_id=? "
                f"AND status IN ({placeholders}) AND last_cycle_key=? "
                "ORDER BY updated_at DESC LIMIT 1",
                (finding_id, *open_statuses, cur_cycle),
            ).fetchone()
        if row is None:
            previous_cycles = _dev_web_report_thread_previous_cycles(
                c,
                domain=domain,
                finding_id=finding_id,
                current_cycle=cur_cycle,
            )
            cycles = [*previous_cycles, cur_cycle] if previous_cycles else [cur_cycle]
            cur = c.execute(
                "INSERT INTO dev_web_report_thread"
                "(target_id, finding_id, domain, url, subject_tag, severity, status, "
                "recipient, report_json, first_reported_at, first_cycle_key, "
                "last_cycle_key, cycle_keys, created_at, updated_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (target_id, finding_id, domain, normalized, tag, sev, status, recipient,
                 payload, now, cur_cycle, cur_cycle, json.dumps(cycles), now, now),
            )
            tid = int(cur.lastrowid)
            if target_id is not None:
                c.execute("UPDATE dev_web_target SET report_thread_id=? WHERE id=?", (tid, target_id))
            return ("recurred" if previous_cycles else "new"), tid

        tid = int(row["id"])
        if finding_id is not None and row["finding_id"] == finding_id:
            c.execute(
                "UPDATE dev_web_report_thread SET severity=?, report_json=?, updated_at=? WHERE id=?",
                (_dev_web_merge_sev(row["severity"], sev), payload, now, tid),
            )
            return "dup", tid
        # ⚠️ 진행한 스레드를 되돌리지 않는다. `status` 의 기본값 "draft" 는 **생성** 기본값이고
        #    유일한 운영 호출부(dev_web_submit_finding_tool)가 언제나 그 값을 넘긴다. 병합은
        #    "같은 대상에 finding 이 하나 더 붙었다" 는 뜻이지 "처음부터 다시" 가 아니다.
        #    바로 위 dup 분기가 status 를 아예 안 건드리는 것이 그 의도의 증거다.
        #    실측(2026-08-28): 발송을 52회 시도한 스레드가 status=draft 로 앉아 있었다 —
        #    병합 후보 SELECT 가 terminal(remediated/closed) 외 전부를 잡으므로
        #    reported·awaiting_reply 도 여기로 들어와 강등됐다.
        merged_status = status if str(row["status"] or "") == "draft" else row["status"]
        c.execute(
            "UPDATE dev_web_report_thread SET finding_id=COALESCE(?, finding_id), "
            "severity=?, report_json=?, status=?, recipient=COALESCE(?, recipient), "
            "updated_at=? WHERE id=?",
            (finding_id, _dev_web_merge_sev(row["severity"], sev), payload,
             merged_status, recipient, now, tid),
        )
        return "merged", tid


def _dev_web_report_thread_previous_cycles(
    c: Any,
    *,
    domain: str,
    finding_id: int | None,
    current_cycle: str,
) -> list[str]:
    clauses = ["domain=?"]
    args: list[Any] = [domain]
    if finding_id is not None:
        clauses.append("finding_id=?")
        args.append(finding_id)
    args.append(current_cycle)
    rows = c.execute(
        "SELECT * FROM dev_web_report_thread "
        f"WHERE ({' OR '.join(clauses)}) AND COALESCE(last_cycle_key, '')<>? "
        "ORDER BY updated_at DESC",
        args,
    ).fetchall()
    cycles: list[str] = []
    for row in rows:
        for key in _report_thread_cycle_list_from_row(row):
            if key and key != current_cycle and key not in cycles:
                cycles.append(key)
    return sorted(cycles)


def dev_web_report_thread_promote_target(
    target_id: int, *, restamp_cycle: bool = False,
) -> int:
    """점검이 끝난 target 의 draft 를 조치요청 큐로 올린다.

    ## ⚠️ `last_cycle_key` 는 dev_web 에서 "이번 주 스캔" 을 뜻하지 않는다

    dev_web upsert 는 github·smb 과 달리 이 컬럼을 **INSERT 때 한 번만** 쓴다
    (`dev_web_report_thread_requeue_ready` 주석이 같은 함정을 적어 뒀다). 그래서
    이 필터는 "스캔이 이번 주 것" 이 아니라 **"스레드가 이번 주에 만들어졌다"** 를
    거른다 — 지난주에 열린 스레드는 이번 주에 점검이 끝나도 영영 안 올라간다.

    실측 2026-08-31: 점검이 끝난 draft 47건 중 **44건이 W35 로 찍혀** 막혀 있었다.

    `restamp_cycle=True` 면 저장된 주차와 무관하게 올리고 **현재 주차를 찍는다** —
    `requeue_ready` 가 하는 것과 같다("주차를 찍는 것이 그 함수의 핵심" 이라고 적혀
    있다). 안 찍으면 status 만 바뀌고 `claim_next` 가 여전히 못 집는다.

    ⚠️ smb 의 주기 필터는 **그대로 둔다.** 거긴 컬럼이 실제로 스캔 주차를 따라가므로
       "지난주 결과를 오늘 사실처럼 보내지 않는다" 는 뜻이 살아 있다.
    """
    now = time.time()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        if restamp_cycle:
            r = c.execute(
                "UPDATE dev_web_report_thread SET status='reported', updated_at=?, "
                "first_reported_at=COALESCE(first_reported_at, ?), "
                "last_cycle_key=?, claimed_by=NULL, claimed_at=NULL "
                "WHERE target_id=? AND status='draft'",
                (now, now, cycle_key, target_id),
            )
        else:
            r = c.execute(
                "UPDATE dev_web_report_thread SET status='reported', updated_at=?, "
                "first_reported_at=COALESCE(first_reported_at, ?), claimed_by=NULL, claimed_at=NULL "
                "WHERE target_id=? AND status='draft' AND last_cycle_key=?",
                (now, now, target_id, cycle_key),
            )
        return r.rowcount


def dev_web_report_thread_requeue_ready(
    *,
    only_prefix: str | None = None,
    cycle_key: str | None = None,
    limit: int | None = None,
) -> int:
    """`report_ready` → `reported`. 파킹된 스레드를 청구 큐로 되돌린다.

    자율발송이 켜지는 날 파킹분이 다시 흐르게 하는 **되돌리는 문**이다.

    ⚠️ **주차를 넘어서 훑고, 되돌릴 때 주차를 함께 찍는다.** `claim_next` 와 병합 후보
       SELECT 는 둘 다 `last_cycle_key=현재주차` 인데, dev_web upsert 는 github 과 달리
       `last_cycle_key` 를 **한 번도 갱신하지 않는다**. 그래서 주차가 넘어간 파킹분은
       status 만 되돌려도 아무도 청구하지 않는다 — 주차를 찍는 것이 이 함수의 핵심이다.
    ⚠️ 접두어 매칭을 SQL LIKE 로 하지 않는다 — 토큰의 `_` 가 LIKE 에서 임의 1문자다.
    """
    now = time.time()
    cur_cycle = smb_current_cycle_key()
    sql = "SELECT * FROM dev_web_report_thread WHERE status='report_ready'"
    args: list[Any] = []
    if cycle_key:
        sql += " AND last_cycle_key=?"
        args.append(str(cycle_key).strip())
    sql += " ORDER BY updated_at ASC"
    n = 0
    with connect() as c:
        for row in c.execute(sql, tuple(args)).fetchall():
            if only_prefix and not str(row["last_reason"] or "").startswith(only_prefix):
                continue
            if limit is not None and n >= int(limit):
                break
            try:
                cycles = json.loads(str(row["cycle_keys"] or "[]"))
                if not isinstance(cycles, list):
                    cycles = []
            except (ValueError, TypeError):
                cycles = []
            if cur_cycle not in cycles:
                cycles.append(cur_cycle)
            c.execute(
                "UPDATE dev_web_report_thread SET status='reported', "
                "claimed_by=NULL, claimed_at=NULL, retry_after=NULL, "
                "first_cycle_key=COALESCE(first_cycle_key, ?), last_cycle_key=?, "
                "cycle_keys=?, updated_at=? WHERE id=? AND status='report_ready'",
                (cur_cycle, cur_cycle, json.dumps(cycles), now, int(row["id"])),
            )
            n += 1
    return n


def dev_web_report_thread_retry_if_status(
    thread_id: int,
    *,
    expect_status: str,
    status: str,
    retry_after: float | None = None,
    last_reason: str | None = None,
) -> bool:
    """`expect_status` 인 동안에만 되돌린다 — **파킹을 덮지 않기 위한 원자 가드.**

    fanout 의 실패 복귀(`release(success=False)`)는 status 를 무조건 덮었다. 파킹이
    없던 시절엔 reported→reported 라 무해했지만, 파킹이 생기면 그것이 파킹을 푸는
    유일한 무조건 경로가 된다 — 토큰까지 지워서 되돌리는 문이 영영 0행이 된다.
    """
    if status not in _DEV_WEB_REPORT_STATUSES:
        raise ValueError(f"invalid dev_web_report_thread status: {status!r}")
    with connect() as c:
        r = c.execute(
            "UPDATE dev_web_report_thread SET status=?, retry_after=?, "
            "last_reason=COALESCE(?, last_reason), claimed_by=NULL, claimed_at=NULL, "
            "updated_at=? WHERE id=? AND status=?",
            (status, retry_after, last_reason, time.time(), thread_id, expect_status),
        )
        return bool(r.rowcount)


def dev_web_report_thread_get(thread_id: int) -> dict[str, Any] | None:
    with connect() as c:
        r = c.execute("SELECT * FROM dev_web_report_thread WHERE id=?", (thread_id,)).fetchone()
    return {k: r[k] for k in r.keys()} if r else None


def dev_web_report_thread_set_status(thread_id: int, status: str, **fields: Any) -> None:
    if status not in _DEV_WEB_REPORT_STATUSES:
        raise ValueError(f"invalid dev_web_report_thread status: {status!r}")
    _validate_column_names(fields.keys())
    sets = ["status=?", "updated_at=?"]
    args: list[Any] = [status, time.time()]
    if "retry_after" not in fields:
        sets.append("retry_after=?")
        args.append(None)
    if status != "reverifying":
        if "claimed_by" not in fields:
            sets.append("claimed_by=?")
            args.append(None)
        if "claimed_at" not in fields:
            sets.append("claimed_at=?")
            args.append(None)
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(thread_id)
    with connect() as c:
        c.execute(f"UPDATE dev_web_report_thread SET {', '.join(sets)} WHERE id=?", args)


def dev_web_report_thread_bump_attempt(thread_id: int, *, reason: str | None = None) -> int:
    now = time.time()
    with connect() as c:
        row = c.execute(
            "UPDATE dev_web_report_thread SET attempt_count=attempt_count+1, "
            "last_reason=COALESCE(?, last_reason), updated_at=? WHERE id=? RETURNING attempt_count",
            (reason, now, thread_id),
        ).fetchone()
    return int(row["attempt_count"]) if row else 0


def dev_web_report_thread_claim_next(
    *,
    session_id: int,
    status: str,
    cycle_key: str | None = None,
    stale_seconds: float = DEV_WEB_CLAIM_STALE_SECONDS,
) -> dict[str, Any] | None:
    now = time.time()
    cutoff = now - stale_seconds
    cycle = str(cycle_key or smb_current_cycle_key()).strip()
    with connect() as c:
        r = c.execute(
            "UPDATE dev_web_report_thread SET claimed_by=?, claimed_at=? WHERE id = ("
            "SELECT id FROM dev_web_report_thread WHERE status=? "
            "AND last_cycle_key=? "
            "AND (retry_after IS NULL OR retry_after <= ?) "
            "AND (claimed_at IS NULL OR claimed_at < ?) "
            # ★ **높음 이상을 먼저 집는다**(사용자 결정 2026-08-31). 예전엔 `updated_at ASC`
        #   순수 FIFO 라, 심각 3건·높음 5건이 낮음 21건 뒤에 줄 서 있었다.
        #   같은 등급 안에서는 오래된 것부터 — 굶는 스레드가 없게.
        "ORDER BY (COALESCE(severity,'') IN ('critical','high')) DESC, "
        "  CASE severity WHEN 'critical' THEN 0 WHEN 'high' THEN 1 "
        "                WHEN 'medium' THEN 2 ELSE 3 END ASC, "
        "  updated_at ASC, id ASC LIMIT 1 FOR UPDATE SKIP LOCKED"
            ") RETURNING *",
            (session_id, now, status, cycle, now, cutoff),
        ).fetchone()
    return {k: r[k] for k in r.keys()} if r else None


def dev_web_report_thread_reclaim_stale(
    *, stale_seconds: float = DEV_WEB_CLAIM_STALE_SECONDS,
) -> int:
    cutoff = time.time() - stale_seconds
    with connect() as c:
        r = c.execute(
            "UPDATE dev_web_report_thread SET claimed_by=NULL, claimed_at=NULL "
            "WHERE claimed_at IS NOT NULL AND claimed_at < ?",
            (cutoff,),
        )
        return r.rowcount


def dev_web_report_threads_overview(
    *, status: str | None = None, cycle_key: str | None = None, limit: int = 100,
) -> list[dict[str, Any]]:
    where: list[str] = []
    args: list[Any] = []
    if status is not None:
        where.append("status=?")
        args.append(status)
    if cycle_key is not None:
        where.append("last_cycle_key=?")
        args.append(cycle_key)
    where_sql = f"WHERE {' AND '.join(where)}" if where else ""
    args.append(max(1, min(int(limit), 1000)))
    with connect() as c:
        rows = c.execute(
            f"SELECT * FROM dev_web_report_thread {where_sql} ORDER BY updated_at DESC LIMIT ?",
            args,
        ).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]


def dev_web_report_thread_status_counts(*, cycle_key: str | None = None) -> dict[str, int]:
    where = ""
    args: list[Any] = []
    if cycle_key is not None:
        where = "WHERE last_cycle_key=?"
        args.append(cycle_key)
    with connect() as c:
        rows = c.execute(
            f"SELECT status, COUNT(*) AS n FROM dev_web_report_thread {where} GROUP BY status",
            args,
        ).fetchall()
    out = {s: 0 for s in _DEV_WEB_REPORT_STATUSES}
    out["total"] = 0
    for r in rows:
        out[r["status"]] = int(r["n"])
        out["total"] += int(r["n"])
    return out


def dev_web_report_thread_cycle_keys(*, limit: int = 24) -> list[str]:
    with connect() as c:
        rows = c.execute(
            "SELECT first_cycle_key, last_cycle_key, cycle_keys FROM dev_web_report_thread "
            "ORDER BY updated_at DESC LIMIT ?",
            (max(1, min(int(limit) * 4, 1000)),),
        ).fetchall()
    seen: list[str] = []
    for row in rows:
        for key in _report_thread_cycle_keys({k: row[k] for k in row.keys()}):
            if key not in seen:
                seen.append(key)
    current = smb_current_cycle_key()
    if current not in seen:
        seen.insert(0, current)
    return sorted(seen, reverse=True)[:max(1, min(int(limit), 100))]


def dev_web_recheck_results_for_thread(thread_id: int) -> list[dict[str, Any]]:
    """이 스레드의 재검증 기록 — 최신 우선.

    ★ 2026-08-31 — dev_web 만 **기록 함수(`_add`)는 있고 조회 함수가 없었다.**
      나머지 셋은 `*_recheck_results_for_thread` / `mail_reverify_results_for_thread`
      가 있다. 그래서 "재검증을 실제로 했는가" 를 dev_web 에서만 확인할 수 없었다.
    """
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM dev_web_recheck_result WHERE thread_id=? "
            "ORDER BY created_at DESC, id DESC",
            (int(thread_id),),
        ).fetchall()
    out: list[dict[str, Any]] = []
    for r in rows:
        d = {k: r[k] for k in r.keys()}
        try:
            d["verification"] = json.loads(d.pop("verification_json") or "{}")
        except Exception:  # noqa: BLE001 — 깨진 JSON 이 조회를 죽이면 안 된다
            d["verification"] = {}
        out.append(d)
    return out


def dev_web_recheck_result_add(
    *,
    thread_id: int,
    target_id: int | None,
    finding_id: int | None,
    domain: str,
    url: str,
    verdict: str,
    verification_json: dict[str, Any] | None = None,
    evidence_ref: str | None = None,
    error: str | None = None,
) -> int:
    normalized, host = _dev_web_normalize_url(url)
    with connect() as c:
        cur = c.execute(
            "INSERT INTO dev_web_recheck_result"
            "(thread_id, target_id, finding_id, domain, url, verdict, verification_json, "
            "evidence_ref, error, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                thread_id, target_id, finding_id, (domain or host).strip().lower(),
                normalized, verdict, json.dumps(verification_json or {}, ensure_ascii=False),
                evidence_ref, error, time.time(),
            ),
        )
        return int(cur.lastrowid)


# ============================================================
# devops_target — v3.61 (github/confluence, web claim 격리)
# ============================================================

_DEVOPS_TARGET_STATUSES = {"pending", "in_progress", "tasked", "skipped", "error"}
DEVOPS_CLAIM_STALE_SECONDS = 1800
# v3.76: rolling 재헌트 — 본 지(last_task_at) 이만큼 지난 SSO 대상도 재claim.
DEVOPS_RESCAN_SECONDS = 86400


def devops_target_cycle_ensure_current(
    *,
    service: str | None = None,
    cycle_key: str | None = None,
) -> dict[str, Any]:
    """Reset DevOps/SSO URL scan progress when a weekly board cycle changes.

    `service` is optional for the generic table, but Confluence SSO uses it so a
    Confluence weekly reset does not perturb unrelated GitHub fallback rows.
    """
    key = cycle_key or smb_current_cycle_key()
    now = time.time()
    # v3.91: 명시적으로 **미래로 미뤄둔** 타깃(retry_after > now)은 주간 리셋에서 건너뛴다.
    # 접근불가 판명(no_access) 타깃에 건 긴 백오프가 매주 리셋에 지워지면 재순환이 그대로
    # 살아난다. 현재 devops_target 의 retry_after writer 는 그 경로 하나뿐이라
    # "미래 retry_after = 의도된 유예"로 읽어도 안전하다.
    where = ["(cycle_key IS NULL OR cycle_key<>?)", "(retry_after IS NULL OR retry_after<=?)"]
    args: list[Any] = [key, key, now]
    if service is not None:
        where.append("service=?")
        args.append(service)
        where.append(
            "id IN (SELECT MAX(id) FROM devops_target WHERE service=? GROUP BY url)"
        )
        args.append(service)
    else:
        where.append(
            "id IN (SELECT MAX(id) FROM devops_target GROUP BY service, url)"
        )
    with connect() as c:
        r = c.execute(
            "UPDATE devops_target SET cycle_key=?, cycle_scanned_at=NULL, "
            "cycle_finding_count=0, status='pending', claimed_by=NULL, claimed_at=NULL, "
            "retry_after=NULL "
            f"WHERE {' AND '.join(where)}",
            args,
        )
    return {"cycle_key": key, "targets_reset": int(r.rowcount or 0), "at": now}


def devops_target_upsert(
    url: str, *, service: str, source: str, day_bucket: str, access_count: int = 0,
    preserve_access_count: bool = False,
) -> int:
    """url × day_bucket 1 row 보장 (web_target_upsert 대응, 별 테이블).

    `preserve_access_count`: 기존 값보다 낮은 access_count 로 덮지 않는다. 프록시 로그가 아닌
    발견 경로(v3.91 전역 code_search)는 트래픽량이 없어 1 을 쓰는데, 같은 repo 를 프록시가
    이미 500 으로 등재했다면 덮는 순간 claim 정렬(access_count DESC)의 신호가 사라진다.
    기본 False = 기존 동작(프록시 재수집은 그날 실제 카운트로 갱신하는 게 맞다).
    """
    url = url.strip()
    if not url:
        raise ValueError("url empty")
    now = time.time()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        r = c.execute(
            "SELECT id, service, cycle_key, access_count FROM devops_target "
            "WHERE url=? AND day_bucket=?",
            (url, day_bucket),
        ).fetchone()
        if r is not None:
            if str(r["service"] or "").strip().lower() != str(service or "").strip().lower():
                return int(r["id"])
            if preserve_access_count:
                access_count = max(int(access_count or 0), int(r["access_count"] or 0))
            if r["cycle_key"] == cycle_key:
                c.execute(
                    "UPDATE devops_target SET access_count=?, last_seen_at=? "
                    "WHERE id=?",
                    (access_count, now, r["id"]),
                )
            else:
                # v3.91: 미래 retry_after(=의도된 유예)는 사이클 전환에도 보존한다.
                # 여기서 지우면 접근불가 판명 타깃이 주 경계마다 pending 으로 되살아나
                # `devops_target_cycle_ensure_current` 쪽만 고친 게 무의미해진다.
                c.execute(
                    "UPDATE devops_target SET access_count=?, last_seen_at=?, "
                    "cycle_key=?, cycle_scanned_at=NULL, cycle_finding_count=0, "
                    "status='pending', claimed_by=NULL, claimed_at=NULL, "
                    "retry_after=NULL WHERE id=? "
                    "AND (retry_after IS NULL OR retry_after<=?)",
                    (access_count, now, cycle_key, r["id"], now),
                )
                c.execute(
                    "UPDATE devops_target SET access_count=?, last_seen_at=?, cycle_key=? "
                    "WHERE id=? AND retry_after IS NOT NULL AND retry_after>?",
                    (access_count, now, cycle_key, r["id"], now),
                )
            return int(r["id"])
        cur = c.execute(
            "INSERT INTO devops_target"
            "(url, service, source, day_bucket, status, access_count, "
            " discovered_at, last_seen_at, cycle_key, cycle_finding_count) "
            "VALUES (?, ?, ?, ?, 'pending', ?, ?, ?, ?, 0)",
            (url, service, source, day_bucket, access_count, now, now, cycle_key),
        )
        return int(cur.lastrowid)


def devops_target_set_status(target_id: int, status: str, **fields: Any) -> None:
    """status 전이 + terminal 시 claim 해제 (web_target_set_status 대응)."""
    if status not in _DEVOPS_TARGET_STATUSES:
        raise ValueError(f"invalid devops_target status: {status!r}")
    _validate_column_names(fields.keys())
    sets = ["status=?", "last_task_at=?"]
    args: list[Any] = [status, time.time()]
    if "cycle_key" not in fields:
        sets.append("cycle_key=?")
        args.append(smb_current_cycle_key())
    if status != "in_progress":
        if "retry_after" not in fields:
            sets.append("retry_after=?")
            args.append(None)
        if "cycle_scanned_at" not in fields:
            sets.append("cycle_scanned_at=?")
            args.append(time.time())
        if "cycle_finding_count" not in fields:
            sets.append("cycle_finding_count=?")
            args.append(int(fields.get("finding_count") or 0))
        if "claimed_by" not in fields:
            sets.append("claimed_by=?")
            args.append(None)
        if "claimed_at" not in fields:
            sets.append("claimed_at=?")
            args.append(None)
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(target_id)
    with connect() as c:
        c.execute(
            f"UPDATE devops_target SET {', '.join(sets)} WHERE id=?", args,
        )


def devops_target_get(target_id: int) -> dict[str, Any] | None:
    with connect() as c:
        r = c.execute(
            "SELECT * FROM devops_target WHERE id=?", (target_id,),
        ).fetchone()
    return {k: r[k] for k in r.keys()} if r is not None else None


def devops_target_claim_next(
    *,
    session_id: int,
    day_bucket: str | None = None,
    stale_seconds: float = DEVOPS_CLAIM_STALE_SECONDS,
    cooldown_seconds: float = DEVOPS_RESCAN_SECONDS,
    service: str | None = None,
    cycle_key: str | None = None,
) -> dict[str, Any] | None:
    """pending(또는 stale in_progress, 또는 cooldown 지난 tasked) URL 1개 atomic claim. None=완료.

    web_target_claim_next 로직 복제(별 테이블) — web 공통 claim 함수는 안 건드림.
    v3.74: `service`('github'/'confluence') 지정 시 해당 service 타깃만 claim
    (github-batch/confluence-batch 분리). None 이면 service 무관 claim(레거시/generic).
    v3.76 rolling 통일: 안 본 것(last_task_at NULL) 먼저 → access_count desc(proxy 트래픽
    secondary) → 본 지 오래된 순 → id asc. terminal row 도 cooldown 지나면 재헌트."""
    now = time.time()
    cutoff = now - stale_seconds
    fresh_cutoff = now - cooldown_seconds
    if cycle_key is not None:
        devops_target_cycle_ensure_current(service=service, cycle_key=cycle_key)
    pick_where = (
        "(status='pending' "
        "OR (status='in_progress' AND claimed_at IS NOT NULL AND claimed_at < ?) "
        "OR (status IN ('tasked','skipped','error') "
        "AND (last_task_at IS NULL OR last_task_at < ?))) "
        "AND (retry_after IS NULL OR retry_after <= ?)"
    )
    order_by = (
        "(last_task_at IS NULL) DESC, access_count DESC, last_task_at ASC, id ASC"
    )
    # 순서 주의: SQL placeholder 순 = day_bucket → service → cycle → cutoff → fresh_cutoff → now.
    pick_args: list[Any] = []
    day_clause = ""
    if day_bucket is not None:
        day_clause = "day_bucket=? AND "
        pick_args.append(day_bucket)
    service_clause = ""
    if service is not None:
        service_clause = "service=? AND "
        pick_args.append(service)
    cycle_clause = ""
    if cycle_key is not None:
        cycle_clause = "cycle_key=? AND "
        pick_args.append(cycle_key)
        pick_where = (
            "(status != 'in_progress' OR (claimed_at IS NOT NULL AND claimed_at < ?)) "
            "AND (cycle_scanned_at IS NULL OR last_task_at IS NULL OR last_task_at < ?) "
            "AND (retry_after IS NULL OR retry_after <= ?)"
        )
        order_by = (
            "(cycle_scanned_at IS NULL) DESC, (last_task_at IS NULL) DESC, "
            "access_count DESC, last_task_at ASC, id ASC"
        )
    pick_args.append(cutoff)
    pick_args.append(fresh_cutoff)
    pick_args.append(now)
    inner_lock = "FOR UPDATE SKIP LOCKED"  # v3.76: 단일 postgres
    sql = (
        "UPDATE devops_target SET status='in_progress', "
        "claimed_by=?, claimed_at=? WHERE id = ("
        "SELECT id FROM devops_target "
        f"WHERE {day_clause}{service_clause}{cycle_clause}({pick_where}) "
        f"ORDER BY {order_by} LIMIT 1 {inner_lock}"
        ") RETURNING *"
    )
    args = [session_id, now, *pick_args]
    with connect() as c:
        r = c.execute(sql, args).fetchone()
    return {k: r[k] for k in r.keys()} if r is not None else None


def devops_reclaim_stale_claims(*, stale_seconds: float = DEVOPS_CLAIM_STALE_SECONDS) -> int:
    """v3.80 Slice0b — devops_target 진행 불능 claim 해제. _reclaim_stale_claims 참조."""
    return _reclaim_stale_claims("devops_target", stale_seconds=stale_seconds)


def devops_targets_summary(
    *,
    day_bucket: str | None = None,
    service: str | None = None,
    cycle_key: str | None = None,
) -> dict[str, int]:
    where = []
    args: list[Any] = []
    if day_bucket is not None:
        where.append("day_bucket=?")
        args.append(day_bucket)
    if service is not None:
        where.append("service=?")
        args.append(service)
    if cycle_key is not None:
        where.append("cycle_key=?")
        args.append(cycle_key)
    where_sql = ("WHERE " + " AND ".join(where)) if where else ""
    q = f"SELECT status, COUNT(*) AS n FROM devops_target {where_sql} GROUP BY status"
    with connect() as c:
        rows = c.execute(q, args).fetchall()
        never = c.execute(
            "SELECT COUNT(*) AS n FROM devops_target "
            f"{where_sql}{' AND' if where_sql else 'WHERE'} cycle_scanned_at IS NULL",
            args,
        ).fetchone()
        scanned = c.execute(
            "SELECT COUNT(*) AS n FROM devops_target "
            f"{where_sql}{' AND' if where_sql else 'WHERE'} cycle_scanned_at IS NOT NULL",
            args,
        ).fetchone()
    out = {s: 0 for s in _DEVOPS_TARGET_STATUSES}
    out["total"] = 0
    for r in rows:
        out[r["status"]] = int(r["n"])
        out["total"] += int(r["n"])
    out["never_scanned"] = int(never["n"])
    out["scanned"] = int(scanned["n"])
    if cycle_key is not None:
        out["cycle_key"] = cycle_key
    return out


# ============================================================
# github_repo_target — v3.75 (전사 repo rolling 스윕, bounded, oldest-first)
# ============================================================

_GITHUB_REPO_STATUSES = {"pending", "in_progress", "tasked", "skipped", "error"}
GITHUB_REPO_CLAIM_STALE_SECONDS = 1800      # in_progress 가 이만큼 묵으면 재claim
GITHUB_REPO_RESCAN_SECONDS = 86400          # 본 지 이만큼 지나야 재스캔(cooldown)


def _target_cycle_ensure_current(table: str, *, cycle_key: str | None = None) -> dict[str, Any]:
    if table not in {"github_repo_target", "confluence_space_target", "confluence_search_target"}:
        raise ValueError(f"unsupported target cycle table: {table!r}")
    key = cycle_key or smb_current_cycle_key()
    now = time.time()
    with connect() as c:
        r = c.execute(
            f"UPDATE {table} SET cycle_key=?, cycle_scanned_at=NULL, "
            "cycle_finding_count=0, status='pending', claimed_by=NULL, claimed_at=NULL, "
            "retry_after=NULL "
            "WHERE cycle_key IS NULL OR cycle_key<>?",
            (key, key),
        )
    return {"cycle_key": key, "targets_reset": int(r.rowcount or 0), "at": now}


def github_repo_cycle_ensure_current(cycle_key: str | None = None) -> dict[str, Any]:
    """Reset GitHub repo scan progress when the weekly board cycle changes."""
    return _target_cycle_ensure_current("github_repo_target", cycle_key=cycle_key)


def github_repo_target_upsert(
    repo: str, *, default_branch: str | None = None, pushed_at: str | None = None,
) -> int:
    """repo 1 row 보장(bounded). 기존 repo 는 메타만 갱신(last_scanned_at/status 보존)."""
    repo = (repo or "").strip()
    if not repo:
        raise ValueError("repo empty")
    now = time.time()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        r = c.execute(
            "SELECT id, cycle_key FROM github_repo_target WHERE repo=?", (repo,),
        ).fetchone()
        if r is not None:
            if r["cycle_key"] == cycle_key:
                c.execute(
                    "UPDATE github_repo_target SET default_branch=?, pushed_at=?, last_seen=? "
                    "WHERE id=?",
                    (default_branch, pushed_at, now, r["id"]),
                )
            else:
                c.execute(
                    "UPDATE github_repo_target SET default_branch=?, pushed_at=?, last_seen=?, "
                    "cycle_key=?, cycle_scanned_at=NULL, cycle_finding_count=0, "
                    "status='pending', claimed_by=NULL, claimed_at=NULL, "
                    "retry_after=NULL WHERE id=?",
                    (default_branch, pushed_at, now, cycle_key, r["id"]),
                )
            return int(r["id"])
        cur = c.execute(
            "INSERT INTO github_repo_target"
            "(repo, default_branch, pushed_at, status, finding_count, first_seen, last_seen, "
            "cycle_key, cycle_finding_count) "
            "VALUES (?, ?, ?, 'pending', 0, ?, ?, ?, 0)",
            (repo, default_branch, pushed_at, now, now, cycle_key),
        )
        return int(cur.lastrowid)


def github_repo_target_claim_next(
    *,
    session_id: int,
    limit: int = 1,
    stale_seconds: float | None = None,
    cooldown_seconds: float | None = None,
) -> list[dict[str, Any]]:
    """oldest-first(한 번도 안 본 것 먼저 → 본 지 오래된 순) rolling claim. 최대 `limit`개.

    claim 대상 = 이번 주 미스캔 target 먼저, 이후 같은 주기 안의 cooldown 재스캔.
    빈 list = 지금 claim 할 stale 대상 없음(다 fresh/소진). bounded(누적 X)."""
    github_repo_cycle_ensure_current()
    stale = GITHUB_REPO_CLAIM_STALE_SECONDS if stale_seconds is None else stale_seconds
    cooldown = GITHUB_REPO_RESCAN_SECONDS if cooldown_seconds is None else cooldown_seconds
    n = max(1, int(limit))
    now = time.time()
    cycle_key = smb_current_cycle_key()
    claim_cutoff = now - stale
    fresh_cutoff = now - cooldown
    pick_where = (
        "cycle_key=? "
        "AND (status != 'in_progress' OR (claimed_at IS NOT NULL AND claimed_at < ?)) "
        "AND (cycle_scanned_at IS NULL OR last_scanned_at IS NULL OR last_scanned_at < ?) "
        "AND (retry_after IS NULL OR retry_after <= ?)"
    )
    inner_lock = "FOR UPDATE SKIP LOCKED"  # v3.76: 단일 postgres
    sql = (
        "UPDATE github_repo_target SET status='in_progress', claimed_by=?, claimed_at=? "
        "WHERE id IN ("
        "SELECT id FROM github_repo_target "
        f"WHERE {pick_where} "
        "ORDER BY (cycle_scanned_at IS NULL) DESC, "
        "(last_scanned_at IS NULL) DESC, last_scanned_at ASC, id ASC "
        f"LIMIT {n} {inner_lock}"
        ") RETURNING *"
    )
    args = [session_id, now, cycle_key, claim_cutoff, fresh_cutoff, now]
    with connect() as c:
        rows = c.execute(sql, args).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]


def github_repo_reclaim_stale_claims(
    *, stale_seconds: float = GITHUB_REPO_CLAIM_STALE_SECONDS,
) -> int:
    """v3.80 Slice0b — github_repo_target 진행 불능 claim 해제.

    rolling 테이블이라 status='pending' 리셋 + last_scanned_at 불변 → 즉시 재claim 대상.
    """
    return _reclaim_stale_claims("github_repo_target", stale_seconds=stale_seconds)


def github_repo_target_set_status(target_id: int, status: str, **fields: Any) -> None:
    """status 전이.

    비-in_progress(처리완료)는 last_scanned_at와 현재 cycle_scanned_at를 함께 찍어
    이번 주 fresh queue 에서는 빠지고, cooldown 재스캔은 기존 rolling 간격을 따른다.
    """
    if status not in _GITHUB_REPO_STATUSES:
        raise ValueError(f"invalid github_repo_target status: {status!r}")
    _validate_column_names(fields.keys())
    sets = ["status=?"]
    args: list[Any] = [status]
    now = time.time()
    if "cycle_key" not in fields:
        sets.append("cycle_key=?")
        args.append(smb_current_cycle_key())
    if status != "in_progress":
        if "retry_after" not in fields:
            sets.append("retry_after=?")
            args.append(None)
        if "last_scanned_at" not in fields:
            sets.append("last_scanned_at=?")
            args.append(now)
        if "cycle_scanned_at" not in fields:
            sets.append("cycle_scanned_at=?")
            args.append(now)
        if "cycle_finding_count" not in fields:
            sets.append("cycle_finding_count=?")
            args.append(int(fields.get("finding_count") or 0))
        if "claimed_by" not in fields:
            sets.append("claimed_by=?")
            args.append(None)
        if "claimed_at" not in fields:
            sets.append("claimed_at=?")
            args.append(None)
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(target_id)
    with connect() as c:
        c.execute(
            f"UPDATE github_repo_target SET {', '.join(sets)} WHERE id=?", args,
        )


def github_repo_target_get(target_id: int) -> dict[str, Any] | None:
    with connect() as c:
        r = c.execute(
            "SELECT * FROM github_repo_target WHERE id=?", (target_id,),
        ).fetchone()
        return {k: r[k] for k in r.keys()} if r is not None else None


def github_repo_set_scanned_sha(repo: str, sha: str | None) -> None:
    """v3.78 G1: commit fetch dedup 커서(마지막 스캔 HEAD sha) 갱신.

    Explicit repo scans may discover commits before discovery has inserted a
    `github_repo_target` row. Preserve the cursor anyway so the next scan starts
    after the already-checked commit. Clearing (`sha is None`) still only touches
    an existing row.
    """
    repo = (repo or "").strip()
    if not repo:
        return
    if sha is None:
        with connect() as c:
            c.execute(
                "UPDATE github_repo_target SET last_scanned_sha=? WHERE repo=?",
                (None, repo),
            )
        return
    now = time.time()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        c.execute(
            "INSERT INTO github_repo_target"
            "(repo, status, first_seen, last_seen, cycle_key, cycle_finding_count, "
            "last_scanned_sha) "
            "VALUES (?, 'pending', ?, ?, ?, 0, ?) "
            "ON CONFLICT (repo) DO UPDATE SET "
            "last_scanned_sha=EXCLUDED.last_scanned_sha, "
            "last_seen=EXCLUDED.last_seen",
            (repo, now, now, cycle_key, sha),
        )


def github_repo_get_scanned_sha(repo: str) -> str | None:
    """v3.78 G1: repo 의 마지막 스캔 sha. row 없거나 미설정이면 None(전체 스캔)."""
    with connect() as c:
        r = c.execute(
            "SELECT last_scanned_sha FROM github_repo_target WHERE repo=?", (repo,),
        ).fetchone()
        return (r["last_scanned_sha"] if r is not None else None)


def github_repo_targets_summary() -> dict[str, int]:
    github_repo_cycle_ensure_current()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        rows = c.execute(
            "SELECT status, COUNT(*) AS n FROM github_repo_target "
            "WHERE cycle_key=? GROUP BY status",
            (cycle_key,),
        ).fetchall()
        never = c.execute(
            "SELECT COUNT(*) AS n FROM github_repo_target "
            "WHERE cycle_key=? AND cycle_scanned_at IS NULL",
            (cycle_key,),
        ).fetchone()
        scanned = c.execute(
            "SELECT COUNT(*) AS n FROM github_repo_target "
            "WHERE cycle_key=? AND cycle_scanned_at IS NOT NULL",
            (cycle_key,),
        ).fetchone()
    out = {s: 0 for s in _GITHUB_REPO_STATUSES}
    out["total"] = 0
    for r in rows:
        out[r["status"]] = int(r["n"])
        out["total"] += int(r["n"])
    out["never_scanned"] = int(never["n"])
    out["scanned"] = int(scanned["n"])
    out["cycle_key"] = cycle_key
    return out


# ============================================================
# github_report_thread — GitHub E2E repo report/recheck state
# ============================================================

_GITHUB_REPORT_THREAD_STATUSES = {
    "draft", "reported", "report_ready", "awaiting_owner",
    "recheck_requested", "rechecking", "partially_remediated",
    "remediated", "still_open", "exception_review", "owner_update_needed",
    "owner_reassignment_review", "reassigned", "escalated", "closed", "error",
}
_GITHUB_REPORT_OPEN_STATUSES = (
    "draft", "reported", "report_ready", "awaiting_owner",
    "recheck_requested", "rechecking", "partially_remediated",
    "still_open", "exception_review", "owner_update_needed",
    "owner_reassignment_review", "reassigned", "escalated", "error",
)
GITHUB_REPORT_THREAD_CLAIM_STALE_SECONDS = 1800
SERVICE_RECHECK_RETRY_SECONDS = 8 * 3600
_GITHUB_SEV_RANK = _sev.RANK


def service_recheck_retry_seconds() -> float:
    raw = os.environ.get("SERVICE_RECHECK_RETRY_SECONDS", "")
    try:
        value = float(raw)
    except ValueError:
        return float(SERVICE_RECHECK_RETRY_SECONDS)
    return value if value > 0 else float(SERVICE_RECHECK_RETRY_SECONDS)


def normalize_github_subject_tag(repo: str) -> str:
    """Repo-scoped report correlation key for GitHub E2E reporting."""
    return f"[GitHub 보안취약점 조치요청]({str(repo or '').strip()})"


def _service_owner_recipient_hint(
    recipient: str | None,
    owner_recipient: str | None,
) -> str | None:
    value = str(owner_recipient if owner_recipient is not None else recipient or "").strip()
    if not value:
        return None
    # ★ 예전엔 리터럴 {"dssoc", "dssoc@samsung.com"} 만 봤다 — **env 를 안 보는 유일한 곳**이었다.
    #   팀함 주소를 env 로 바꾸면 그 주소가 담당자로 잡혀, 화면에 팀함이 사람처럼 뜨고
    #   조치요청이 "당신이 담당자입니다" 로 팀함 앞에 나간다.
    if orx.is_dssoc(value):
        return None
    return value


def _report_thread_finding_ids_from_row(row: Any) -> list[int]:
    out: list[int] = []
    try:
        values = json.loads(row["finding_ids"] or "[]")
    except Exception:
        values = []
    if isinstance(values, list):
        for value in values:
            try:
                fid = int(value)
            except (TypeError, ValueError):
                continue
            if fid not in out:
                out.append(fid)
    try:
        representative = int(row["finding_id"])
    except Exception:
        representative = None
    if representative is not None and representative not in out:
        out.append(representative)
    return out


def _report_thread_cycle_list_from_row(row: Any) -> list[str]:
    keys: list[str] = []
    try:
        values = json.loads(row["cycle_keys"] or "[]")
    except Exception:
        values = []
    if isinstance(values, list):
        for value in values:
            key = str(value or "").strip()
            if key and key not in keys:
                keys.append(key)
    for k in ("first_cycle_key", "last_cycle_key"):
        try:
            key = str(row[k] or "").strip()
        except Exception:
            key = ""
        if key and key not in keys:
            keys.append(key)
    return keys


def _report_thread_previous_cycles(
    c: Any,
    *,
    table: str,
    scope_column: str,
    scope_value: str,
    finding_id: int,
    current_cycle: str,
) -> list[str]:
    if table not in {"github_report_thread", "confluence_report_thread"}:
        raise ValueError(f"invalid report thread table: {table!r}")
    if scope_column not in {"repo", "space_key"}:
        raise ValueError(f"invalid report thread scope column: {scope_column!r}")
    rows = c.execute(
        f"SELECT * FROM {table} WHERE {scope_column}=? "
        "AND COALESCE(last_cycle_key, '')<>? ORDER BY updated_at DESC",
        (scope_value, current_cycle),
    ).fetchall()
    cycles: list[str] = []
    for row in rows:
        if int(finding_id) not in _report_thread_finding_ids_from_row(row):
            continue
        for key in _report_thread_cycle_list_from_row(row):
            if key != current_cycle and key not in cycles:
                cycles.append(key)
    return sorted(cycles)


def _report_thread_cycle_where(cycle_key: str | None) -> tuple[str, list[Any]]:
    key = str(cycle_key or "").strip()
    if not key:
        return "", []
    return "last_cycle_key=?", [key]


def _report_thread_cycle_keys(row: dict[str, Any]) -> list[str]:
    keys: list[str] = []
    for k in ("last_cycle_key", "first_cycle_key"):
        value = str(row.get(k) or "").strip()
        if value and value not in keys:
            keys.append(value)
    try:
        raw = json.loads(row.get("cycle_keys") or "[]")
    except Exception:
        raw = []
    if isinstance(raw, list):
        for value in raw:
            key = str(value or "").strip()
            if key and key not in keys:
                keys.append(key)
    return keys


def _merge_service_recipients(stored: object, incoming: str | None) -> tuple[str | None, bool]:
    """스레드에 쌓인 수신처와 이번 finding 의 수신처를 **합집합**으로 합친다.

    반환: `(합친 문자열|None, 새로 추가된 게 있나)`

    ★ 왜 합집합인가 (2026-08-28 실측). github·confluence 의 report 스레드는
      **저장소/space 단위**라 finding 여러 개를 모은다. 그런데 각 finding 이 자기
      담당자를 스레드에 그대로 덮어써서, 담당자가 다른 둘이 한 스레드를 공유하면
      **매 패스마다 서로 덮어쓰며 싸운다.** 재개 가드가 그 차이를 "리포트 내용이
      바뀌었다" 로 읽어 status 를 report_ready → reported 로 되돌리고 attempt 를 올린다:

          confluence thread 2 (MASKResist)  36576 → hs3h.choi, kh93.park
                                            36577 → kh93.park
          → attempt_count 가 60초마다 **+2**, 관측 시점 541 이고 계속 올라갔다.

      합집합으로 두면 각 finding 의 담당자가 이미 포함된 부분집합이라 "바뀐 게 없다"
      가 되어 순환이 멈춘다. 그리고 **아무도 수신처에서 빠지지 않는다** — 마지막에 쓴
      finding 의 담당자만 남던 예전 동작은 나머지 담당자를 조용히 지우고 있었다.

    ⚠️ 정렬해서 돌려준다. 순서가 흔들리면 그 자체가 "바뀌었다" 로 읽힌다.
    ⚠️ github 이 지금 안 싸우는 건 한 저장소의 finding 들이 담당자가 같아서지
       구조가 달라서가 아니다 — 그래서 두 도메인을 같이 고친다.
    """
    def _split(value: object) -> list[str]:
        return [part.strip() for part in str(value or "").split(",") if part.strip()]

    have = set(_split(stored))
    add = set(_split(incoming))
    if not add:
        return (", ".join(sorted(have)) or None), False
    merged = have | add
    return (", ".join(sorted(merged)) or None), bool(add - have)


def github_report_thread_upsert(
    *,
    finding_id: int,
    repo: str,
    severity: str | None = None,
    recipient: str | None = None,
    owner_recipient: str | None = None,
    status: str = "reported",
    subject_tag: str | None = None,
    cycle_key: str | None = None,
) -> tuple[str, int]:
    """Group GitHub findings into one open report thread per repo.

    Returns (action, thread_id):
    - new: no open repo thread exists.
    - merged: finding was added to an open pre-notification thread.
    - recurred: finding appeared after owner notification; report should be rebuilt.
    - dup: finding was already attached.
    """
    repo = str(repo or "").strip()
    if not repo:
        raise ValueError("repo is required")
    if status not in _GITHUB_REPORT_THREAD_STATUSES:
        raise ValueError(f"invalid github_report_thread status: {status!r}")
    now = time.time()
    cur_cycle = cycle_key or smb_current_cycle_key()
    sev = (severity or "").strip().lower() or None
    tag = subject_tag or normalize_github_subject_tag(repo)
    owner = _service_owner_recipient_hint(recipient, owner_recipient)
    open_in = ",".join("?" for _ in _GITHUB_REPORT_OPEN_STATUSES)
    with connect() as c:
        row = c.execute(
            f"SELECT * FROM github_report_thread WHERE repo=? AND status IN ({open_in}) "
            "AND last_cycle_key=? ORDER BY updated_at DESC LIMIT 1",
            (repo, *_GITHUB_REPORT_OPEN_STATUSES, cur_cycle),
        ).fetchone()
        if row is None:
            previous_cycles = _report_thread_previous_cycles(
                c,
                table="github_report_thread",
                scope_column="repo",
                scope_value=repo,
                finding_id=finding_id,
                current_cycle=cur_cycle,
            )
            cycles = [*previous_cycles, cur_cycle] if previous_cycles else [cur_cycle]
            cur = c.execute(
                "INSERT INTO github_report_thread("
                "repo, finding_id, finding_ids, subject_tag, severity, status, "
                "recipient, owner_recipient, first_reported_at, first_cycle_key, "
                "last_cycle_key, cycle_keys, created_at, updated_at"
                ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id",
                (
                    repo, finding_id, json.dumps([finding_id]), tag, sev, status,
                    recipient, owner, now, cur_cycle, cur_cycle, json.dumps(cycles), now, now,
                ),
            )
            inserted = cur.fetchone()
            return ("recurred" if previous_cycles else "new"), int(inserted["id"])

        tid = int(row["id"])
        try:
            fids = [int(x) for x in json.loads(row["finding_ids"] or "[]")]
        except Exception:
            fids = []
        cycles = _report_thread_cycle_list_from_row(row)
        if cur_cycle not in cycles:
            cycles.append(cur_cycle)
        cycles_json = json.dumps(cycles)
        # ⚠️ 수신처를 **언제 합치고 언제 교체하나.**
        #
        #  · finding 이 **여럿**인 스레드: 이 finding 의 담당자는 전체가 아니라 **기여분**이다.
        #    그대로 덮어쓰면 담당자가 다른 둘이 매 패스마다 서로 덮어쓰며 싸운다
        #    (실측 2026-08-28: confluence attempt_count 가 60초마다 +2, 541 까지).
        #    그리고 조용한 손실도 난다 — TPYE 스레드는 마지막에 쓴 finding 의 담당자만
        #    남아서 `hottie.yang` 이 수신처에서 빠져 있었다. → **합집합.**
        #  · finding 이 **하나**인 스레드: 그 담당자가 곧 스레드의 담당자다. 조회가
        #    정정되거나 담당자가 바뀌면 옛 사람에게 계속 보내면 안 된다. → **교체.**
        #
        # ★ 네 갈래 UPDATE 가 **모두** 이 값을 쓴다 — 한 곳이라도 원본을 쓰면 거기서
        #   다시 덮어써서 순환이 그대로 산다(실제로 두 곳만 고쳤을 때 재현됐다).
        _aggregating = len(fids) > 1 or int(finding_id) not in fids
        if _aggregating:
            merged_recipient, recipient_grew = _merge_service_recipients(
                row["recipient"], recipient)
            merged_owner, owner_grew = _merge_service_recipients(
                row["owner_recipient"], owner)
        else:
            merged_recipient, merged_owner = recipient, owner
            recipient_grew = recipient is not None and str(recipient) != str(
                row["recipient"] or "")
            owner_grew = owner is not None and str(owner) != str(
                row["owner_recipient"] or "")
        if int(finding_id) in fids:
            best = _merge_github_sev(row["severity"], sev)
            report_ready_changed = row["status"] == "report_ready" and (
                best != row["severity"] or recipient_grew or owner_grew
            )
            if report_ready_changed:
                c.execute(
                    "UPDATE github_report_thread SET severity=?, "
                    "status='reported', claimed_by=NULL, claimed_at=NULL, retry_after=NULL, "
                    "attempt_count=attempt_count+1, report_json='{}', report_html=NULL, "
                    "notified_at=NULL, "
                    "recipient=COALESCE(?, recipient), owner_recipient=COALESCE(?, owner_recipient), "
                    "first_cycle_key=COALESCE(first_cycle_key, ?), last_cycle_key=?, "
                    "cycle_keys=?, updated_at=? WHERE id=?",
                    (best, merged_recipient, merged_owner, cur_cycle, cur_cycle,
                     cycles_json, now, tid),
                )
                return "recurred", tid
            c.execute(
                "UPDATE github_report_thread SET severity=?, "
                "recipient=COALESCE(?, recipient), owner_recipient=COALESCE(?, owner_recipient), "
                "first_cycle_key=COALESCE(first_cycle_key, ?), last_cycle_key=?, "
                "cycle_keys=?, updated_at=? WHERE id=?",
                (best, merged_recipient, merged_owner, cur_cycle, cur_cycle,
                 cycles_json, now, tid),
            )
            return "dup", tid

        fids.append(int(finding_id))
        best = _merge_github_sev(row["severity"], sev)
        already_notified = row["status"] in (
            "report_ready", "awaiting_owner", "recheck_requested",
            "rechecking", "partially_remediated", "still_open",
            "exception_review", "owner_update_needed",
            "owner_reassignment_review", "reassigned", "error",
        )
        if already_notified:
            c.execute(
                "UPDATE github_report_thread SET finding_ids=?, severity=?, "
                "status='reported', claimed_by=NULL, claimed_at=NULL, retry_after=NULL, "
                "attempt_count=attempt_count+1, report_json='{}', report_html=NULL, "
                "notified_at=NULL, "
                "recipient=COALESCE(?, recipient), owner_recipient=COALESCE(?, owner_recipient), "
                "first_cycle_key=COALESCE(first_cycle_key, ?), last_cycle_key=?, "
                "cycle_keys=?, updated_at=? WHERE id=?",
                (json.dumps(fids), best, merged_recipient, merged_owner,
                 cur_cycle, cur_cycle, cycles_json, now, tid),
            )
            return "recurred", tid
        c.execute(
            "UPDATE github_report_thread SET finding_ids=?, severity=?, "
            "subject_tag=?, recipient=COALESCE(?, recipient), "
            "owner_recipient=COALESCE(?, owner_recipient), "
            "first_cycle_key=COALESCE(first_cycle_key, ?), "
            "last_cycle_key=?, cycle_keys=?, updated_at=? WHERE id=?",
            (json.dumps(fids), best, tag, merged_recipient, merged_owner,
             cur_cycle, cur_cycle, cycles_json, now, tid),
        )
        return "merged", tid


def _merge_github_sev(a: str | None, b: str | None) -> str | None:
    if a is None:
        return b
    if b is None:
        return a
    return _sev.merge(a, b)


def github_report_thread_get(thread_id: int) -> dict[str, Any] | None:
    with connect() as c:
        r = c.execute(
            "SELECT * FROM github_report_thread WHERE id=?", (thread_id,),
        ).fetchone()
    return {k: r[k] for k in r.keys()} if r else None


def github_report_thread_finding_ids(thread_id: int) -> list[int]:
    t = github_report_thread_get(thread_id)
    if not t:
        return []
    try:
        return [int(x) for x in json.loads(t.get("finding_ids") or "[]")]
    except Exception:
        return []


# ── 스레드가 닫히면 그 finding 도 닫는다 (2026-08-28) ───────────────────────
# smb 는 `mail_thread` 를 remediated 로 닫을 때 finding 도 함께 닫는다(:7038 부근).
# github·confluence 는 그 짝이 **아예 없어서** finding 이 영원히 `open` 이었다 —
# 실측 2026-08-28: finding 92건 전부 open. 스레드는 remediated 인데 finding 은 안 닫혔다.
#
# ⚠️ 엔진 어휘는 {open, triaged, false_positive, accepted_risk, remediated} 다.
#    `"resolved"` 를 쓰면 ValueError 가 나고 호출부가 삼킨다(그게 smb/dev_web 의 6주짜리
#    조용한 실패였다 — 68a39b8). `service/tests/test_finding_status_vocabulary.py` 가 고정한다.
_THREAD_CLOSING_STATUSES = frozenset({"remediated", "closed"})


def _close_findings_for_thread(thread_id: int, table: str) -> int:
    """스레드의 finding 을 remediated 로. 실패해도 스레드 상태 전이를 막지 않는다."""
    from secu_agent import state as _cs

    closed = 0
    try:
        with connect() as c:
            row = c.execute(
                f"SELECT finding_id FROM {table} WHERE id=?", (int(thread_id),)
            ).fetchone()
        fid = row["finding_id"] if row else None
        if fid is None:
            return 0
        _cs.finding_update(int(fid), status="remediated")
        closed = 1
    except Exception:  # noqa: BLE001 — 기록 실패가 스레드 전이를 되돌리지 않는다
        # ⚠️ 이 모듈엔 모듈 로거가 없다. `log` 를 쓰면 except 안에서 NameError 가 나고,
        #    그게 밖으로 튀어 **스레드 전이 자체를 막는다** — 삼키려던 실패가 더 큰 실패가
        #    된다. 실기동 전에 테스트가 잡았다.
        logging.getLogger(__name__).exception(
            "[%s] finding 종료 실패 thread=%s", table, thread_id)
    return closed


def github_report_thread_set_status(thread_id: int, status: str, **fields: Any) -> None:
    if status not in _GITHUB_REPORT_THREAD_STATUSES:
        raise ValueError(f"invalid github_report_thread status: {status!r}")
    _validate_column_names(fields.keys())
    sets = ["status=?", "updated_at=?"]
    args: list[Any] = [status, time.time()]
    if "retry_after" not in fields:
        sets.append("retry_after=?")
        args.append(None)
    if status != "rechecking":
        if "claimed_by" not in fields:
            sets.append("claimed_by=?")
            args.append(None)
        if "claimed_at" not in fields:
            sets.append("claimed_at=?")
            args.append(None)
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(thread_id)
    with connect() as c:
        c.execute(
            f"UPDATE github_report_thread SET {', '.join(sets)} WHERE id=?", args,
        )
    if status in _THREAD_CLOSING_STATUSES:
        _close_findings_for_thread(thread_id, "github_report_thread")


def github_report_thread_schedule_recheck_retry(
    thread_id: int,
    *,
    reason: str,
    retry_seconds: float | None = None,
) -> float:
    reason_text = str(reason or "github recheck retry scheduled")[:1000]
    retry_after = time.time() + (
        retry_seconds if retry_seconds is not None else service_recheck_retry_seconds()
    )
    github_report_thread_set_status(
        thread_id,
        "recheck_requested",
        retry_after=retry_after,
        last_reason=reason_text,
    )
    github_report_thread_bump_attempt(thread_id, reason=reason_text)
    return retry_after


def github_report_thread_claim_next(
    *,
    session_id: int,
    status: str,
    stale_seconds: float = GITHUB_REPORT_THREAD_CLAIM_STALE_SECONDS,
) -> dict[str, Any] | None:
    if status not in _GITHUB_REPORT_THREAD_STATUSES:
        raise ValueError(f"invalid github_report_thread status: {status!r}")
    now = time.time()
    cutoff = now - stale_seconds
    cycle_filter = ""
    owner_filter = ""
    args: list[Any] = [session_id, now, status, now, cutoff]
    if status in {"reported", "recheck_requested"}:
        cycle_filter = "AND last_cycle_key=? "
        args.append(smb_current_cycle_key())
    if status == "reported":
        owner_filter = "AND TRIM(COALESCE(owner_recipient, ''))<>'' "
    with connect() as c:
        r = c.execute(
            "UPDATE github_report_thread SET claimed_by=?, claimed_at=? WHERE id = ("
            "SELECT id FROM github_report_thread WHERE status=? "
            "AND (retry_after IS NULL OR retry_after <= ?) "
            "AND (claimed_at IS NULL OR claimed_at < ?) "
            f"{cycle_filter}"
            f"{owner_filter}"
            # ★ **높음 이상을 먼저 집는다**(사용자 결정 2026-08-31 · 4도메인 통일).
        #   예전엔 순수 FIFO 라 심각·높음이 낮음 뒤에 줄 섰다(smb 실측: 심각 3·높음 5가
        #   낮음 21건 뒤). 같은 등급 안에서는 오래된 것부터 — 굶는 스레드가 없게.
        #   ⚠️ NULL 함정: `severity IN (...)` 은 NULL 이면 NULL 이고 postgres 의 DESC 는
        #      NULL 을 **먼저** 놓는다. COALESCE 로 막는다(리드 정렬에서 실제로 당했다).
        "ORDER BY (COALESCE(severity,'') IN ('critical','high')) DESC, "
        "  CASE severity WHEN 'critical' THEN 0 WHEN 'high' THEN 1 "
        "                WHEN 'medium' THEN 2 ELSE 3 END ASC, "
        "  updated_at ASC, id ASC LIMIT 1 FOR UPDATE SKIP LOCKED"
            ") RETURNING *",
            args,
        ).fetchone()
    return {k: r[k] for k in r.keys()} if r else None


def github_report_thread_reclaim_stale(
    *,
    stale_seconds: float = GITHUB_REPORT_THREAD_CLAIM_STALE_SECONDS,
) -> int:
    cutoff = time.time() - stale_seconds
    with connect() as c:
        r = c.execute(
            "UPDATE github_report_thread SET claimed_by=NULL, claimed_at=NULL "
            "WHERE claimed_at IS NOT NULL AND claimed_at < ?",
            (cutoff,),
        )
        return r.rowcount


def github_report_thread_bump_attempt(thread_id: int, *, reason: str | None = None) -> int:
    with connect() as c:
        cur = c.execute(
            "UPDATE github_report_thread SET attempt_count=attempt_count+1, "
            "last_reason=?, updated_at=? WHERE id=? RETURNING attempt_count",
            (reason, time.time(), thread_id),
        )
        row = cur.fetchone()
    return int(row["attempt_count"]) if row else 0


def github_report_threads_overview(
    *,
    status: str | None = None,
    repo: str | None = None,
    limit: int = 100,
    cycle_key: str | None = None,
) -> list[dict[str, Any]]:
    where: list[str] = []
    args: list[Any] = []
    if status is not None:
        where.append("status=?")
        args.append(status)
    if repo is not None:
        where.append("repo=?")
        args.append(repo)
    cycle_where, cycle_args = _report_thread_cycle_where(cycle_key)
    if cycle_where:
        where.append(cycle_where)
        args.extend(cycle_args)
    where_sql = "WHERE " + " AND ".join(where) if where else ""
    args.append(max(1, min(int(limit), 1000)))
    with connect() as c:
        rows = c.execute(
            f"SELECT * FROM github_report_thread {where_sql} "
            "ORDER BY updated_at DESC LIMIT ?",
            args,
        ).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]


def github_report_thread_status_counts(*, cycle_key: str | None = None) -> dict[str, int]:
    where, args = _report_thread_cycle_where(cycle_key)
    where_sql = f"WHERE {where}" if where else ""
    with connect() as c:
        rows = c.execute(
            f"SELECT status, COUNT(*) AS n FROM github_report_thread {where_sql} "
            "GROUP BY status",
            args,
        ).fetchall()
    out = {s: 0 for s in _GITHUB_REPORT_THREAD_STATUSES}
    for r in rows:
        out[str(r["status"])] = int(r["n"])
    return out


def github_report_thread_queue_count(status: str, *, cycle_key: str | None = None) -> int:
    where = ["status=?"]
    args: list[Any] = [status]
    now = time.time()
    if status == "reported":
        where.append("TRIM(COALESCE(owner_recipient, ''))<>''")
    if status in {"reported", "recheck_requested"}:
        where.append("(retry_after IS NULL OR retry_after <= ?)")
        where.append("(claimed_at IS NULL OR claimed_at < ?)")
        args.extend([now, now - GITHUB_REPORT_THREAD_CLAIM_STALE_SECONDS])
    cycle_where, cycle_args = _report_thread_cycle_where(cycle_key)
    if cycle_where:
        where.append(cycle_where)
        args.extend(cycle_args)
    with connect() as c:
        row = c.execute(
            f"SELECT COUNT(*) AS n FROM github_report_thread WHERE {' AND '.join(where)}",
            args,
        ).fetchone()
    return int(row["n"] or 0) if row else 0


def github_report_thread_cycle_keys(*, limit: int = 24) -> list[str]:
    with connect() as c:
        rows = c.execute(
            "SELECT first_cycle_key, last_cycle_key, cycle_keys FROM github_report_thread "
            "ORDER BY updated_at DESC LIMIT ?",
            (max(1, min(int(limit) * 4, 1000)),),
        ).fetchall()
    seen: list[str] = []
    for row in rows:
        for key in _report_thread_cycle_keys({k: row[k] for k in row.keys()}):
            if key not in seen:
                seen.append(key)
    current = smb_current_cycle_key()
    if current not in seen:
        seen.insert(0, current)
    return sorted(seen, reverse=True)[:max(1, min(int(limit), 100))]


def github_recheck_result_add(
    *,
    thread_id: int,
    repo: str,
    verdict: str,
    finding_id: int | None = None,
    path: str | None = None,
    verification: dict[str, Any] | None = None,
    error: str | None = None,
) -> int:
    now = time.time()
    with connect() as c:
        cur = c.execute(
            "INSERT INTO github_recheck_result("
            "thread_id, finding_id, repo, path, verdict, verification_json, error, created_at"
            ") VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (
                thread_id, finding_id, repo, path, verdict,
                json.dumps(verification or {}, ensure_ascii=False, sort_keys=True),
                error, now,
            ),
        )
        return int(cur.lastrowid)


def github_recheck_results_for_thread(thread_id: int) -> list[dict[str, Any]]:
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM github_recheck_result WHERE thread_id=? "
            "ORDER BY created_at DESC, id DESC",
            (thread_id,),
        ).fetchall()
    out: list[dict[str, Any]] = []
    for r in rows:
        d = {k: r[k] for k in r.keys()}
        try:
            d["verification"] = json.loads(d.pop("verification_json") or "{}")
        except Exception:
            d["verification"] = {}
        out.append(d)
    return out


# ============================================================
# confluence_space_target — v3.76 (전사 space rolling 스윕, bounded, oldest-first)
# github_repo_target 의 near-exact 미러. claim SQL/ORDER BY 동일 재사용.
# ============================================================

_CONFLUENCE_SPACE_STATUSES = {"pending", "in_progress", "tasked", "skipped", "error"}
CONFLUENCE_SPACE_CLAIM_STALE_SECONDS = 1800   # in_progress 가 이만큼 묵으면 재claim
CONFLUENCE_SPACE_RESCAN_SECONDS = 86400       # 본 지 이만큼 지나야 재스캔(cooldown)


def confluence_space_cycle_ensure_current(cycle_key: str | None = None) -> dict[str, Any]:
    """Reset Confluence space scan progress when the weekly board cycle changes."""
    return _target_cycle_ensure_current("confluence_space_target", cycle_key=cycle_key)


def confluence_space_target_upsert(
    space_key: str, *, space_name: str | None = None, space_type: str | None = None,
) -> int:
    """space 1 row 보장(bounded). 기존 space 는 메타만 갱신(last_scanned_at/status 보존)."""
    space_key = (space_key or "").strip()
    if not space_key:
        raise ValueError("space_key empty")
    now = time.time()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        r = c.execute(
            "SELECT id, cycle_key FROM confluence_space_target WHERE space_key=?", (space_key,),
        ).fetchone()
        if r is not None:
            if r["cycle_key"] == cycle_key:
                c.execute(
                    "UPDATE confluence_space_target SET space_name=?, space_type=?, last_seen=? "
                    "WHERE id=?",
                    (space_name, space_type, now, r["id"]),
                )
            else:
                c.execute(
                    "UPDATE confluence_space_target SET space_name=?, space_type=?, last_seen=?, "
                    "cycle_key=?, cycle_scanned_at=NULL, cycle_finding_count=0, "
                    "status='pending', claimed_by=NULL, claimed_at=NULL, "
                    "retry_after=NULL WHERE id=?",
                    (space_name, space_type, now, cycle_key, r["id"]),
                )
            return int(r["id"])
        cur = c.execute(
            "INSERT INTO confluence_space_target"
            "(space_key, space_name, space_type, status, finding_count, "
            " first_seen, last_seen, cycle_key, cycle_finding_count) "
            "VALUES (?, ?, ?, 'pending', 0, ?, ?, ?, 0)",
            (space_key, space_name, space_type, now, now, cycle_key),
        )
        return int(cur.lastrowid)


def confluence_space_target_claim_next(
    *,
    session_id: int,
    limit: int = 1,
    stale_seconds: float | None = None,
    cooldown_seconds: float | None = None,
) -> list[dict[str, Any]]:
    """oldest-first(한 번도 안 본 것 먼저 → 본 지 오래된 순) rolling claim. 최대 `limit`개.

    github_repo_target_claim_next 와 동일 SQL seam (pick_where/ORDER BY)."""
    confluence_space_cycle_ensure_current()
    stale = CONFLUENCE_SPACE_CLAIM_STALE_SECONDS if stale_seconds is None else stale_seconds
    cooldown = CONFLUENCE_SPACE_RESCAN_SECONDS if cooldown_seconds is None else cooldown_seconds
    n = max(1, int(limit))
    now = time.time()
    cycle_key = smb_current_cycle_key()
    claim_cutoff = now - stale
    fresh_cutoff = now - cooldown
    pick_where = (
        "cycle_key=? "
        "AND (status != 'in_progress' OR (claimed_at IS NOT NULL AND claimed_at < ?)) "
        "AND (cycle_scanned_at IS NULL OR last_scanned_at IS NULL OR last_scanned_at < ?) "
        "AND (retry_after IS NULL OR retry_after <= ?)"
    )
    inner_lock = "FOR UPDATE SKIP LOCKED"  # v3.76: 단일 postgres
    sql = (
        "UPDATE confluence_space_target SET status='in_progress', claimed_by=?, claimed_at=? "
        "WHERE id IN ("
        "SELECT id FROM confluence_space_target "
        f"WHERE {pick_where} "
        "ORDER BY (cycle_scanned_at IS NULL) DESC, "
        "(last_scanned_at IS NULL) DESC, last_scanned_at ASC, id ASC "
        f"LIMIT {n} {inner_lock}"
        ") RETURNING *"
    )
    args = [session_id, now, cycle_key, claim_cutoff, fresh_cutoff, now]
    with connect() as c:
        rows = c.execute(sql, args).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]


def confluence_space_reclaim_stale_claims(
    *, stale_seconds: float = CONFLUENCE_SPACE_CLAIM_STALE_SECONDS,
) -> int:
    """v3.80 Slice0b — confluence_space_target 진행 불능 claim 해제 (github 미러)."""
    return _reclaim_stale_claims("confluence_space_target", stale_seconds=stale_seconds)


def confluence_space_target_set_status(target_id: int, status: str, **fields: Any) -> None:
    """status 전이. 비-in_progress 완료 시 현재 cycle_scanned_at도 같이 찍는다."""
    if status not in _CONFLUENCE_SPACE_STATUSES:
        raise ValueError(f"invalid confluence_space_target status: {status!r}")
    _validate_column_names(fields.keys())
    sets = ["status=?"]
    args: list[Any] = [status]
    now = time.time()
    if "cycle_key" not in fields:
        sets.append("cycle_key=?")
        args.append(smb_current_cycle_key())
    if status != "in_progress":
        if "retry_after" not in fields:
            sets.append("retry_after=?")
            args.append(None)
        if "last_scanned_at" not in fields:
            sets.append("last_scanned_at=?")
            args.append(now)
        if "cycle_scanned_at" not in fields:
            sets.append("cycle_scanned_at=?")
            args.append(now)
        if "cycle_finding_count" not in fields:
            sets.append("cycle_finding_count=?")
            args.append(int(fields.get("finding_count") or 0))
        if "claimed_by" not in fields:
            sets.append("claimed_by=?")
            args.append(None)
        if "claimed_at" not in fields:
            sets.append("claimed_at=?")
            args.append(None)
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(target_id)
    with connect() as c:
        c.execute(
            f"UPDATE confluence_space_target SET {', '.join(sets)} WHERE id=?", args,
        )


def confluence_space_target_get(target_id: int) -> dict[str, Any] | None:
    with connect() as c:
        r = c.execute(
            "SELECT * FROM confluence_space_target WHERE id=?", (target_id,),
        ).fetchone()
        return {k: r[k] for k in r.keys()} if r is not None else None


def confluence_space_targets_summary() -> dict[str, int]:
    confluence_space_cycle_ensure_current()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        rows = c.execute(
            "SELECT status, COUNT(*) AS n FROM confluence_space_target "
            "WHERE cycle_key=? GROUP BY status",
            (cycle_key,),
        ).fetchall()
        never = c.execute(
            "SELECT COUNT(*) AS n FROM confluence_space_target "
            "WHERE cycle_key=? AND cycle_scanned_at IS NULL",
            (cycle_key,),
        ).fetchone()
        scanned = c.execute(
            "SELECT COUNT(*) AS n FROM confluence_space_target "
            "WHERE cycle_key=? AND cycle_scanned_at IS NOT NULL",
            (cycle_key,),
        ).fetchone()
    out = {s: 0 for s in _CONFLUENCE_SPACE_STATUSES}
    out["total"] = 0
    for r in rows:
        out[r["status"]] = int(r["n"])
        out["total"] += int(r["n"])
    out["never_scanned"] = int(never["n"])
    out["scanned"] = int(scanned["n"])
    out["cycle_key"] = cycle_key
    return out


# ============================================================
# confluence_search_target — Confluence 키워드 브라우저-검색 큐 (space_target 미러)
# ============================================================
# REST CQL 이 정책상 영구차단(429)이라, 허용목록 키워드로 dosearchsite 브라우저 검색을 rolling 스윕한다.
# claim/cooldown/cycle 메커니즘은 confluence_space_target 과 동일 seam(keyword 가 space_key 역할).

_CONFLUENCE_SEARCH_STATUSES = {"pending", "in_progress", "tasked", "skipped", "error"}
CONFLUENCE_SEARCH_CLAIM_STALE_SECONDS = 1800   # in_progress 가 이만큼 묵으면 재claim
CONFLUENCE_SEARCH_RESCAN_SECONDS = 86400       # 본 지 이만큼 지나야 재검색(cooldown)


def confluence_search_cycle_ensure_current(cycle_key: str | None = None) -> dict[str, Any]:
    """주간 보드 사이클이 바뀌면 키워드 검색 진행상태 리셋."""
    return _target_cycle_ensure_current("confluence_search_target", cycle_key=cycle_key)


def confluence_search_target_upsert(
    keyword: str, *, scope_space_keys: list[str] | None = None, config_version: str | None = None,
) -> int:
    """키워드 1 row 보장(허용목록 sync 용). 기존 키워드는 scope/config만 갱신(진행상태 보존)."""
    keyword = (keyword or "").strip()
    if not keyword:
        raise ValueError("keyword empty")
    scope_json = json.dumps(sorted(scope_space_keys)) if scope_space_keys else None
    now = time.time()
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        r = c.execute(
            "SELECT id, cycle_key FROM confluence_search_target WHERE keyword=?", (keyword,),
        ).fetchone()
        if r is not None:
            if r["cycle_key"] == cycle_key:
                c.execute(
                    "UPDATE confluence_search_target SET scope_json=?, config_version=?, last_seen=? "
                    "WHERE id=?",
                    (scope_json, config_version, now, r["id"]),
                )
            else:
                c.execute(
                    "UPDATE confluence_search_target SET scope_json=?, config_version=?, last_seen=?, "
                    "cycle_key=?, cycle_scanned_at=NULL, cycle_finding_count=0, "
                    "status='pending', claimed_by=NULL, claimed_at=NULL, retry_after=NULL WHERE id=?",
                    (scope_json, config_version, now, cycle_key, r["id"]),
                )
            return int(r["id"])
        cur = c.execute(
            "INSERT INTO confluence_search_target"
            "(keyword, scope_json, status, finding_count, first_seen, last_seen, "
            " cycle_key, cycle_finding_count, config_version) "
            "VALUES (?, ?, 'pending', 0, ?, ?, ?, 0, ?)",
            (keyword, scope_json, now, now, cycle_key, config_version),
        )
        return int(cur.lastrowid)


def confluence_search_target_claim_next(
    *,
    session_id: int,
    limit: int = 1,
    stale_seconds: float | None = None,
    cooldown_seconds: float | None = None,
) -> list[dict[str, Any]]:
    """oldest-first rolling claim(최대 limit개). confluence_space_target_claim_next 와 동일 seam."""
    confluence_search_cycle_ensure_current()
    stale = CONFLUENCE_SEARCH_CLAIM_STALE_SECONDS if stale_seconds is None else stale_seconds
    cooldown = CONFLUENCE_SEARCH_RESCAN_SECONDS if cooldown_seconds is None else cooldown_seconds
