# ============================================================
# confluence_report_thread — Confluence E2E space report/recheck state
# ============================================================

_CONFLUENCE_REPORT_THREAD_STATUSES = {
    "draft", "reported", "report_ready", "awaiting_owner",
    "recheck_requested", "rechecking", "remediated", "still_open",
    "partially_remediated", "exception_review", "owner_update_needed",
    "owner_reassignment_review", "reassigned", "escalated", "closed", "error",
}
_CONFLUENCE_REPORT_OPEN_STATUSES = (
    "draft", "reported", "report_ready", "awaiting_owner",
    "recheck_requested", "rechecking", "still_open", "partially_remediated",
    "exception_review", "owner_update_needed", "owner_reassignment_review",
    "reassigned", "escalated", "error",
)
CONFLUENCE_REPORT_THREAD_CLAIM_STALE_SECONDS = 1800
_CONFLUENCE_SEV_RANK = _sev.RANK


def normalize_confluence_subject_tag(space_key: str) -> str:
    """Space-scoped report correlation key for Confluence E2E reporting."""
    return f"[Confluence 보안취약점 조치요청]({str(space_key or '').strip()})"


def confluence_report_thread_upsert(
    *,
    finding_id: int,
    space_key: str,
    severity: str | None = None,
    recipient: str | None = None,
    owner_recipient: str | None = None,
    status: str = "reported",
    subject_tag: str | None = None,
    cycle_key: str | None = None,
) -> tuple[str, int]:
    """Group Confluence findings into one open report thread per space."""
    space_key = str(space_key or "").strip() or "unknown"
    if status not in _CONFLUENCE_REPORT_THREAD_STATUSES:
        raise ValueError(f"invalid confluence_report_thread status: {status!r}")
    now = time.time()
    cur_cycle = cycle_key or smb_current_cycle_key()
    sev = (severity or "").strip().lower() or None
    tag = subject_tag or normalize_confluence_subject_tag(space_key)
    owner = _service_owner_recipient_hint(recipient, owner_recipient)
    open_in = ",".join("?" for _ in _CONFLUENCE_REPORT_OPEN_STATUSES)
    with connect() as c:
        row = c.execute(
            f"SELECT * FROM confluence_report_thread WHERE space_key=? "
            f"AND status IN ({open_in}) AND last_cycle_key=? "
            "ORDER BY updated_at DESC LIMIT 1",
            (space_key, *_CONFLUENCE_REPORT_OPEN_STATUSES, cur_cycle),
        ).fetchone()
        if row is None:
            previous_cycles = _report_thread_previous_cycles(
                c,
                table="confluence_report_thread",
                scope_column="space_key",
                scope_value=space_key,
                finding_id=finding_id,
                current_cycle=cur_cycle,
            )
            cycles = [*previous_cycles, cur_cycle] if previous_cycles else [cur_cycle]
            cur = c.execute(
                "INSERT INTO confluence_report_thread("
                "space_key, finding_id, finding_ids, subject_tag, severity, status, "
                "recipient, owner_recipient, first_reported_at, first_cycle_key, "
                "last_cycle_key, cycle_keys, created_at, updated_at"
                ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id",
                (
                    space_key, finding_id, json.dumps([finding_id]), tag, sev, status,
                    recipient, owner, now, cur_cycle, cur_cycle, json.dumps(cycles), now, now,
                ),
            )
            inserted = cur.fetchone()
            return ("recurred" if previous_cycles else "new"), int(inserted["id"])

        tid = int(row["id"])
        try:
            fids = [int(x) for x in json.loads(row["finding_ids"] or "[]")]
        except Exception:
            fids = []
        cycles = _report_thread_cycle_list_from_row(row)
        if cur_cycle not in cycles:
            cycles.append(cur_cycle)
        cycles_json = json.dumps(cycles)
        # ⚠️ 수신처를 **언제 합치고 언제 교체하나.**
        #
        #  · finding 이 **여럿**인 스레드: 이 finding 의 담당자는 전체가 아니라 **기여분**이다.
        #    그대로 덮어쓰면 담당자가 다른 둘이 매 패스마다 서로 덮어쓰며 싸운다
        #    (실측 2026-08-28: confluence attempt_count 가 60초마다 +2, 541 까지).
        #    그리고 조용한 손실도 난다 — TPYE 스레드는 마지막에 쓴 finding 의 담당자만
        #    남아서 `hottie.yang` 이 수신처에서 빠져 있었다. → **합집합.**
        #  · finding 이 **하나**인 스레드: 그 담당자가 곧 스레드의 담당자다. 조회가
        #    정정되거나 담당자가 바뀌면 옛 사람에게 계속 보내면 안 된다. → **교체.**
        #
        # ★ 네 갈래 UPDATE 가 **모두** 이 값을 쓴다 — 한 곳이라도 원본을 쓰면 거기서
        #   다시 덮어써서 순환이 그대로 산다(실제로 두 곳만 고쳤을 때 재현됐다).
        _aggregating = len(fids) > 1 or int(finding_id) not in fids
        if _aggregating:
            merged_recipient, recipient_grew = _merge_service_recipients(
                row["recipient"], recipient)
            merged_owner, owner_grew = _merge_service_recipients(
                row["owner_recipient"], owner)
        else:
            merged_recipient, merged_owner = recipient, owner
            recipient_grew = recipient is not None and str(recipient) != str(
                row["recipient"] or "")
            owner_grew = owner is not None and str(owner) != str(
                row["owner_recipient"] or "")
        if int(finding_id) in fids:
            best = _merge_confluence_sev(row["severity"], sev)
            report_ready_changed = row["status"] == "report_ready" and (
                best != row["severity"] or recipient_grew or owner_grew
            )
            if report_ready_changed:
                c.execute(
                    "UPDATE confluence_report_thread SET severity=?, "
                    "status='reported', claimed_by=NULL, claimed_at=NULL, retry_after=NULL, "
                    "attempt_count=attempt_count+1, report_json='{}', report_html=NULL, "
                    "notified_at=NULL, "
                    "recipient=COALESCE(?, recipient), owner_recipient=COALESCE(?, owner_recipient), "
                    "first_cycle_key=COALESCE(first_cycle_key, ?), last_cycle_key=?, "
                    "cycle_keys=?, updated_at=? WHERE id=?",
                    (best, merged_recipient, merged_owner, cur_cycle, cur_cycle,
                     cycles_json, now, tid),
                )
                return "recurred", tid
            c.execute(
                "UPDATE confluence_report_thread SET severity=?, "
                "recipient=COALESCE(?, recipient), owner_recipient=COALESCE(?, owner_recipient), "
                "first_cycle_key=COALESCE(first_cycle_key, ?), last_cycle_key=?, "
                "cycle_keys=?, updated_at=? WHERE id=?",
                (best, merged_recipient, merged_owner, cur_cycle, cur_cycle,
                 cycles_json, now, tid),
            )
            return "dup", tid

        fids.append(int(finding_id))
        best = _merge_confluence_sev(row["severity"], sev)
        already_notified = row["status"] in (
            "report_ready", "awaiting_owner", "recheck_requested",
            "rechecking", "still_open", "partially_remediated",
            "exception_review", "owner_update_needed", "owner_reassignment_review",
            "reassigned", "escalated", "error",
        )
        if already_notified:
            c.execute(
                "UPDATE confluence_report_thread SET finding_ids=?, severity=?, "
                "status='reported', claimed_by=NULL, claimed_at=NULL, retry_after=NULL, "
                "attempt_count=attempt_count+1, report_json='{}', report_html=NULL, "
                "notified_at=NULL, "
                "recipient=COALESCE(?, recipient), owner_recipient=COALESCE(?, owner_recipient), "
                "first_cycle_key=COALESCE(first_cycle_key, ?), last_cycle_key=?, "
                "cycle_keys=?, updated_at=? WHERE id=?",
                (json.dumps(fids), best, merged_recipient, merged_owner,
                 cur_cycle, cur_cycle, cycles_json, now, tid),
            )
            return "recurred", tid
        c.execute(
            "UPDATE confluence_report_thread SET finding_ids=?, severity=?, "
            "subject_tag=?, recipient=COALESCE(?, recipient), "
            "owner_recipient=COALESCE(?, owner_recipient), "
            "first_cycle_key=COALESCE(first_cycle_key, ?), "
            "last_cycle_key=?, cycle_keys=?, updated_at=? WHERE id=?",
            (json.dumps(fids), best, tag, merged_recipient, merged_owner,
             cur_cycle, cur_cycle, cycles_json, now, tid),
        )
        return "merged", tid


def _merge_confluence_sev(a: str | None, b: str | None) -> str | None:
    if a is None:
        return b
    if b is None:
        return a
    return _sev.merge(a, b)


def confluence_report_thread_get(thread_id: int) -> dict[str, Any] | None:
    with connect() as c:
        r = c.execute(
            "SELECT * FROM confluence_report_thread WHERE id=?", (thread_id,),
        ).fetchone()
    return {k: r[k] for k in r.keys()} if r else None


def confluence_report_thread_finding_ids(thread_id: int) -> list[int]:
    t = confluence_report_thread_get(thread_id)
    if not t:
        return []
    try:
        return [int(x) for x in json.loads(t.get("finding_ids") or "[]")]
    except Exception:
        return []


def confluence_report_thread_set_status(thread_id: int, status: str, **fields: Any) -> None:
    if status not in _CONFLUENCE_REPORT_THREAD_STATUSES:
        raise ValueError(f"invalid confluence_report_thread status: {status!r}")
    _validate_column_names(fields.keys())
    sets = ["status=?", "updated_at=?"]
    args: list[Any] = [status, time.time()]
    if "retry_after" not in fields:
        sets.append("retry_after=?")
        args.append(None)
    if status != "rechecking":
        if "claimed_by" not in fields:
            sets.append("claimed_by=?")
            args.append(None)
        if "claimed_at" not in fields:
            sets.append("claimed_at=?")
            args.append(None)
    for k, v in fields.items():
        sets.append(f"{k}=?")
        args.append(v)
    args.append(thread_id)
    with connect() as c:
        c.execute(
            f"UPDATE confluence_report_thread SET {', '.join(sets)} WHERE id=?", args,
        )
    if status in _THREAD_CLOSING_STATUSES:
        _close_findings_for_thread(thread_id, "confluence_report_thread")


def confluence_report_thread_schedule_recheck_retry(
    thread_id: int,
    *,
    reason: str,
    retry_seconds: float | None = None,
) -> float:
    reason_text = str(reason or "confluence recheck retry scheduled")[:1000]
    retry_after = time.time() + (
        retry_seconds if retry_seconds is not None else service_recheck_retry_seconds()
    )
    confluence_report_thread_set_status(
        thread_id,
        "recheck_requested",
        retry_after=retry_after,
        last_reason=reason_text,
    )
    confluence_report_thread_bump_attempt(thread_id, reason=reason_text)
    return retry_after


def confluence_report_thread_claim_next(
    *,
    session_id: int,
    status: str,
    stale_seconds: float = CONFLUENCE_REPORT_THREAD_CLAIM_STALE_SECONDS,
) -> dict[str, Any] | None:
    if status not in _CONFLUENCE_REPORT_THREAD_STATUSES:
        raise ValueError(f"invalid confluence_report_thread status: {status!r}")
    now = time.time()
    cutoff = now - stale_seconds
    cycle_filter = ""
    owner_filter = ""
    args: list[Any] = [session_id, now, status, now, cutoff]
    if status in {"reported", "recheck_requested"}:
        cycle_filter = "AND last_cycle_key=? "
        args.append(smb_current_cycle_key())
    if status == "reported":
        owner_filter = "AND TRIM(COALESCE(owner_recipient, ''))<>'' "
    with connect() as c:
        r = c.execute(
            "UPDATE confluence_report_thread SET claimed_by=?, claimed_at=? WHERE id = ("
            "SELECT id FROM confluence_report_thread WHERE status=? "
            "AND (retry_after IS NULL OR retry_after <= ?) "
            "AND (claimed_at IS NULL OR claimed_at < ?) "
            f"{cycle_filter}"
            f"{owner_filter}"
            # ★ **높음 이상을 먼저 집는다**(사용자 결정 2026-08-31 · 4도메인 통일).
        #   예전엔 순수 FIFO 라 심각·높음이 낮음 뒤에 줄 섰다(smb 실측: 심각 3·높음 5가
        #   낮음 21건 뒤). 같은 등급 안에서는 오래된 것부터 — 굶는 스레드가 없게.
        #   ⚠️ NULL 함정: `severity IN (...)` 은 NULL 이면 NULL 이고 postgres 의 DESC 는
        #      NULL 을 **먼저** 놓는다. COALESCE 로 막는다(리드 정렬에서 실제로 당했다).
        "ORDER BY (COALESCE(severity,'') IN ('critical','high')) DESC, "
        "  CASE severity WHEN 'critical' THEN 0 WHEN 'high' THEN 1 "
        "                WHEN 'medium' THEN 2 ELSE 3 END ASC, "
        "  updated_at ASC, id ASC LIMIT 1 FOR UPDATE SKIP LOCKED"
            ") RETURNING *",
            args,
        ).fetchone()
    return {k: r[k] for k in r.keys()} if r else None


def confluence_report_thread_reclaim_stale(
    *,
    stale_seconds: float = CONFLUENCE_REPORT_THREAD_CLAIM_STALE_SECONDS,
) -> int:
    cutoff = time.time() - stale_seconds
    with connect() as c:
        r = c.execute(
            "UPDATE confluence_report_thread SET claimed_by=NULL, claimed_at=NULL "
            "WHERE claimed_at IS NOT NULL AND claimed_at < ?",
            (cutoff,),
        )
        return r.rowcount


def confluence_report_thread_bump_attempt(thread_id: int, *, reason: str | None = None) -> int:
    with connect() as c:
        cur = c.execute(
            "UPDATE confluence_report_thread SET attempt_count=attempt_count+1, "
            "last_reason=?, updated_at=? WHERE id=? RETURNING attempt_count",
            (reason, time.time(), thread_id),
        )
        row = cur.fetchone()
    return int(row["attempt_count"]) if row else 0


def confluence_report_threads_overview(
    *,
    status: str | None = None,
    space_key: str | None = None,
    limit: int = 100,
    cycle_key: str | None = None,
) -> list[dict[str, Any]]:
    where: list[str] = []
    args: list[Any] = []
    if status is not None:
        where.append("status=?")
        args.append(status)
    if space_key is not None:
        where.append("space_key=?")
        args.append(space_key)
    cycle_where, cycle_args = _report_thread_cycle_where(cycle_key)
    if cycle_where:
        where.append(cycle_where)
        args.extend(cycle_args)
    where_sql = "WHERE " + " AND ".join(where) if where else ""
    args.append(max(1, min(int(limit), 1000)))
    with connect() as c:
        rows = c.execute(
            f"SELECT * FROM confluence_report_thread {where_sql} "
            "ORDER BY updated_at DESC LIMIT ?",
            args,
        ).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]


def confluence_report_thread_status_counts(*, cycle_key: str | None = None) -> dict[str, int]:
    where, args = _report_thread_cycle_where(cycle_key)
    where_sql = f"WHERE {where}" if where else ""
    with connect() as c:
        rows = c.execute(
            f"SELECT status, COUNT(*) AS n FROM confluence_report_thread {where_sql} "
            "GROUP BY status",
            args,
        ).fetchall()
    out = {s: 0 for s in _CONFLUENCE_REPORT_THREAD_STATUSES}
    for r in rows:
        out[str(r["status"])] = int(r["n"])
    return out


def confluence_report_thread_queue_count(status: str, *, cycle_key: str | None = None) -> int:
    where = ["status=?"]
    args: list[Any] = [status]
    now = time.time()
    if status == "reported":
        where.append("TRIM(COALESCE(owner_recipient, ''))<>''")
    if status in {"reported", "recheck_requested"}:
        where.append("(retry_after IS NULL OR retry_after <= ?)")
        where.append("(claimed_at IS NULL OR claimed_at < ?)")
        args.extend([now, now - CONFLUENCE_REPORT_THREAD_CLAIM_STALE_SECONDS])
    cycle_where, cycle_args = _report_thread_cycle_where(cycle_key)
    if cycle_where:
        where.append(cycle_where)
        args.extend(cycle_args)
    with connect() as c:
        row = c.execute(
            f"SELECT COUNT(*) AS n FROM confluence_report_thread WHERE {' AND '.join(where)}",
            args,
        ).fetchone()
    return int(row["n"] or 0) if row else 0


def confluence_report_thread_cycle_keys(*, limit: int = 24) -> list[str]:
    with connect() as c:
        rows = c.execute(
            "SELECT first_cycle_key, last_cycle_key, cycle_keys FROM confluence_report_thread "
            "ORDER BY updated_at DESC LIMIT ?",
            (max(1, min(int(limit) * 4, 1000)),),
        ).fetchall()
    seen: list[str] = []
    for row in rows:
        for key in _report_thread_cycle_keys({k: row[k] for k in row.keys()}):
            if key not in seen:
                seen.append(key)
    current = smb_current_cycle_key()
    if current not in seen:
        seen.insert(0, current)
    return sorted(seen, reverse=True)[:max(1, min(int(limit), 100))]


def confluence_recheck_result_add(
    *,
    thread_id: int,
    space_key: str,
    verdict: str,
    finding_id: int | None = None,
    asset: str | None = None,
    verification: dict[str, Any] | None = None,
    error: str | None = None,
) -> int:
    now = time.time()
    with connect() as c:
        cur = c.execute(
            "INSERT INTO confluence_recheck_result("
            "thread_id, finding_id, space_key, asset, verdict, verification_json, error, created_at"
            ") VALUES (?, ?, ?, ?, ?, ?, ?, ?) RETURNING id",
            (
                thread_id, finding_id, str(space_key or "unknown"), asset, verdict,
                json.dumps(verification or {}, ensure_ascii=False, sort_keys=True),
                error, now,
            ),
        )
        inserted = cur.fetchone()
        return int(inserted["id"])


def confluence_recheck_results_for_thread(thread_id: int) -> list[dict[str, Any]]:
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM confluence_recheck_result WHERE thread_id=? "
            "ORDER BY created_at DESC, id DESC",
            (thread_id,),
        ).fetchall()
    out: list[dict[str, Any]] = []
    for r in rows:
        d = {k: r[k] for k in r.keys()}
        try:
            d["verification"] = json.loads(d.pop("verification_json") or "{}")
        except Exception:
            d["verification"] = {}
        out.append(d)
    return out


_SERVICE_REPLY_DOMAINS = {"github", "confluence"}
_SERVICE_REPORT_INBOUND_MATCH_STATUSES = (
    "awaiting_owner", "recheck_requested", "still_open", "partially_remediated",
    "exception_review", "owner_update_needed", "owner_reassignment_review",
    "reassigned", "escalated",
)
_SERVICE_REPLY_DECISION_STATUS = {
    "remediation_claim": "recheck_requested",
    "business_exception_claim": "exception_review",
    "not_owner": "owner_update_needed",
    "owner_changed": "owner_reassignment_review",
    "how_to_question": "awaiting_owner",
    "still_needed": "awaiting_owner",
    "unclear": "awaiting_owner",
}


def _float_or_none(value: Any) -> float | None:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


#: 도메인 → 스레드 테이블. 규칙은 하나, 어휘는 도메인 것.
#: ⚠️ dev_web 이 여기 없어서 `_service_report_table` 이 **ValueError 를 던졌다** —
#:    dev_web 담당자가 답장하면 POP3 수집기가 그 자리에서 죽는다(2026-08-31 실측).
_SERVICE_REPORT_TABLES: dict[str, str] = {
    "github": "github_report_thread",
    "confluence": "confluence_report_thread",
    "dev_web": "dev_web_report_thread",
}


def _service_report_table(domain: str) -> str:
    table = _SERVICE_REPORT_TABLES.get(str(domain or "").strip().lower())
    if table is None:
        raise ValueError(f"invalid service reply domain: {domain!r}")
    return table


#: 도메인 → 스레드 테이블. 티켓 번호 저장·조회가 공통으로 쓴다.
_THREAD_TABLES: dict[str, str] = {
    "smb": "mail_thread",
    "github": "github_report_thread",
    "confluence": "confluence_report_thread",
    "dev_web": "dev_web_report_thread",
}


def thread_ensure_ticket_no(domain: str, thread_id: int) -> str | None:
    """이 스레드의 티켓 번호를 **저장하고** 돌려준다. 이미 있으면 그대로 둔다.

    ★ 번호는 사람에게 이미 나간 값이다(메일 제목). 한 번 정해지면 **절대 바꾸지 않는다** —
      접두 규칙이 바뀌어도 저장된 값이 이긴다. 그래서 재계산이 아니라 `IS NULL` 일 때만 쓴다.

    ⚠️ 이 함수가 번호의 **유일한 생산자**다. 콘솔(게이트웨이)은 이 열을 읽기만 한다.
    """
    table = _THREAD_TABLES.get(str(domain or ""))
    if table is None:
        return None
    from _shared.ticket_id import ticket_no as _make

    try:
        value = _make(str(domain), int(thread_id))
    except (TypeError, ValueError):
        return None
    with connect() as c:
        row = c.execute(
            f"UPDATE {table} SET ticket_no=? WHERE id=? AND ticket_no IS NULL "
            "RETURNING ticket_no", (value, int(thread_id)),
        ).fetchone()
        if row is not None:
            return row["ticket_no"]
        cur = c.execute(
            f"SELECT ticket_no FROM {table} WHERE id=?", (int(thread_id),),
        ).fetchone()
    return cur["ticket_no"] if cur is not None else None


def stamp_subject_for_thread(subject: str, domain: str, thread_id: int) -> str:
    """발송 제목에 티켓 번호를 찍는다 — **저장된 값**으로.

    ⚠️ 발송 경로는 전부 이걸 쓴다. `_shared.ticket_id.stamp_subject`(공식 계산)를 직접
       쓰면 저장값과 갈릴 수 있다. 번호는 사람에게 이미 나간 값이다.
    """
    from _shared.ticket_id import stamp_subject_with

    return stamp_subject_with(subject, thread_ensure_ticket_no(domain, thread_id))


def thread_backfill_ticket_no(domain: str) -> int:
    """이 도메인의 빈 `ticket_no` 를 채운다. 이미 값이 있는 행은 건드리지 않는다."""
    table = _THREAD_TABLES.get(str(domain or ""))
    if table is None:
        return 0
    from _shared.ticket_id import TICKET_PREFIX

    prefix = TICKET_PREFIX.get(str(domain))
    if not prefix:
        return 0
    with connect() as c:
        r = c.execute(
            f"UPDATE {table} SET ticket_no = ? || LPAD(id::text, 5, '0') "
            "WHERE ticket_no IS NULL", (prefix,),
        )
        return int(getattr(r, "rowcount", 0) or 0)


def service_report_inbound_match_statuses(domain: str) -> tuple[str, ...]:
    """이 도메인에서 답장을 받을 수 있는 상태들. 정본은 여기 하나.

    ★ 2026-08-31 — dev_web 은 `_SERVICE_REPORT_INBOUND_MATCH_STATUSES`(github·confluence
      어휘)로 조회되고 있었다. 그 집합의 `awaiting_owner`·`recheck_requested`·`still_open`
      **셋은 dev_web 상태 어휘에 존재하지도 않는다.** dev_web 어휘는 smb 와 같고
      (차이는 `report_ready` 하나뿐) 답장 대기 상태는 `awaiting_reply` 다.
      즉 dev_web 은 답장을 받을 수 있는 상태를 **하나도 후보로 두지 않았다.**

    ⚠️ 상수를 **복사하지 않는다** — 지연 참조다. smb 집합이 바뀌면 dev_web 도 따라간다.
       (`_MAIL_THREAD_INBOUND_MATCH_STATUSES` 는 이 파일 뒤쪽에서 정의된다.)
    """
    d = str(domain or "").strip().lower()
    if d == "dev_web":
        return tuple(_MAIL_THREAD_INBOUND_MATCH_STATUSES)
    if d in ("github", "confluence"):
        return tuple(_SERVICE_REPORT_INBOUND_MATCH_STATUSES)
    raise ValueError(f"invalid service reply domain: {domain!r}")


def service_report_thread_find_inbound_match_at(
    domain: str,
    subject_tag: str,
    *,
    received_at: float | None,
) -> dict[str, Any] | None:
    """Find an active GitHub/Confluence report thread for a POP3 reply.

    Service report threads use the latest sent outbound as their reply boundary:
    the first report notification (`notified_at`) or a later service reply mail.
    If a reply predates the newest outbound for that subject, do not fall back
    to older cycles.
    """
    table = _service_report_table(domain)
    statuses = service_report_inbound_match_statuses(domain)
    placeholders = ",".join("?" for _ in statuses)
    with connect() as c:
        rows = c.execute(
            f"SELECT t.*, "
            "  (SELECT MAX(srm.received_at) FROM service_reply_message srm "
            "   WHERE srm.domain=? AND srm.thread_id=t.id "
            "   AND srm.direction='out' AND srm.agent_verdict='sent') "
            f"  AS latest_reply_outbound_at FROM {table} t WHERE subject_tag=? "
            f"AND status IN ({placeholders}) "
            "ORDER BY updated_at DESC, id DESC",
            (domain, subject_tag, *statuses),
        ).fetchall()
    if not rows:
        return None
    candidates: list[dict[str, Any]] = []
    for row in rows:
        candidate = {k: row[k] for k in row.keys()}
        outbound_times = [
            ts for ts in (
                _float_or_none(candidate.get("notified_at")),
                _float_or_none(candidate.get("latest_reply_outbound_at")),
            )
            if ts is not None
        ]
        candidate["_latest_outbound_at"] = max(outbound_times) if outbound_times else None
        candidates.append(candidate)
    candidates.sort(
        key=lambda item: (
            item["_latest_outbound_at"] is None,
            -float(item["_latest_outbound_at"] or 0.0),
            -float(item.get("updated_at") or 0.0),
            -int(item.get("id") or 0),
        )
    )
    row = candidates[0]
    latest_out = row.pop("_latest_outbound_at", None)
    row.pop("latest_reply_outbound_at", None)
    if latest_out is None:
        # ★ 2026-08-31 — 여기서 `return None` 을 했다. 그래서 github·confluence·dev_web 은
        #   답장이 와도 **구조적으로 100% 미아**였다. 경계의 출처가 둘뿐인데 실측하면
        #   둘 다 비어 있다:
        #       notified_at                     github 552/0 · confluence 44/0
        #                                       dev_web 은 **열 자체가 없다**
        #       service_reply_message out/sent  테이블 전체 0행
        #
        #   경계를 요구한 의도는 "우리가 보낸 적 없는 스레드에 답장이 붙는 것" 방지였는데,
        #   실제로 막은 건 **발송 기록이 유실된 경우**였다. 답장이 왔다는 것 자체가 우리가
        #   보냈다는 증거다 — 우리 제목 태그를 달고 오기 때문이다.
        #
        #   smb(`mail_thread_find_inbound_match_at`)는 경계가 없어도 매칭한다. 그래서
        #   smb 만 동작했다. 사용자 지시(2026-08-31 "이것도 마찬가지로 통일된걸로")에 따라
        #   smb 규칙으로 통일한다. 규칙 정본은 `_shared/reply_match` 머리말.
        return row
    if received_at is not None:
        try:
            if float(received_at) <= float(latest_out):
                return None
        except (TypeError, ValueError):
            pass
    return row


def service_report_thread_mark_reply_received(
    domain: str,
    thread_id: int,
    *,
    reason: str = "inbound reply received; recheck requested",
) -> None:
    domain = str(domain or "").strip().lower()
    if domain == "github":
        github_report_thread_set_status(thread_id, "recheck_requested", last_reason=reason)
        return
    if domain == "confluence":
        confluence_report_thread_set_status(thread_id, "recheck_requested", last_reason=reason)
        return
    raise ValueError(f"invalid service reply domain: {domain!r}")


def service_report_thread_mark_reply_decision(
    domain: str,
    thread_id: int,
    *,
    decision: str,
    reason: str,
) -> str:
    """Apply a deterministic inbound reply decision to a service report thread."""
    domain = str(domain or "").strip().lower()
    decision = str(decision or "").strip()
    status = _SERVICE_REPLY_DECISION_STATUS.get(decision)
    if not status:
        raise ValueError(f"invalid service reply decision: {decision!r}")
    if domain == "github":
        github_report_thread_set_status(thread_id, status, last_reason=reason[:1000])
        return status
    if domain == "confluence":
        confluence_report_thread_set_status(thread_id, status, last_reason=reason[:1000])
        return status
    raise ValueError(f"invalid service reply domain: {domain!r}")


def service_report_thread_claim_how_to_guidance_next(
    domain: str,
    *,
    session_id: int,
    stale_seconds: float = GITHUB_REPORT_THREAD_CLAIM_STALE_SECONDS,
) -> dict[str, Any] | None:
    """Claim one service report thread whose latest actionable reply asks how to fix.

    This mirrors SMB reply-verify behavior without making the POP3 collector send
    mail. A thread is eligible only when its latest how-to inbound has not
    already been followed by a sent how-to guidance outbound.
    """
    domain = str(domain or "").strip().lower()
    table = _service_report_table(domain)
    now = time.time()
    cutoff = now - stale_seconds
    cycle_key = smb_current_cycle_key()
    with connect() as c:
        row = c.execute(
            f"""
            WITH latest_how_to AS (
                SELECT DISTINCT ON (thread_id)
                    id AS reply_message_id,
                    thread_id,
                    received_at AS reply_received_at
                FROM service_reply_message
                WHERE domain=?
                  AND direction='in'
                  AND agent_verdict='classified_how_to_question'
                  AND thread_id IS NOT NULL
                ORDER BY thread_id, received_at DESC, id DESC
            ),
            candidate AS (
                SELECT t.id, latest_how_to.reply_message_id,
                       latest_how_to.reply_received_at
                FROM {table} t
                JOIN latest_how_to ON latest_how_to.thread_id=t.id
                WHERE t.status='awaiting_owner'
                  AND t.last_cycle_key=?
                  AND (t.retry_after IS NULL OR t.retry_after <= ?)
                  AND (t.claimed_at IS NULL OR t.claimed_at < ?)
                  AND NOT EXISTS (
                      SELECT 1 FROM service_reply_message out
                      WHERE out.domain=?
                        AND out.thread_id=t.id
                        AND out.direction='out'
                        AND out.agent_verdict='sent'
                        AND out.decision_reason='outbound_how_to_guidance'
                        AND out.received_at >= latest_how_to.reply_received_at
                  )
                ORDER BY latest_how_to.reply_received_at ASC,
                         t.updated_at ASC,
                         t.id ASC
                LIMIT 1 FOR UPDATE SKIP LOCKED
            )
            UPDATE {table} t
            SET claimed_by=?, claimed_at=?, updated_at=?
            FROM candidate
            WHERE t.id=candidate.id
            RETURNING t.*, candidate.reply_message_id,
                      candidate.reply_received_at
            """,
            (domain, cycle_key, now, cutoff, domain, session_id, now, now),
        ).fetchone()
    return {k: row[k] for k in row.keys()} if row else None


def service_reply_message_get_by_message_id(message_id: str) -> dict[str, Any] | None:
    mid = str(message_id or "").strip()
    if not mid:
        return None
    with connect() as c:
        r = c.execute(
            "SELECT * FROM service_reply_message WHERE message_id=? LIMIT 1",
            (mid,),
        ).fetchone()
    return {k: r[k] for k in r.keys()} if r is not None else None


def service_reply_message_get(message_id_pk: int) -> dict[str, Any] | None:
    with connect() as c:
        row = c.execute(
            "SELECT * FROM service_reply_message WHERE id=? LIMIT 1",
            (int(message_id_pk),),
        ).fetchone()
    return _service_reply_message_row(row) if row is not None else None


def service_reply_message_add(
    *,
    domain: str,
    direction: str,
    received_at: float | None = None,
    thread_id: int | None = None,
    message_id: str | None = None,
    in_reply_to: str | None = None,
    references_header: str | None = None,
    root_message_id: str | None = None,
    subject: str | None = None,
    subject_tag: str | None = None,
    mail_from: str | None = None,
    mail_to: str | None = None,
    mail_cc: str | None = None,
    body_excerpt: str | None = None,
    body_html: str | None = None,
    agent_verdict: str = "pending",
    decision_reason: str | None = None,
    extracted_owner: dict[str, Any] | None = None,
) -> int | None:
    domain = str(domain or "").strip().lower()
    if domain not in _SERVICE_REPLY_DOMAINS:
        raise ValueError(f"invalid service reply domain: {domain!r}")
    now = received_at if received_at is not None else time.time()
    mid = str(message_id or "").strip() or None
    with connect() as c:
        if mid is not None:
            dup = c.execute(
                "SELECT id FROM service_reply_message WHERE message_id=? LIMIT 1",
                (mid,),
            ).fetchone()
            if dup is not None:
                return None
        cur = c.execute(
            "INSERT INTO service_reply_message(domain, thread_id, direction, message_id, "
            "in_reply_to, references_header, root_message_id, subject, subject_tag, "
            "mail_from, mail_to, mail_cc, body_excerpt, body_html, agent_verdict, "
            "decision_reason, extracted_owner_json, received_at) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                domain, thread_id, direction, mid, in_reply_to, references_header,
                root_message_id, subject, subject_tag, mail_from, mail_to, mail_cc,
                body_excerpt, body_html, agent_verdict, decision_reason,
                json.dumps(extracted_owner or {}, ensure_ascii=False, sort_keys=True), now,
            ),
        )
        return int(cur.lastrowid)


def service_reply_message_set_body_html(message_id_pk: int, body_html: str) -> None:
    with connect() as c:
        c.execute(
            "UPDATE service_reply_message SET body_html=? WHERE id=?",
            (body_html, message_id_pk),
        )


def _service_reply_message_row(row: Any) -> dict[str, Any]:
    d = {k: row[k] for k in row.keys()}
    try:
        d["extracted_owner"] = json.loads(d.get("extracted_owner_json") or "{}")
    except Exception:
        d["extracted_owner"] = {}
    return d


def service_reply_message_attach_unmatched(
    domain: str,
    subject_tag: str,
    thread_id: int,
    *,
    received_after: float | None = None,
) -> list[dict[str, Any]]:
    """Attach pre-existing inbound service replies to a newly mailed report thread."""
    domain = str(domain or "").strip().lower()
    if domain not in _SERVICE_REPLY_DOMAINS:
        raise ValueError(f"invalid service reply domain: {domain!r}")
    where = [
        "domain=?",
        "direction='in'",
        "thread_id IS NULL",
        "subject_tag=?",
    ]
    args: list[Any] = [domain, subject_tag]
    if received_after is not None:
        where.append("received_at>=?")
        args.append(float(received_after))
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM service_reply_message WHERE " + " AND ".join(where)
            + " ORDER BY received_at ASC, id ASC",
            args,
        ).fetchall()
        ids = [int(r["id"]) for r in rows]
        if ids:
            placeholders = ",".join("?" for _ in ids)
            c.execute(
                f"UPDATE service_reply_message SET thread_id=? WHERE id IN ({placeholders})",
                (thread_id, *ids),
            )
    out = []
    for row in rows:
        d = _service_reply_message_row(row)
        d["thread_id"] = thread_id
        out.append(d)
    return out


def service_reply_messages_for_thread(domain: str, thread_id: int) -> list[dict[str, Any]]:
    domain = str(domain or "").strip().lower()
    if domain not in _SERVICE_REPLY_DOMAINS:
        raise ValueError(f"invalid service reply domain: {domain!r}")
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM service_reply_message WHERE domain=? AND thread_id=? "
            "ORDER BY received_at ASC, id ASC",
            (domain, thread_id),
        ).fetchall()
    return [_service_reply_message_row(r) for r in rows]


def service_reply_message_latest_inbound_for_thread(
    domain: str,
    thread_id: int,
) -> dict[str, Any] | None:
    domain = str(domain or "").strip().lower()
    if domain not in _SERVICE_REPLY_DOMAINS:
        raise ValueError(f"invalid service reply domain: {domain!r}")
    with connect() as c:
        row = c.execute(
            "SELECT * FROM service_reply_message "
            "WHERE domain=? AND thread_id=? AND direction='in' "
            "ORDER BY received_at DESC, id DESC LIMIT 1",
            (domain, int(thread_id)),
        ).fetchone()
    return _service_reply_message_row(row) if row is not None else None


def service_reply_message_latest_inbound_after_latest_outbound(
    domain: str,
    thread_id: int,
    *,
    fallback_outbound_at: float | None = None,
) -> dict[str, Any] | None:
    """Return the newest inbound reply newer than the latest sent outbound.

    When no outbound boundary is known, this preserves legacy behavior and
    returns the newest inbound. Callers can pass the report thread `notified_at`
    as the first outbound boundary; later sent service replies supersede it.
    """
    domain = str(domain or "").strip().lower()
    if domain not in _SERVICE_REPLY_DOMAINS:
        raise ValueError(f"invalid service reply domain: {domain!r}")
    outbound_times = [ts for ts in (_float_or_none(fallback_outbound_at),) if ts is not None]
    with connect() as c:
        latest_out = c.execute(
            "SELECT MAX(received_at) AS ts FROM service_reply_message "
            "WHERE domain=? AND thread_id=? AND direction='out' AND agent_verdict='sent'",
            (domain, int(thread_id)),
        ).fetchone()
        if latest_out and latest_out["ts"] is not None:
            ts = _float_or_none(latest_out["ts"])
            if ts is not None:
                outbound_times.append(ts)
        boundary = max(outbound_times) if outbound_times else None
        where = ["domain=?", "thread_id=?", "direction='in'"]
        args: list[Any] = [domain, int(thread_id)]
        if boundary is not None:
            where.append("received_at>?")
            args.append(boundary)
        row = c.execute(
            "SELECT * FROM service_reply_message WHERE " + " AND ".join(where)
            + " ORDER BY received_at DESC, id DESC LIMIT 1",
            args,
        ).fetchone()
    return _service_reply_message_row(row) if row is not None else None


# ============================================================
# token_usage — v3.62 Q5 (LLM 호출 토큰/세그먼트 계측, 분석 전용)
# ============================================================


def domain_entity_timeline(entity_type: str, entity_id: str) -> list[dict[str, Any]]:
    """엔티티(host/domain/url) 하나를 축으로 부서별 테이블을 가로질러 시간순 사건.

    각 이벤트: {ts, source, action, detail, severity}. ts 오름차순 정렬.
    세션 격리와 무관 — 엔티티 단위 cross-table 집계 (H4 의 핵심 가치).
    """
    etype = (entity_type or "").lower().strip()
    eid = (entity_id or "").strip()
    if etype not in ENTITY_TYPES:
        raise ValueError(f"unknown entity_type: {entity_type!r} (allowed: {ENTITY_TYPES})")
    events: list[dict[str, Any]] = []
    with connect() as c:
        if etype == "host":
            for r in c.execute(
                "SELECT share, first_seen, walk_done_at, walk_file_count, "
                "processed_at, severity FROM smb_share WHERE host=? "
                "ORDER BY first_seen",
                (eid,),
            ).fetchall():
                events.append({
                    "ts": r["first_seen"], "source": "smb",
                    "action": "share_discovered",
                    "detail": f"\\\\{eid}\\{r['share']}", "severity": None,
                })
                if r["walk_done_at"] is not None:
                    events.append({
                        "ts": r["walk_done_at"], "source": "smb",
                        "action": "share_walked",
                        "detail": f"{r['share']} ({r['walk_file_count']} files)",
                        "severity": None,
                    })
                if r["processed_at"] is not None:
                    events.append({
                        "ts": r["processed_at"], "source": "smb",
                        "action": "share_triaged",
                        "detail": f"{r['share']} {r['severity'] or ''}".strip(),
                        "severity": r["severity"],
                    })
            for r in c.execute(
                "SELECT h.triaged_at AS ts, h.category, h.kind, h.agent_verdict, "
                "f.path, s.share FROM smb_file_hit h "
                "JOIN smb_file f ON h.file_id=f.id "
                "JOIN smb_share s ON f.share_id=s.id "
                "WHERE s.host=? AND h.triaged_at IS NOT NULL",
                (eid,),
            ).fetchall():
                events.append({
                    "ts": r["ts"], "source": "smb",
                    "action": f"hit_{r['agent_verdict']}",
                    "detail": f"{r['category']}/{r['kind']} @ {r['share']}/{r['path']}",
                    "severity": None,
                })
            _timeline_findings(c, f"{eid}%", events)
        elif etype == "domain":
            for r in c.execute(
                "SELECT discovered_at, last_task_at, day_bucket, status "
                "FROM web_target_domain WHERE domain=? ORDER BY discovered_at",
                (eid,),
            ).fetchall():
                events.append({
                    "ts": r["discovered_at"], "source": "web",
                    "action": "domain_discovered",
                    "detail": f"{eid} ({r['day_bucket']})", "severity": None,
                })
                if r["last_task_at"] is not None:
                    events.append({
                        "ts": r["last_task_at"], "source": "web",
                        "action": "domain_tasked",
                        "detail": f"{eid} status={r['status']}", "severity": None,
                    })
            _timeline_findings(c, f"%{eid}%", events)
        else:  # url (devops)
            for r in c.execute(
                "SELECT discovered_at, last_task_at, service, status "
                "FROM devops_target WHERE url=? ORDER BY discovered_at",
                (eid,),
            ).fetchall():
                events.append({
                    "ts": r["discovered_at"], "source": "devops",
                    "action": "target_discovered",
                    "detail": f"{r['service']}: {eid}", "severity": None,
                })
                if r["last_task_at"] is not None:
                    events.append({
                        "ts": r["last_task_at"], "source": "devops",
                        "action": "target_tasked",
                        "detail": f"{eid} status={r['status']}", "severity": None,
                    })
            _timeline_findings(c, f"%{eid}%", events)
    events.sort(key=lambda e: (e["ts"] if e["ts"] is not None else 0.0))
    return events


# ============================================================
# SMB E2E 파이프라인 — collector reclaim / control_flag / heartbeat / run
# ============================================================

# LLM-free 러너는 chat_session row 가 없어 기존 smb_reclaim_stale_host_claims
# (archived session 기준)가 회수 못 한다 → sentinel claimed_by + 순수 시간기반 회수.
COLLECTOR_CLAIM_STALE_SECONDS = 3600  # walk 1 host 가 이만큼 묵으면 crash 로 보고 회수


def smb_collector_reclaim_stale(
    *, stale_seconds: float = COLLECTOR_CLAIM_STALE_SECONDS,
) -> int:
    """collector sentinel 이 물고 죽은 smb_share host claim 을 시간기반으로 회수.

    chat_session 이 없는 코드 러너 전용 — crash 시 큐 영구 점유 방지.
    """
    cutoff = time.time() - stale_seconds
    with connect() as c:
        r = c.execute(
            "UPDATE smb_share SET status='pending', claimed_by=NULL, claimed_at=NULL "
            "WHERE status='in_progress' AND claimed_by=? "
            "AND (claimed_at IS NULL OR claimed_at < ?)",
            (COLLECTOR_SESSION_ID, cutoff),
        )
        return r.rowcount


# ---- control_flag (cron on/off · 수동 실행) ----

def control_flag_get(component: str) -> dict[str, Any]:
    """component 의 제어 플래그. 없으면 기본값(enabled=1, run_now=0)으로 생성 후 반환."""
    now = time.time()
    with connect() as c:
        row = c.execute(
            "SELECT * FROM control_flag WHERE component=?", (component,),
        ).fetchone()
        if row is None:
            c.execute(
                "INSERT INTO control_flag(component, enabled, run_now, updated_at) "
                "VALUES (?, 1, 0, ?) ON CONFLICT(component) DO NOTHING",
                (component, now),
            )
            row = c.execute(
                "SELECT * FROM control_flag WHERE component=?", (component,),
            ).fetchone()
    if row is None:
        return {
            "component": component,
            "enabled": 1,
            "run_now": 0,
            "interval_seconds": None,
            "updated_by": None,
            "updated_at": now,
        }
    return {k: row[k] for k in row.keys()}


def control_flag_set(
    component: str, *,
    enabled: bool | None = None,
    run_now: bool | None = None,
    interval_seconds: float | None = None,
    updated_by: str | None = None,
) -> dict[str, Any]:
    control_flag_get(component)  # ensure row exists
    sets: list[str] = ["updated_at=?"]
    args: list[Any] = [time.time()]
    if enabled is not None:
        sets.append("enabled=?")
        args.append(1 if enabled else 0)
    if run_now is not None:
        sets.append("run_now=?")
        args.append(1 if run_now else 0)
    if interval_seconds is not None:
        sets.append("interval_seconds=?")
        args.append(float(interval_seconds))
    if updated_by is not None:
        sets.append("updated_by=?")
        args.append(updated_by)
    args.append(component)
    with connect() as c:
        c.execute(
            f"UPDATE control_flag SET {', '.join(sets)} WHERE component=?", args,
        )
    return control_flag_get(component)


def control_flag_consume_run_now(component: str) -> bool:
    """run_now 를 atomic 하게 1→0 소비. 소비됐으면(=수동 실행 트리거) True."""
    with connect() as c:
        r = c.execute(
            "UPDATE control_flag SET run_now=0, updated_at=? "
            "WHERE component=? AND run_now=1",
            (time.time(), component),
        )
        return r.rowcount > 0


# ---- pipeline_heartbeat (liveness) ----

def heartbeat_upsert(
    component: str, *, phase: str | None = None,
    detail: str | None = None, pid: int | None = None,
) -> None:
    now = time.time()
    with connect() as c:
        c.execute(
            "INSERT INTO pipeline_heartbeat(component, phase, detail, pid, last_beat) "
            "VALUES (?, ?, ?, ?, ?) ON CONFLICT(component) DO UPDATE SET "
            "phase=excluded.phase, detail=excluded.detail, pid=excluded.pid, "
            "last_beat=excluded.last_beat",
            (component, phase, detail, pid, now),
        )


def heartbeats_all() -> list[dict[str, Any]]:
    with connect() as c:
        rows = c.execute(
            "SELECT * FROM pipeline_heartbeat ORDER BY component",
        ).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]


# ---- pipeline_run (cycle 스냅샷) ----

def pipeline_run_start(component: str) -> int:
    with connect() as c:
        cur = c.execute(
            "INSERT INTO pipeline_run(component, started_at, status) "
            "VALUES (?, ?, 'running')",
            (component, time.time()),
        )
        return int(cur.lastrowid)


def pipeline_run_finish(
    run_id: int, *, status: str = "ok",
    subnets_swept: int = 0, hosts_found: int = 0, shares_found: int = 0,
    shares_walked: int = 0, owners_enriched: int = 0, detail: str | None = None,
) -> None:
    with connect() as c:
        c.execute(
            "UPDATE pipeline_run SET finished_at=?, status=?, subnets_swept=?, "
            "hosts_found=?, shares_found=?, shares_walked=?, owners_enriched=?, "
            "detail=? WHERE id=?",
            (time.time(), status, subnets_swept, hosts_found, shares_found,
             shares_walked, owners_enriched, detail, run_id),
        )


def pipeline_runs_recent(component: str | None = None, *, limit: int = 20) -> list[dict[str, Any]]:
    where = ""
    args: list[Any] = []
    if component is not None:
        where = "WHERE component=?"
        args.append(component)
    args.append(max(1, min(int(limit), 200)))
    with connect() as c:
        rows = c.execute(
            f"SELECT * FROM pipeline_run {where} ORDER BY started_at DESC LIMIT ?",
            args,
        ).fetchall()
    return [{k: r[k] for k in r.keys()} for r in rows]


